	[708] = {708, "Invocation d'élémentaires", [[ En passant de la forme pure à la forme impure, Hydross invoque quatre élémentaires impurs pour l'aider. ]], 0, 0, 38235, 1567, 0, 709, 705, 0, 0, 3, 2, -1, 0},
