	[710] = {710, "Berserk", [[ Après 10 minutes de combat, Hydross augmente sa vitesse de déplacement de 150% et ses dégâts infligés de 500% pendant 600 min. ]], 0, 0, 27680, 1567, 0, 0, 0, 0, 0, 3, 2, -1, 0},    [711] = {711, "Водяная стрела", [[ Выстрел в противника водяной стрелой, наносящей $[4 20057$]$[2 86469$]$[1 22286$] ед. урона от магии льда. Используется Скрытнем только в том случае, если он не может атаковать противника в ближнем бою. ]], 0, 0, 37138, 1568, 712, 0, 0, 0, 0, 3, 2, -1, 0},
	[711] = {711, "Flèche aqueuse", [[ Tire une flèche d'eau sur l'ennemi, infligeant $[4 20057$]$[2 86469$]$[1 22286$] points de dégâts de givre. Utilisé par le Traqueur uniquement lorsqu'il ne peut pas attaquer en mêlée. ]], 0, 0, 37138, 1568, 712, 0, 0, 0, 0, 3, 2, -1, 0},
