    [783] = {783, "Phase 2 : Le moment est venu ! N'épargnez personne !", [[ Lorsque ses points de vie tombent à 70%, Dame Vashj se replie au centre de l'arène et active des barrières magiques. Pendant cette phase, elle utilise continuellement la foudre pour frapper ses ennemis, tandis que des serviteurs viennent l'aider. ]], 0, 0, 0, 1572, 798, 784, 0, 0, 0, 2, 2, -1, 0},
    [784] = {784, "Barrière magique", [[ Invulnérabilité à toutes les attaques et tous les sorts. La barrière est alimentée par quatre générateurs pouvant être désactivés à l'aide de la 'Magma corrompu'. ]], 0, 0, 38112, 1572, 785, 0, 783, 0, 0, 3, 2, -1, 0},
    [785] = {785, "Éclair fourchu", [[ Inflige $[4 2124$]$[2 9156$]$[1 2360$] points de dégâts de nature aux ennemis situés dans un secteur devant le lanceur de sorts. ]], 0, 0, 38145, 1572, 786, 0, 783, 0, 0, 3, 2, -1, 0},
    [786] = {786, "Élémentaire enchanté", [[ Des élémentaires enchantés surgissent de l'eau et se dirigent vers Dame Vashj. Chaque élémentaire qui l'atteint lui confère l'effet 'Décharge'. L'élémentaire se dirigera vers sa cible coûte que coûte. ]], 20076, 0, 0, 1572, 788, 787, 783, 1, 0, 4, 2, -1, 21958},
