    [788] = {788, "Élémentaire impur", [[ Toutes les 60 sec., l'un des élémentaires enchantés apparus sera remplacé par un 'Élémentaire impur', qui disparaîtra après 15 secondes s'il n'est pas tué avant. ]], 11172, 0, 0, 1572, 792, 789, 783, 1, 0, 4, 2, -1, 22009},
    [789] = {789, "Frappe empoisonnée", [[ Inflige $[4 1843$]$[2 7946$]$[1 2048$] dégâts de nature, puis $[4 1800$]$[2 7760$]$[1 2000$] dégâts supplémentaires toutes les 4 sec. pendant 8 sec. ]], 0, 0, 38253, 1572, 791, 0, 788, 0, 0, 3, 2, -1, 0},
    [791] = {791, "Magma corrompu", [[ En mourant, l'élémentaire impur laisse derrière lui du 'Magma corrompu'. Le joueur qui ramasse le magma est paralysé et ne peut plus se déplacer, mais peut le lancer à un allié proche. Le magma corrompu peut être utilisé sur un générateur magique, ce qui entraîne sa désactivation complète - il faut pour cela avoir le magma corrompu dans son inventaire et se trouver à proximité du générateur. ]], 0, 0, 38132, 1572, 0, 0, 788, 0, 0, 3, 2, -1, 0},
    [792] = {792, "Rôdeur du bassin de Croc-Tordu", [[ À l'appel de Dame Vashj vient l'un des monstres de Zangartopi, dressé par les naga. Le rôdeur est vulnérable aux effets de ralentissement, mais inflige d'énormes dégâts physiques au corps à corps. ]], 18194, 0, 0, 1572, 795, 793, 783, 1, 0, 4, 2, -1, 22056},
