    [794] = {794, "Explosion mentale", [[ Frappe l'esprit de la cible, infligeant $[4 2214$]$[2 9544$]$[1 2460$] points de dégâts de magie noire. ]], 0, 0, 38259, 1572, 0, 0, 792, 0, 0, 3, 2, -1, 0},
