    [797] = {797, "Trancher les tendons", [[ Inflige à l'ennemi des dégâts d'arme ainsi que 20 points de dégâts physiques supplémentaires, et réduit sa vitesse de déplacement de 60% pendant 10 sec. ]], 0, 0, 38262, 1572, 0, 0, 795, 0, 0, 3, 2, -1, 0},
