    [810] = {810, "Braises explosives", [[ En mourant, les braises explosent, infligeant $[4 30424$]$[2 28634$]$[1 7380$] points de dégâts de feu à tous les ennemis dans un rayon de 15 m. La mort d'une 'Braise d'Alar' inflige également des dégâts au dieu-phénix équivalents à 3% de ses points de vie maximum. ]], 0, 0, 34133, 1573, 0, 0, 809, 0, 0, 3, 2, -1, 0},
    [811] = {811, "Phase 2 : Renaissance", [[ Alar périt en s'écrasant sur le niveau inférieur de l'arène, puis renaît, retrouvant 100% de ses points de vie. Jusqu'à la fin du combat, il attaquera les ennemis au corps à corps en les poursuivant. ]], 0, 0, 0, 1573, 0, 812, 0, 0, 0, 2, 2, -1, 0},
    [812] = {812, "Charge", [[ Alar charge un ennemi aléatoire, lui infligeant des dégâts normaux augmentés de $[4 21280$]$[2 20028$]$[1 5162$] points et l'étourdissant pendant 3 sec. ]], 0, 0, 35412, 1573, 813, 0, 811, 0, 0, 3, 2, -1, 0},
