    [819] = {819, "Coup lourd", [[ Le gardien de l'abîme déchaîne une grêle de coups, faisant trembler le sol. Chaque coup inflige à tous les ennemis proches $[4 17553$]$[2 16521$]$[1 4258$] points de dégâts occultes. ]], 0, 0, 34162, 1574, 820, 0, 0, 0, 0, 3, 2, -1, 0},
