    [866] = {866, "Bond", [[ Téléporte le lanceur de sorts de 20 mètres vers l'avant, si rien ne bloque le passage. Libère le lanceur de sorts des effets d'immobilisation. ]], 0, 0, 36994, 1575, 867, 0, 865, 0, 0, 3, 2, -1, 0},
