    [868] = {868, "Volée", [[ Fait s'abattre une pluie de projectiles sur l'ennemi et ses alliés proches, touchant jusqu'à 10 cibles et leur infligeant $[4 17953$]$[2 16897$]$[1 4355$] points de dégâts supplémentaires. ]], 0, 0, 36979, 1575, 0, 0, 865, 0, 0, 3, 2, -1, 0},
    [869] = {869, "Phase 3 : Je ne fais que rendre la pareille.", [[ 2 minutes après l'invocation des armes enchantées, Kael'thas ranime ses conseillers, doublant leurs points de vie. La phase se termine après 3 minutes, ou lorsque les quatre conseillers sont à nouveau vaincus. ]], 0, 0, 0, 1575, 883, 870, 0, 0, 0, 2, 2, -1, 0},
    [870] = {870, "Taladred Voleur de lumière", [[ Guerrier armé d'une hache à deux mains, poursuivant des ennemis choisis au hasard et changeant de cible de temps à autre. ]], 20236, 0, 0, 1575, 874, 871, 869, 1, 0, 4, 2, -1, 20064},
