    [877] = {877, "Boule de feu", [[ Inflige à l'ennemi $[4 29319$]$[2 27594$]$[1 7112$] dégâts de feu. ]], 0, 0, 36971, 1575, 878, 0, 876, 0, 0, 3, 2, -1, 0},
    [878] = {878, "Embrasement", [[ Enflamme l'ennemi, lui infligeant $[4 111431$]$[2 104876$]$[1 27030$] points de dégâts de feu sur 10 sec. et le plongeant dans la panique. Tant que la cible brûle, les flammes brûlent périodiquement ses alliés proches, infligeant $[4 1236$]$[2 1164$]$[1 300$] points de dégâts. ]], 0, 0, 37018, 1575, 879, 0, 876, 0, 0, 3, 2, -1, 0},
