    [880] = {880, "Ingénieur en chef Telonicus", [[ Ingénieur utilisant des capacités dangereuses issues de ses inventions et combattant au corps à corps. ]], 20177, 0, 0, 1575, 0, 881, 869, 1, 0, 4, 2, -1, 20063},
    [881] = {881, "Bombe", [[ Bombarde tous les ennemis dans la zone choisie, infligeant $[4 34237$]$[2 32223$]$[1 8305$] dégâts de feu. ]], 0, 0, 37036, 1575, 882, 0, 880, 0, 0, 3, 2, -1, 0},
    [882] = {882, "Jouet télécommandé", [[ Un appareil télécommandé frappe la cible, l'étourdissant périodiquement pendant 60 sec. ]], 0, 0, 37027, 1575, 0, 0, 880, 0, 0, 3, 2, -1, 0},
    [883] = {883, "Phase 4 : Kael'thas le Voyageur du Soleil", [[ Kael'thas entre lui-même dans le combat, combattant à la fois au corps à corps et à l'aide de sorts. ]], 20023, 0, 0, 1575, 896, 884, 0, 1, 0, 4, 2, -1, 19622},
