    [886] = {886, "Frappe de flamme", [[ Une colonne de flammes brûle tous les ennemis dans la zone choisie et inflige des dégâts de feu supplémentaires toutes les 1 sec. pendant 8 sec. ]], 0, 0, 36731, 1575, 887, 0, 883, 0, 0, 3, 2, -1, 0},
    [887] = {887, "Barrière de choc", [[ Un bouclier de magie occulte entoure le lanceur de sorts, le rendant insensible aux interruptions. Cette barrière absorbe $[4 329799$]$[2 310400$]$[1 80000$] points de dégâts et dure 10 sec. Une fois cette barrière activée, Kael'thas utilisera 'Bloc de feu'. ]], 0, 0, 36815, 1575, 888, 0, 883, 0, 0, 3, 2, -1, 0},
