    [889] = {889, "Contrôle mental", [[ Kael'thas soumet plusieurs ennemis à sa volonté. Augmente de 100% les dégâts infligés par les ennemis contrôlés, de 50% leur vitesse de déplacement et de 1000% l'efficacité des soins qu'ils prodiguent. ]], 0, 0, 36797, 1575, 890, 0, 883, 0, 0, 3, 2, -1, 0},
