    [891] = {891, "Phénix", [[ L'un des jeunes phénix apparaît sur le champ de bataille, attaquant les ennemis de Kael'thas. ]], 17765, 0, 0, 1575, 0, 892, 890, 1, 0, 4, 2, -1, 21362},
    [892] = {892, "Flamme ardente", [[ Inflige $[4 113929$]$[2 107227$]$[1 27636$] points de dégâts de feu à tous les ennemis dans un rayon de 8 m, toutes les 2 sec. ]], 0, 0, 36721, 1575, 893, 0, 891, 0, 0, 3, 2, -1, 0},
    [893] = {893, "Braises ardentes", [[ Inflige $[4 40598$]$[2 38210$]$[1 9848$] points de dégâts de feu à tous les ennemis dans un rayon de 8 m à sa mort, les repoussant en arrière. ]], 0, 0, 34341, 1575, 894, 0, 891, 0, 0, 3, 2, -1, 0},
    [894] = {894, "Œuf de phénix", [[ Après sa mort, le phénix se transforme en œuf, qui renaîtra en phénix après 15 sec. s'il n'est pas détruit. ]], 20245, 0, 0, 1575, 0, 895, 891, 1, 0, 4, 2, -1, 21364},
	[895] = {895, "Renaissance", [[ Le phénix renaît dans une explosion de flammes, infligeant $[4 18538$]$[2 17448$]$[1 4497$] points de dégâts de feu à tous les ennemis dans un rayon de 8 m, les repoussant en arrière. ]], 0, 0, 41587, 1575, 0, 0, 894, 0, 0, 3, 2, -1, 0},
    [896] = {896, "Phase 5 : Pouvoir du Néant tourbillonnant", [[ Lorsque ses points de vie tombent à 50%, Kael'thas entre en rage, absorbant les énergies chaotiques du néant tourbillonnant et entamant la phase finale du combat. ]], 20023, 0, 0, 1575, 0, 897, 0, 1, 0, 4, 2, -1, 19622},
