    [899] = {899, "Frappe de flamme", [[ Une colonne de flammes brûle tous les ennemis dans la zone choisie et inflige des dégâts de feu supplémentaires toutes les 1 sec. pendant 8 sec. ]], 0, 0, 36731, 1575, 689, 0, 896, 0, 0, 3, 2, -1, 0},
    [900] = {900, "Dame Jaina Portvaillant", [[ Au sommet de la Citadelle de la Couronne de Glace, après la victoire sur le Roi-liche, les héros d'Azeroth doivent affronter Dame Jaina Portvaillant. Ce combat n'est accessible qu'en version héroïque du raid à 25 joueurs. ]], 30864, 0, 0, 1637, 0, 901, 0, 1, 0, 1, 0, -1, 200000},
    [901] = {901, "Phase 1 : Le pouvoir de la magie occulte.", [[ Dame Jaina Portvaillant ouvre plusieurs portails de magie occulte, qui invoquent des serviteurs et lui transmettent de l'énergie. Cette phase dure jusqu'à ce que les 4 portails soient fermés. ]], 0, 0, 306445, 1637, 920, 902, 900, 0, 0, 2, 2, -1, 0},
    [902] = {902, "Portails de magie occulte", [[ Crée des portails de magie occulte qui génèrent périodiquement des amas de magie. ]], 0, 0, 306445, 1637, 909, 903, 901, 32, 0, 3, 2, -1, 0},
    [903] = {903, "Transfert d'énergie", [[ Chaque portail actif restaure à Jaina 3% de ses points de vie maximum toutes les 30 sec. ]], 0, 0, 306446, 1637, 904, 0, 902, 32, 0, 4, 2, -1, 0},
    [904] = {904, "Drainage de mana", [[ Lorsqu'il est détruit, le portail draine l'énergie de Jaina, retirant toutes les charges de l'effet 'Flot ensorcelé'. ]], 0, 0, 306447, 1637, 905, 0, 902, 32, 0, 4, 2, -1, 0},
    [905] = {905, "Formation de magie", [[ Chaque portail actif invoque périodiquement un amas de magie. ]], 0, 0, 306448, 1637, 0, 906, 902, 1, 0, 4, 2, -1, 0},
    [906] = {906, "Amas de magie", [[ Incarnation de la magie, élémentaire combattant aux côtés de Jaina Portvaillant. ]], 26259, 0, 0, 1637, 0, 907, 905, 1, 0, 4, 2, -1, 130509},
    [907] = {907, "Brûlure magique", [[ En infligeant des dégâts, il y a 50% de chances de frapper l'ennemi d'une 'Brûlure magique', augmentant de 2500 points les dégâts physiques qu'il subit pendant 20 sec. Cet effet se cumule. ]], 0, 0, 306450, 1637, 908, 0, 906, 33, 0, 4, 2, -1, 0},
    [908] = {908, "Magie résiduelle", [[ En mourant, crée une sphère de magie que peut absorber un élémentaire magique. ]], 0, 0, 306452, 1637, 0, 0, 906, 32, 0, 4, 2, -1, 0},
    [909] = {909, "Invocation d'un élémentaire", [[ Dame Jaina invoque un Destructeur d'ensorcellement pour l'aider au combat. ]], 0, 0, 306454, 1637, 914, 910, 901, 17, 0, 4, 2, -1, 0},
    [910] = {910, "Destructeur d'ensorcellement", [[ Puissant élémentaire combattant aux côtés de Jaina Portvaillant. ]], 14252, 0, 0, 1637, 0, 911, 909, 17, 0, 4, 2, -1, 130510},
    [911] = {911, "Condensateur de magie", [[ Au contact, absorbe une sphère de magie occulte, augmentant les dégâts infligés de 20% par charge. ]], 0, 0, 306455, 1637, 912, 0, 910, 32, 0, 4, 2, -1, 0},
    [912] = {912, "Décharge occulte", [[ Une fois que le Destructeur d'ensorcellement a accumulé 15 charges de l'effet 'Condensateur de magie', sa structure commence à se déstabiliser, ce qui provoque périodiquement des décharges de magie occulte, infligeant $[1 5400$]$[2 6750$]$[3 6750$]$[4 6750$] points de dégâts occultes à tous les ennemis dans un rayon de 200 m. ]], 0, 0, 306456, 1637, 913, 0, 910, 48, 0, 4, 2, -1, 0},
    [913] = {913, "Implosion", [[ Une fois que le Destructeur d'ensorcellement, ayant accumulé 15 charges de l'effet 'Condensateur de magie', se désintègre, une explosion de magie occulte se produit, infligeant $[1 12000$]$[2 15000$]$[3 15000$]$[4 15000$] points de dégâts occultes à tous les ennemis dans un rayon de 200 m. Détruit instantanément un 'Portail de magie occulte'. ]], 0, 0, 306458, 1637, 0, 0, 910, 48, 0, 4, 2, -1, 0},
    [914] = {914, "Éclat occulte", [[ Dame Jaina frappe l'ennemi d'une charge d'énergie, lui infligeant $[1 55800$]$[2 69750$]$[3 69750$]$[4 69750$] points de dégâts occultes. Chaque lancer de 'Éclat occulte' augmente de 2% tous les dégâts infligés par les sorts occultes. Cet effet se cumule. ]], 0, 0, 306459, 1637, 916, 915, 901, 4, 0, 4, 2, -1, 0},
    [915] = {915, "Flot ensorcelé", [[ Augmente de 2% tous les dégâts infligés par les sorts occultes. ]], 0, 0, 306460, 1637, 0, 0, 914, 2048, 0, 4, 2, -1, 0},
    [916] = {916, "Annihilateur magique", [[ Après chaque troisième lancer de 'Éclat occulte', Dame Jaina inflige $[1 12000$]$[2 15000$]$[3 15000$]$[4 15000$] points de dégâts occultes à 6 ennemis choisis au hasard. ]], 0, 0, 306461, 1637, 917, 0, 901, 16, 0, 4, 2, -1, 0},
    [917] = {917, "Flèches d'ensorcellement", [[ Libère pendant 3 sec. des flèches d'ensorcellement sur l'ennemi, infligeant $[1 25800$]$[2 32250$]$[3 32250$]$[4 32250$] points de dégâts occultes toutes les 0.5 sec. ]], 0, 0, 306462, 1637, 918, 0, 901, 0, 0, 4, 2, -1, 0},
    [918] = {918, "Tempête d'ensorcellement", [[ Dame Jaina Portvaillant se téléporte et entretient une tempête de magie occulte autour d'elle pendant les 10 sec. suivantes. Tous les ennemis subissent $[1 4500$]$[2 5625$]$[3 5625$]$[4 5625$] points de dégâts occultes toutes les 1 sec. et infligent les mêmes dégâts à leurs alliés dans un rayon de 6 m. ]], 0, 0, 306464, 1637, 919, 0, 901, 20, 0, 4, 2, -1, 0},
    [919] = {919, "Magie instable", [[ Perturbe la magie de tous les ennemis. La prochaine capacité lancée par un ennemi dans les 10 sec. verra son temps de recharge allongé de 10 sec. ]], 0, 0, 306468, 1637, 0, 0, 901, 32, 0, 4, 2, -1, 0},
    [920] = {920, "Phase 2 : Renaissance dans le feu.", [[ Dame Jaina Portvaillant tente d'en finir avec ses ennemis à l'aide d'un sort dévastateur, mais Tirion l'en empêche. Durant cette phase, Jaina utilise une série de capacités destructrices de magie de feu. Cette phase dure jusqu'à ce que les points de vie de Dame Jaina Portvaillant atteignent 50%. ]], 0, 0, 306483, 1637, 930, 921, 900, 0, 0, 2, 2, -1, 0},
    [921] = {921, "Rayons incinérants", [[ Crée des sphères de feu d'où jaillissent de puissants jets de flammes, repoussant tous les ennemis en arrière et leur infligeant $[1 72000$]$[2 90000$]$[3 90000$]$[4 90000$] points de dégâts de feu instantanément, puis $[1 6000$]$[2 7500$]$[3 7500$]$[4 7500$] points de dégâts de feu toutes les 2.5 sec. pendant 10 sec. ]], 0, 0, 306485, 1637, 922, 0, 920, 16, 0, 3, 2, -1, 0},
    [922] = {922, "Flamme explosive", [[ Frappe jusqu'à 6 cibles de flammes qui explosent après 6 sec., infligeant $[1 12000$]$[2 15000$]$[3 15000$]$[4 15000$] points de dégâts de feu dans un rayon de 5 m et enflammant le sol dans un rayon de 3 m. Le sol enflammé inflige $[1 18000$]$[2 22500$]$[3 22500$]$[4 22500$] points de dégâts de feu toutes les 2 sec. ]], 0, 0, 306487, 1637, 924, 923, 920, 48, 0, 4, 2, -1, 0},
    [923] = {923, "Sol enflammé", [[ Inflige $[1 18000$]$[2 22500$]$[3 22500$]$[4 22500$] points de dégâts de feu toutes les 2 sec. dans un rayon de 3 m. ]], 0, 0, 306489, 1637, 0, 0, 922, 0, 0, 4, 2, -1, 0},
    [924] = {924, "Pluie de météores", [[ Invoque du ciel 4 météores qui, après 4 sec., s'écrasent sur la plateforme, infligeant $[1 90000$]$[2 112500$]$[3 112500$]$[4 112500$] points de dégâts de feu répartis entre toutes les cibles touchées dans un rayon de 8 m, et augmentant de 100% pendant 45 sec. les dégâts subis par ce sort chez les ennemis touchés. Cet effet se cumule. Si un météore ne touche aucun joueur, une 'Implosion colossale' se produit. ]], 0, 0, 306491, 1637, 926, 925, 920, 16, 0, 4, 2, -1, 0},
	[925] = {925, "Implosion colossale", [[ Inflige $[1 42000$]$[2 52500$]$[3 52500$]$[4 52500$] points de dégâts de feu à tous les ennemis et augmente de 25% tous les dégâts de feu subis pendant 120 min. Cet effet se cumule. ]], 0, 0, 306494, 1637, 0, 0, 924, 4096, 0, 4, 2, -1, 0},
    [926] = {926, "Tourbillon de feu", [[ Absorbe tous les feux existants créés par l'effet 'Flamme explosive', les transformant en comète et infligeant $[1 12000$]$[2 15000$]$[3 15000$]$[4 15000$] points de dégâts de feu toutes les 3 sec. Les feux créés par l'effet 'Flamme explosive' brûlent les ennemis, augmentant de 100% les dégâts de feu qu'ils subissent. Utilise 'Effondrement' une fois tout le feu absorbé. ]], 0, 0, 306495, 1637, 928, 927, 920, 32, 0, 4, 2, -1, 0},
    [927] = {927, "Effondrement", [[ Provoque l'explosion de la comète. Des fragments de comète volent vers tous les ennemis, infligeant $[1 39000$]$[2 48750$]$[3 48750$]$[4 48750$] points de dégâts de feu et les repoussant de 10 m. ]], 0, 0, 306500, 1637, 0, 0, 926, 4096, 0, 4, 2, -1, 0},
    [928] = {928, "Feu sauvage", [[ Enflamme 3 ennemis, leur infligeant $[1 7200$]$[2 9000$]$[3 9000$]$[4 9000$] points de dégâts de feu toutes les 1 sec. pendant 6 sec. Toutes les 3 sec., les flammes se propagent aux alliés proches. ]], 0, 0, 306502, 1637, 929, 0, 920, 16, 0, 4, 2, -1, 0},
    [929] = {929, "Boule de feu", [[ Lance sur l'ennemi un bloc de feu, infligeant instantanément $[1 48000$]$[2 60000$]$[3 60000$]$[4 60000$] points de dégâts de feu, puis $[1 12000$]$[2 15000$]$[3 15000$]$[4 15000$] points de dégâts supplémentaires toutes les 1 sec. pendant 15 sec. ]], 0, 0, 306504, 1637, 0, 0, 920, 5, 0, 4, 2, -1, 0},
    [930] = {930, "Phase 3 : Glace noire", [[ Dame Jaina Portvaillant, affaiblie et désespérée, gèle Tirion et absorbe le pouvoir caché dans l'éclat de la Couronne de Glace. À partir de cet instant, il n'y a plus de retour possible pour elle, et les forces de la glace et des ténèbres écraseront ses ennemis. ]], 0, 0, 306516, 1637, 0, 931, 900, 0, 0, 2, 2, -1, 0},
    [931] = {931, "Froid glacial", [[ Certaines capacités de Jaina gèlent l'ennemi, réduisant de 4% par charge de l'effet l'efficacité des soins qu'il reçoit. ]], 0, 0, 306518, 1637, 932, 0, 930, 32, 0, 4, 2, -1, 0},
    [932] = {932, "Flèche de glace noire", [[ Le lanceur de sorts crée un immense glaçon qui transperce la cible, lui infligeant instantanément $[1 34200$]$[2 42750$]$[3 42750$]$[4 42750$] points de dégâts de givre, puis $[1 9000$]$[2 11250$]$[3 11250$]$[4 11250$] points de dégâts de magie noire toutes les 0.5 sec. pendant 2 sec. Chaque troisième lancer de ce sort confère à la cible une charge de l'effet 'Froid glacial' et inflige $[1 14400$]$[2 18000$]$[3 18000$]$[4 18000$] points de dégâts de givre à tous les ennemis dans un rayon de 10 m. ]], 0, 0, 306520, 1637, 933, 0, 930, 32, 0, 4, 2, -1, 0},
    [933] = {933, "Marque de glace", [[ Marque 6 ennemis, ralentissant la cible de 10% toutes les 1 sec. À la fin de la marque, la cible est enfermée dans un bloc de glace, subissant des dégâts de magie noire équivalents à 5% de ses points de vie maximum toutes les 1 sec., jusqu'à ce que le bloc soit détruit. ]], 0, 0, 306523, 1637, 934, 0, 930, 4096, 0, 4, 2, -1, 0},
    [934] = {934, "Rayon glaciaire", [[ Se concentre sur la cible actuelle et, après 4 sec., déclenche et maintient un rayon infligeant $[1 36000$]$[2 45000$]$[3 45000$]$[4 45000$] points de dégâts de givre toutes les 0.3 sec. à tous les ennemis situés sur une ligne droite. Le rayon gèle le sol, créant des zones de 'Sol gelé'. ]], 0, 0, 306528, 1637, 936, 935, 930, 16, 0, 4, 2, -1, 0},
    [935] = {935, "Sol gelé", [[ Réduit la vitesse de déplacement de 85%, inflige $[1 18000$]$[2 22500$]$[3 22500$]$[4 22500$] points de dégâts de givre toutes les 3 sec. et applique 'Froid glacial' toutes les 1.5 sec. ]], 0, 0, 306530, 1637, 0, 0, 934, 0, 0, 4, 2, -1, 0},
    [936] = {936, "Assaut de glace", [[ Crée des sphères de glace qui se dispersent dans toutes les directions. Au contact d'un ennemi, la sphère de glace explose, infligeant $[1 27000$]$[2 33750$]$[3 33750$]$[4 33750$] points de dégâts de givre à tous les ennemis. ]], 0, 0, 306531, 1637, 937, 0, 930, 16, 0, 4, 2, -1, 0},
    [937] = {937, "Blizzard vengeur", [[ Crée un blizzard au-dessus de 2 ennemis, qui dure 6 sec. Tous les ennemis dans un rayon de 13 m des cibles de cette capacité subissent $[1 6420$]$[2 8025$]$[3 8025$]$[4 8025$] points de dégâts de givre toutes les 1 sec. Si la cible de cette capacité meurt, le 'Blizzard vengeur' se déplace vers l'ennemi le plus proche, en renouvelant sa durée. ]], 0, 0, 306535, 1637, 938, 0, 930, 16, 0, 4, 2, -1, 0},
    [938] = {938, "Lances de glace noire", [[ Crée $[1 4$]$[2 6$]$[3 6$]$[4 6$] lances de glace noire qui, après un moment, volent vers le lanceur de sorts et infligent $[1 30000$]$[2 37500$]$[3 37500$]$[4 37500$] points de dégâts de givre noir au premier ennemi rencontré. Chaque lance suivante inflige 25% de dégâts supplémentaires. Si les lances touchent Jaina, elle reçoit l'effet 'Croûte de glace'. ]], 0, 0, 306537, 1637, 940, 939, 930, 34, 0, 4, 2, -1, 0},
    [939] = {939, "Croûte de glace", [[ Augmente de 10% les dégâts infligés par Jaina et réduit de 2% les dégâts qu'elle subit. ]], 0, 0, 306541, 1637, 0, 0, 936, 2048, 0, 4, 2, -1, 0},
    [940] = {940, "Image de glace", [[ Unissant le pouvoir de la glace et de la magie occulte, Jaina crée une image animée qui lance des sorts et combat pour sa maîtresse. ]], 50482, 0, 306542, 1637, 942, 941, 930, 32, 0, 4, 2, -1, 130511},
    [941] = {941, "Boule de glace", [[ Crée une boule de glace puis la lance sur l'ennemi, infligeant à lui et à tous ses alliés dans un rayon de 5 m $[1 18000$]$[2 22500$]$[3 22500$]$[4 22500$] points de dégâts de givre et appliquant l'effet 'Froid glacial'. ]], 0, 0, 306543, 1637, 0, 0, 940, 64, 0, 4, 2, -1, 0},
    [942] = {942, "Fureur glaciale", [[ Entretient une tempête de glace. La tempête inflige à tous les ennemis dans son rayon d'action $[1 24000$]$[2 30000$]$[3 30000$]$[4 30000$] points de dégâts de givre, applique l'effet 'Froid glacial' et protège Jaina de tous les dégâts. ]], 0, 0, 306545, 1637, 0, 943, 930, 4096, 0, 4, 2, -1, 0},
    [943] = {943, "Catalyseurs de glace noire", [[ Sept catalyseurs de glace noire apparaissent dans l'arène, entretenant l'effet de 'Fureur glaciale'. ]], 48947, 0, 306546, 1637, 945, 944, 942, 32, 0, 4, 2, -1, 200007},
    [944] = {944, "Vague de terreur", [[ Émet une vague de terreur, forçant tous ceux qui la regardent à fuir dans la panique pendant 4 sec. ]], 0, 0, 306547, 1637, 0, 0, 943, 2, 0, 4, 2, -1, 0},
    [945] = {945, "Pics de glace noire", [[ Crée 4 bandes de glace noire équidistantes, se déplaçant lentement. Les pics de glace noire infligent $[1 30000$]$[2 37500$]$[3 37500$]$[4 37500$] points de dégâts de givre noir à tous les ennemis se trouvant à proximité 3 sec. après leur apparition, appliquent l'effet 'Froid glacial' et augmentent de 1% pendant 25 sec. les dégâts de givre et de magie noire subis. Cet effet se cumule. ]], 0, 0, 306549, 1637, 946, 0, 942, 16, 0, 4, 2, -1, 0},
    [946] = {946, "Flot de glace", [[ Crée des blocs de glace infligeant $[1 28200$]$[2 35250$]$[3 35250$]$[4 35250$] points de dégâts de givre dans un rayon de 3 m, ralentissant de 45% et repoussant de 12 m. ]], 0, 0, 306551, 1637, 947, 0, 942, 0, 0, 4, 2, -1, 0},
    [947] = {947, "Goule serviteur", [[ Jaina invoque ses pouvoirs acquis, relevant des goules d'entre les morts pour combattre à ses côtés. ]], 24999, 0, 306491, 1637, 0, 948, 942, 1, 0, 4, 2, -1, 100383},
    [948] = {948, "Blessure mortelle", [[ En infligeant des dégâts, il y a 50% de chances de frapper l'ennemi de l'effet 'Blessure mortelle', augmentant de 1250 points les dégâts physiques qu'il subit pendant 60 sec. Cet effet se cumule. ]], 0, 0, 306562, 1637, 0, 0, 947, 1, 0, 4, 2, -1, 0},
    [1000] = {1000, "Monde normal", [[ Halion est un dragon crépusculaire, ce qui signifie qu'il possède une capacité rare même chez les dragons - se déplacer entre les dimensions. Halion passe le premier tiers du combat dans le monde normal, attaquant ses ennemis principalement avec des flammes. ]], 0, 0, 0, 1652, 1006, 1001, 0, 0, 4096, 1, 0, -1, 0},
    [1001] = {1001, "Souffle enflammé", [[ Inflige $[4 27135$]$[3 23878$]$[2 27135$]$[1 23878$] points de dégâts de feu aux ennemis se trouvant dans un cône devant le lanceur de sorts. ]], 0, 0, 74525, 1652, 1002, 0, 1000, 0, 3, 2, 2, -1, 0},
    [1002] = {1002, "Frappe tranchante", [[ Inflige à l'ennemi et à ses alliés proches 75% des dégâts normaux. Affecte jusqu'à 10 cibles. ]], 0, 0, 74524, 1652, 1003, 0, 1000, 0, 3, 3, 2, -1, 0},
    [1003] = {1003, "Coup de queue", [[ Un coup de queue cinglant frappe tous les ennemis situés derrière le lanceur de sorts, infligeant $[4 4192$]$[3 3689$]$[2 4192$]$[1 3689$] points de dégâts et les étourdissant pendant 2 sec. ]], 0, 0, 74531, 1652, 1004, 0, 1000, 0, 2, 4, 2, -1, 0},
    [1004] = {1004, "Chute de météore", [[ Halion fait s'abattre un météore sur une zone sous un joueur choisi au hasard. Inflige $[4 25296$]$[3 22260$]$[2 25296$]$[1 22260$] points de dégâts de feu à tous les ennemis dans un rayon de 12 m et libère 4 traînées de flammes, enflammant une partie du champ de bataille. ]], 0, 0, 74637, 1652, 1005, 1014, 1000, 0, 16, 5, 2, -1, 0},
    [1005] = {1005, "Feu ardent", [[ Les flammes enveloppent l'ennemi, infligeant $[4 5000$]$[3 4400$]$[2 5000$]$[1 4400$] points de dégâts de feu toutes les 2 sec. Chaque fois que la cible subit des dégâts de 'Feu ardent', elle reçoit une 'Marque de feu ardent'. Lorsque l'effet expire ou est dissipé, une tache de feu se forme, dont la taille est directement proportionnelle au nombre de marques accumulées par la cible. Cet effet peut être dissipé à l'aide de sorts de dissipation de malédiction ou de magie. ]], 0, 0, 74562, 1652, 0, 0, 1000, 0, 416, 6, 2, -1, 0},
	[1006] = {1006, "Monde crépusculaire", [[ Lorsque ses points de vie tombent à 75%, Halion ouvre un portail vers la dimension crépusculaire et s'y cache. Les ennemis assez téméraires pour l'y suivre découvriront un tout autre éventail de capacités de ce dragon monstrueux. ]], 0, 0, 0, 1652, 6346, 1007, 0, 0, 4096, 7, 0, -1, 0},
    [1007] = {1007, "Souffle ténébreux", [[ Inflige $[4 24505$]$[3 21564$]$[2 24505$]$[1 21564$] points de dégâts de magie noire aux ennemis se trouvant dans un cône devant le lanceur de sorts. ]], 0, 0, 74806, 1652, 1008, 0, 1006, 0, 3, 8, 2, -1, 0},
    [1008] = {1008, "Dévoration d'âme", [[ Une énergie ténébreuse se concentre autour de l'ennemi, infligeant $[4 5000$]$[3 4400$]$[2 5000$]$[1 4400$] points de dégâts de magie noire toutes les 2 sec. Chaque fois que la cible subit des dégâts de 'Dévoration d'âme', elle reçoit une 'Marque de dévoration'. Lorsque l'effet expire ou est dissipé, une explosion d'énergie ténébreuse se produit, dont la puissance est directement proportionnelle au nombre de marques accumulées par la cible. Cet effet peut être dissipé à l'aide de sorts de dissipation de malédiction ou de magie. ]], 0, 0, 74792, 1652, 1009, 0, 1006, 0, 416, 9, 2, -1, 0},
    [1009] = {1009, "Voile de pénombre", [[ Halion émet une énergie ténébreuse, infligeant aux ennemis proches $[4 3750$]$[3 3300$]$[2 3750$]$[1 3300$] points de dégâts de magie noire toutes les 2 sec. ]], 0, 0, 75476, 1652, 1010, 0, 1006, 0, 4, 10, 2, -1, 0},
    [1010] = {1010, "Lame du crépuscule", [[ Dans le monde crépusculaire, deux sphères sombres tournent autour de l'arène - quatre en difficulté héroïque. Halion charge ces sphères d'énergie, ce qui les relie entre elles par un flux formant une lame du crépuscule. Tout ennemi qui la touche subit $[4 37477$]$[3 32980$]$[2 37477$]$[1 32980$] points de dégâts de magie noire. ]], 0, 0, 74769, 1652, 1011, 0, 1006, 0, 48, 11, 2, -1, 0},
    [1011] = {1011, "Dédoublement crépusculaire", [[ Dédouble le lanceur de sorts, lui permettant d'agir simultanément dans le monde matériel et le monde crépusculaire. ]], 0, 0, 75063, 1652, 0, 1012, 1006, 0, 32, 12, 2, -1, 0},
    [1012] = {1012, "Matérialité", [[ Dédouble le lanceur de sorts entre le monde physique et le monde crépusculaire. Les dégâts infligés et subis par le lanceur de sorts sont proportionnels à son degré de matérialité dans chaque monde. ]], 0, 0, 74832, 1652, 1013, 0, 1011, 0, 34, 13, 2, -1, 0},
    [1013] = {1013, "Soin crépusculaire", [[ En restant au repos dans l'un des mondes, Halion restaure ses forces vitales. ]], 0, 0, 75509, 1652, 0, 0, 1011, 0, 32, 14, 2, -1, 0},
    [1014] = {1014, "Flamme infernale vivante", [[ En difficulté héroïque, 'Chute de météore' invoque également une 'Flamme infernale vivante' ainsi qu'une dizaine de 'Feux vivants'. ]], 12129, 0, 0, 1652, 0, 1015, 1004, 2, 25, 15, 0, 12, 0},
    [1015] = {1015, "Aura ardente", [[ L'air brûlant inflige $[4 5022$]$[3 4419$]$[2 5022$]$[1 4419$] points de dégâts de feu toutes les 2 sec. à tous les ennemis dans un rayon de 15 m. Les points de vie de tous les feux vivants dans ce rayon, ainsi que leurs dégâts infligés, sont augmentés de 30%. ]], 0, 0, 75885, 1652, 1016, 0, 1014, 2, 25, 16, 2, 12, 0},
    [1016] = {1016, "Feu vivant", [[ Ces jeunes élémentaires de flamme sont progressivement renforcés par l'Aura ardente et, bien qu'ils ne représentent initialement aucune menace, peuvent devenir problématiques après une exposition prolongée à l'aura. ]], 1070, 0, 0, 1652, 0, 0, 1014, 2, 25, 17, 0, 12, 0},
    [1500] = {1500, "Phase 1 : Le dieu-phénix", [[ Alar attend ses ennemis au niveau inférieur de l'arène, et une fois le combat engagé, bloque l'accès aux niveaux supérieurs de l'arène et attire vers le bas les ennemis qui s'y trouvent. ]], 0, 0, 0, 11573, 1512, 1501, 0, 0, 0, 1, 2, 12, 0},
    [1501] = {1501, "Chaleur desséchante", [[ Une chaleur émane du corps du phénix, infligeant $[4 16490$]$[2 15520$]$[1 4000$] dégâts de feu toutes les 2 sec. à tous les ennemis dans un rayon de 45 m. Les attaques de corps à corps peuvent provoquer l'effet 'Brûlure'. ]], 0, 0, 308660, 11573, 1503, 1502, 1500, 0, 0, 2, 2, 12, 0},
    [1502] = {1502, "Brûlure", [[ Inflige $[4 824$]$[2 776$]$[1 200$] dégâts de feu toutes les 2 sec. pendant 8 sec. Se cumule jusqu'à 20 fois. ]], 0, 0, 308626, 11573, 0, 0, 1501, 0, 0, 3, 2, 12, 0},
    [1503] = {1503, "Frappe de flamme", [[ Chaque attaque de corps à corps d'Alar qui atteint sa cible inflige $[4 6595$]$[2 6208$]$[1 1600$] points de dégâts de feu supplémentaires et augmente de 50% les dégâts subis par l'ennemi via cette capacité. Se cumule jusqu'à 100 fois. ]], 0, 0, 308627, 11573, 1504, 0, 1500, 0, 0, 4, 2, 12, 0},
    [1504] = {1504, "Chute de flamme", [[ Plusieurs plumes de feu se détachent d'Alar et, après 5 sec., s'envolent vers les positions d'ennemis choisis au hasard. Dès qu'une plume de feu touche le sol, elle explose, infligeant $[4 14840$]$[2 13968$]$[1 3600$] dégâts de feu à tous les ennemis dans un rayon de 6 m, et laisse une marque de flamme sur cette zone. ]], 0, 0, 308629, 11573, 1506, 1505, 1500, 0, 0, 5, 2, 12, 0},
    [1505] = {1505, "Plume ardente", [[ La plume du phénix s'embrase, infligeant $[4 25662$]$[2 24153$]$[1 6225$] dégâts de feu à tous les ennemis dans un rayon de 6 m toutes les 2 sec., et augmentant les dégâts de feu qu'ils subissent de 10% jusqu'à 200% sur 10 sec. ]], 0, 0, 34121, 11573, 0, 0, 1504, 0, 0, 6, 2, 12, 0},
    [1506] = {1506, "Flamme ranimée", [[ Alar fait appel aux étincelles de vie dans ses plumes tombées, ranimant chaque plume en une 'Flamme ranimée'. Ces élémentaires nouvellement créés se dirigent vers Alar pour lui restituer sa puissance. ]], 0, 0, 308633, 11573, 1510, 1507, 1500, 0, 0, 7, 2, 12, 0},
    [1507] = {1507, "Flamme ranimée", [[ Élémentaires nouvellement créés, se dirigeant vers leur créateur. Sensibles à certains effets de contrôle. ]], 5488, 0, 0, 11573, 0, 1508, 1506, 0, 0, 8, 1, 12, 0},
    [1508] = {1508, "Supernova", [[ La flamme ranimée restitue son essence à Alar, provoquant une explosion infligeant $[4 5771$]$[2 5432$]$[1 1400$] dégâts de feu et augmentant de 100% les dégâts subis par les ennemis via cette capacité. Alar reçoit alors une charge de l'effet 'Embrasement croissant'. ]], 0, 0, 308636, 11573, 1509, 0, 1507, 0, 0, 9, 2, 12, 0},
    [1509] = {1509, "Embrasement croissant", [[ La flamme brûle de plus en plus vivement. La vitesse d'attaque et de déplacement est augmentée de 1%. ]], 0, 0, 308637, 11573, 0, 0, 1507, 0, 0, 10, 2, 12, 0},
    [1510] = {1510, "Marque de feu", [[ Marque 5 ennemis lanceurs de sorts d'un signe de feu. La marque draine la force de son porteur, réduisant de 50% sa vitesse de lancer de sorts et de 75% l'efficacité de ses sorts de soin. L'ennemi qui dissipe cette marque en devient lui-même la victime. ]], 0, 0, 308638, 11573, 1511, 0, 1500, 0, 0, 11, 2, 12, 0},
    [1511] = {1511, "Rage berserk", [[ Les dégâts infligés sont augmentés de 500%. Immunité aux effets de provocation. ]], 0, 0, 308639, 11573, 0, 0, 1500, 0, 0, 12, 2, 12, 0},
    [1512] = {1512, "Phase 2 : Les enfants de la flamme", [[ Lorsque ses points de vie tombent à 5%, le dieu-phénix renaît, embrasant le niveau inférieur de l'arène et s'envolant jusqu'au plafond de l'arène. Quatre 'Braises d'Alar' se posent sur la plateforme supérieure, attaquant les ennemis d'Alar. ]], 0, 0, 0, 11573, 0, 1513, 0, 0, 0, 13, 2, 12, 0},
    [1513] = {1513, "Représailles de flamme", [[ Alar renaît, retrouvant l'intégralité de ses points de vie, puis embrase le niveau inférieur de l'arène, tuant instantanément tous les ennemis qui s'y trouvent, et laisse une zone de flammes infligeant $[4 32980$]$[2 31040$]$[1 8000$] dégâts de feu toutes les 1 sec. ]], 0, 0, 308640, 11573, 1515, 1514, 1512, 0, 0, 14, 2, 12, 0},
    [1514] = {1514, "Flamme furieuse", [[ La flamme du phénix, transperçant toute forme de protection, inflige $[4 32980$]$[2 31040$]$[1 8000$] dégâts de feu toutes les 1 sec. ]], 0, 0, 308650, 11573, 0, 0, 1513, 0, 0, 15, 2, 12, 0},
    [1515] = {1515, "Invocation des phénix", [[ Alar invoque quatre phénix, qui se posent sur les plateformes du niveau supérieur de l'arène. La mort de chaque phénix consume 25% des points de vie maximum d'Alar. ]], 0, 0, 308651, 11573, 1532, 1516, 1512, 0, 0, 16, 2, 12, 0},
    [1516] = {1516, "Braise d'Alar", [[ Les quatre phénix invoqués lient leur vie à celle d'Alar, attaquant les ennemis. Les phénix ne se déplacent pas et sont immunisés à tout type de contrôle. La mort de chaque phénix consume 25% des points de vie maximum d'Alar. ]], 19682, 0, 0, 11573, 0, 1517, 1515, 0, 0, 17, 1, 12, 0},
    [1517] = {1517, "Chaleur desséchante", [[ Une chaleur émane du corps du phénix, infligeant $[4 3297$]$[2 3104$]$[1 800$] dégâts de feu toutes les 2 sec. à tous les ennemis dans un rayon de 15 m, et consumant 5% des points de vie maximum du phénix. Les attaques de corps à corps peuvent provoquer l'effet 'Brûlure'. ]], 0, 0, 308804, 11573, 1519, 1518, 1516, 0, 0, 18, 2, 12, 0},
    [1518] = {1518, "Brûlure", [[ Inflige 100 dégâts de feu toutes les 2 sec. pendant 6 sec. ]], 0, 0, 308150, 11573, 0, 0, 1517, 0, 0, 19, 2, 12, 0},
	[1519] = {1519, "Frappe de flamme", [[ Chaque attaque de corps à corps qui atteint sa cible inflige $[4 2473$]$[2 2328$]$[1 600$] points de dégâts de feu supplémentaires et augmente de 50% les dégâts subis par l'ennemi via cette capacité. Se cumule jusqu'à 100 fois. ]], 0, 0, 308661, 11573, 1520, 0, 1516, 0, 0, 20, 2, 12, 0},
    [1520] = {1520, "Marque du phénix", [[ Chacun des quatre phénix obtient la capacité d'utiliser l'une des quatre 'Marques du phénix'. ]], 0, 0, 308663, 11573, 1525, 1521, 1516, 0, 0, 21, 2, 12, 0},
    [1521] = {1521, "Marque du phénix : distraction", [[ Le phénix marque 5 ennemis proches d'un signe magique absorbant leur puissance magique. Les dégâts magiques qu'ils infligent sont réduits de 80% jusqu'à la mort du phénix. ]], 0, 0, 308663, 11573, 1522, 0, 1520, 0, 0, 22, 2, 12, 0},
    [1522] = {1522, "Marque du phénix : faiblesse", [[ Le phénix marque 5 ennemis proches d'un signe magique affaiblissant leur puissance physique. Les dégâts physiques qu'ils infligent sont réduits de 80% jusqu'à la mort du phénix. ]], 0, 0, 308664, 11573, 1523, 0, 1520, 0, 0, 23, 2, 12, 0},
    [1523] = {1523, "Marque du phénix : fureur", [[ Le phénix marque 5 ennemis proches d'un signe magique les emplissant de fureur. Le niveau de menace qu'ils génèrent est augmenté de 200% jusqu'à la mort du phénix. ]], 0, 0, 308665, 11573, 1524, 0, 1520, 0, 0, 24, 2, 12, 0},
    [1524] = {1524, "Marque du phénix : épuisement", [[ Le phénix marque 5 ennemis proches d'un signe magique les frappant d'un épuisement extrême. Presque toutes les formes de régénération de mana sont bloquées, et les réserves maximales de rage, de force runique et d'énergie sont réduites de 50%. ]], 0, 0, 308666, 11573, 0, 0, 1520, 0, 0, 25, 2, 12, 0},
    [1525] = {1525, "Cri du phénix", [[ Chacun des quatre phénix obtient la capacité d'utiliser l'un des quatre 'Cris du phénix'. ]], 0, 0, 308668, 11573, 1530, 1526, 1516, 0, 0, 26, 2, 12, 0},
    [1526] = {1526, "Cri du phénix", [[ Un cri perçant du phénix frappe les ennemis dans un rayon de 45 m, leur faisant lâcher leur arme pendant 6 sec. ]], 0, 0, 308668, 11573, 1527, 0, 1525, 0, 0, 27, 2, 12, 0},
    [1527] = {1527, "Cri du phénix", [[ Le cri du phénix frappe l'âme même des ennemis dans un rayon de 45 m, interrompant leurs sorts en cours et les empêchant de lancer des sorts de la même école pendant 6 sec. ]], 0, 0, 308669, 11573, 1528, 0, 1525, 0, 0, 28, 2, 12, 0},
    [1528] = {1528, "Cri du phénix", [[ Le cri plaintif du phénix ramène à zéro le niveau de menace de tous les ennemis dans un rayon de 45 m. ]], 0, 0, 308670, 11573, 1529, 0, 1525, 0, 0, 29, 2, 12, 0},
    [1529] = {1529, "Cri du phénix", [[ Le cri du phénix inspire terreur et effroi. Les ennemis dans un rayon de 45 m qui aperçoivent le phénix sont plongés dans la peur pendant 6 sec. ]], 0, 0, 308671, 11573, 0, 0, 1525, 0, 0, 30, 2, 12, 0},
    [1530] = {1530, "Jet de flamme", [[ Si le phénix ne parvient pas à rattraper son ennemi au corps à corps, il le frappe de la puissance des flammes, infligeant $[4 8245$]$[2 7760$]$[1 2000$] dégâts de feu et augmentant de 20% les dégâts de feu qu'il subit pendant 60 sec. ]], 0, 0, 308672, 11573, 1531, 0, 1516, 0, 0, 31, 2, 12, 0},
    [1531] = {1531, "Rage berserk", [[ Les dégâts infligés sont augmentés de 500%. Immunité aux effets de provocation. ]], 0, 0, 308673, 11573, 0, 0, 1516, 0, 0, 32, 2, 12, 0},
    [1532] = {1532, "Chute de flamme", [[ Plusieurs plumes de feu se détachent d'Alar et, après 5 sec., s'envolent vers les positions d'ennemis choisis au hasard. Dès qu'une plume de feu touche le sol, elle explose, infligeant $[4 14840$]$[2 13968$]$[1 3600$] dégâts de feu à tous les ennemis dans un rayon de 6 m, et laisse une marque de flamme sur cette zone. ]], 0, 0, 308629, 11573, 1534, 1533, 1512, 0, 0, 33, 2, 12, 0},
    [1533] = {1533, "Plume ardente", [[ La plume du phénix s'embrase, infligeant $[4 24376$]$[2 22942$]$[1 5913$] dégâts de feu à tous les ennemis dans un rayon de 6 m toutes les 2 sec., et augmentant les dégâts de feu qu'ils subissent de 10% jusqu'à 200% sur 10 sec. ]], 0, 0, 34121, 11573, 0, 0, 1532, 0, 0, 34, 2, 12, 0},
    [1534] = {1534, "Flamme ranimée", [[ Alar fait appel aux étincelles de vie dans ses plumes tombées, ranimant chaque plume en une 'Flamme ranimée'. Ces élémentaires nouvellement créés se dirigent vers le phénix le plus proche pour lui restituer sa puissance. ]], 0, 0, 308633, 11573, 0, 1535, 1512, 0, 0, 35, 2, 12, 0},
    [1535] = {1535, "Flamme ranimée", [[ Élémentaires nouvellement créés, se dirigeant vers leur créateur. Sensibles à certains effets de contrôle. ]], 5488, 0, 0, 11573, 0, 1536, 1534, 0, 0, 36, 1, 12, 0},
    [1536] = {1536, "Supernova", [[ La flamme ranimée fusionne avec le phénix le plus proche, provoquant une explosion infligeant $[4 5771$]$[2 5432$]$[1 1400$] dégâts de feu et augmentant de 100% les dégâts subis par les ennemis via cette capacité. Le phénix reçoit alors une charge de l'effet 'Embrasement croissant'. ]], 0, 0, 308636, 11573, 1538, 1537, 1535, 0, 0, 37, 2, 12, 0},
    [1537] = {1537, "Embrasement croissant", [[ La flamme brûle de plus en plus vivement. La vitesse d'attaque est augmentée de 5%. ]], 0, 0, 308658, 11573, 0, 0, 1536, 0, 0, 38, 2, 12, 0},
    [1538] = {1538, "Flamme éternelle", [[ Si la 'Flamme ranimée' meurt avant d'avoir atteint le phénix, elle redevient une 'Plume ardente'. ]], 0, 0, 308659, 11573, 0, 0, 1535, 0, 0, 39, 2, 12, 0},
    [1539] = {1539, "Phase 1 : Le gardien de l'abîme", [[ Le gardien de l'abîme entre en combat sous la protection de sa 'Matrice du néant'. Il doit périodiquement se recharger, et devient alors vulnérable. Cette phase dure jusqu'à ce que tous les 'Creusets du néant' soient déchargés, ou jusqu'à ce que les points de vie du gardien de l'abîme tombent à 50%. ]], 0, 0, 0, 11574, 1549, 1540, 0, 0, 0, 1, 2, 12, 0},
    [1540] = {1540, "Matrice du néant", [[ Les systèmes de protection du gardien de l'abîme s'activent, réduisant de 50% les dégâts qu'il subit. Après un moment, il devra se recharger. ]], 0, 0, 308465, 11574, 1541, 0, 1539, 0, 0, 2, 2, 12, 0},
    [1541] = {1541, "Sphère d'ensorcellement", [[ Le générateur du creuset du néant relâche son surplus d'énergie sous forme d'une sphère qui poursuit l'ennemi le plus éloigné. La sphère explose au contact de n'importe quel ennemi ou d'une autre sphère. ]], 0, 0, 308466, 11574, 1545, 1542, 1539, 0, 0, 3, 2, 12, 0},
    [1542] = {1542, "Magnétisme", [[ La sphère d'ensorcellement se fixe sur l'ennemi le plus éloigné et le poursuit. Au contact de n'importe quel ennemi ou d'une autre sphère, elle utilise 'Explosion'. ]], 0, 0, 308467, 11574, 1543, 0, 1541, 0, 0, 4, 2, 12, 0},
    [1543] = {1543, "Explosion", [[ La sphère explose, infligeant $[4 32980$]$[2 31040$]$[1 8000$] points de dégâts occultes à tous les ennemis dans un rayon de 10 m, ainsi que $[4 13191$]$[2 12416$]$[1 3200$] points de dégâts occultes supplémentaires à tous les ennemis dans un rayon de 500 m, les frappant de 'Réceptivité occulte'. ]], 0, 0, 308468, 11574, 1544, 0, 1541, 0, 0, 5, 2, 12, 0},
    [1544] = {1544, "Réceptivité occulte", [[ L'explosion de la sphère d'ensorcellement confère aux ennemis touchés une énergie résiduelle, augmentant de 100% les dégâts qu'ils subissent d'une 'Explosion'. ]], 0, 0, 308469, 11574, 0, 0, 1541, 0, 0, 6, 2, 12, 0},
    [1545] = {1545, "Coup lourd", [[ Un coup renforcé par l'énergie d'ensorcellement, infligeant $[4 65960$]$[2 62080$]$[1 16000$] points de dégâts occultes à l'ennemi et à ses alliés dans un rayon de 6 m, et augmentant de 25% les dégâts occultes subis. Se cumule jusqu'à 10 fois. ]], 0, 0, 308470, 11574, 1546, 0, 1539, 0, 0, 7, 2, 12, 0},
    [1546] = {1546, "Sceau d'ensorcellement", [[ Marque 4 ennemis d'un sceau d'ensorcellement. Après 8 sec., le sceau s'active, infligeant $[4 49469$]$[2 46560$]$[1 12000$] points de dégâts occultes, et tente de se propager à tous les ennemis dans un rayon de 15 m. ]], 0, 0, 308471, 11574, 1547, 0, 1539, 0, 0, 8, 2, 12, 0},
    [1547] = {1547, "Recharge", [[ Le gardien de l'abîme se précipite vers le creuset du néant le plus proche et commence à s'y recharger. Dans cet état, il ne peut pas se déplacer, mais peut attaquer. Les dégâts qu'il subit sont augmentés de 50%, et toutes les 2 sec. il libère une onde d'énergie d'ensorcellement infligeant $[4 4946$]$[2 4656$]$[1 1200$] points de dégâts occultes à tous les ennemis. ]], 0, 0, 308473, 11574, 0, 1548, 1539, 0, 0, 9, 2, 12, 0},
    [1548] = {1548, "Canon d'ensorcellement", [[ Le gardien de l'abîme active son armement intégré, frappant l'ennemi d'un tir de canon d'ensorcellement infligeant $[4 32980$]$[2 31040$]$[1 8000$] points de dégâts occultes et augmentant de 50% les dégâts occultes subis par la cible. Se cumule jusqu'à 10 fois. ]], 0, 0, 308475, 11574, 0, 0, 1547, 0, 0, 10, 2, 12, 0},
	[1549] = {1549, "Phase 2 : Protocole de Rétribution", [[ La matrice du néant se désactive en raison de la surcharge du système, ce qui active le 'Protocole de Rétribution', qui renforce le gardien de l'abîme à mesure qu'il subit des dégâts. Les 'Creusets du néant' surchargés renforcent toutes les 'Sphères d'ensorcellement' suivantes. ]], 0, 0, 0, 11574, 0, 1550, 0, 0, 0, 11, 2, 12, 0},
    [1550] = {1550, "Protocole de rétribution", [[ Optimisation du système après analyse des dégâts subis, augmentant les dégâts physiques infligés de 1% pour chaque 1% de points de vie manquants. ]], 0, 0, 308479, 11574, 1551, 0, 1549, 0, 0, 12, 2, 12, 0},
    [1551] = {1551, "Surcharge", [[ L'énergie d'ensorcellement submerge les systèmes du gardien de l'abîme, déstabilisant ses circuits et se libérant de façon chaotique, infligeant $[4 6595$]$[2 6208$]$[1 1600$] points de dégâts occultes toutes les 3 sec. à tous les ennemis. ]], 0, 0, 308476, 11574, 1552, 0, 1549, 0, 0, 13, 2, 12, 0},
    [1552] = {1552, "Sphère d'ensorcellement", [[ Le générateur du creuset du néant relâche son surplus d'énergie sous forme d'une sphère qui poursuit l'ennemi le plus éloigné. La sphère explose au contact de n'importe quel ennemi ou d'une autre sphère. ]], 0, 0, 308466, 11574, 1557, 1553, 1549, 0, 0, 14, 2, 12, 0},
    [1553] = {1553, "Magnétisme", [[ La sphère d'ensorcellement se fixe sur l'ennemi le plus éloigné et le poursuit. Au contact de n'importe quel ennemi ou d'une autre sphère, elle utilise 'Explosion'. ]], 0, 0, 308467, 11574, 1554, 0, 1552, 0, 0, 15, 2, 12, 0},
    [1554] = {1554, "Explosion", [[ La sphère explose, infligeant $[4 32980$]$[2 31040$]$[1 8000$] points de dégâts occultes à tous les ennemis dans un rayon de 10 m, ainsi que $[4 13191$]$[2 12416$]$[1 3200$] points de dégâts occultes supplémentaires à tous les ennemis dans un rayon de 500 m, les frappant de 'Réceptivité occulte'. ]], 0, 0, 308468, 11574, 1555, 0, 1552, 0, 0, 16, 2, 12, 0},
    [1555] = {1555, "Réceptivité occulte", [[ L'explosion de la sphère d'ensorcellement confère aux ennemis touchés une énergie résiduelle, augmentant de 100% les dégâts qu'ils subissent d'une 'Explosion'. ]], 0, 0, 308469, 11574, 1556, 0, 1552, 0, 0, 17, 2, 12, 0},
    [1556] = {1556, "Corrosion d'ensorcellement", [[ En raison de la surcharge des creusets du néant, les sphères deviennent plus instables. L'explosion d'une sphère laisse une tache de corrosion d'un rayon de 20 m. Les ennemis présents dans cette zone subissent $[4 3297$]$[2 3104$]$[1 800$] points de dégâts occultes toutes les 1 sec. ]], 0, 0, 308478, 11574, 0, 0, 1552, 0, 0, 18, 2, 12, 0},
    [1557] = {1557, "Coup lourd", [[ Un coup renforcé par l'énergie d'ensorcellement, infligeant $[4 65960$]$[2 62080$]$[1 16000$] points de dégâts occultes à l'ennemi et à ses alliés dans un rayon de 6 m, et augmentant de 25% les dégâts occultes subis. Se cumule jusqu'à 10 fois. ]], 0, 0, 308470, 11574, 1558, 0, 1549, 0, 0, 19, 2, 12, 0},
    [1558] = {1558, "Sceau d'ensorcellement", [[ Marque 4 ennemis d'un sceau d'ensorcellement. Après 8 sec., le sceau s'active, infligeant $[4 49469$]$[2 46560$]$[1 12000$] points de dégâts occultes, et tente de se propager à tous les ennemis dans un rayon de 15 m. ]], 0, 0, 308471, 11574, 0, 0, 1549, 0, 0, 20, 2, 12, 0},
    [1559] = {1559, "Phase 1 : La Grande Astronome", [[ Solarian entre dans le combat, attaquant ses ennemis à l'aide de sorts occultes et de magie sacrée. La Grande Astronome maintient sa position et ne poursuit pas ses ennemis. La phase 1 se termine lorsque les points de vie de la Grande Astronome tombent à 30%, ou après l'accumulation de 100 charges de l'effet 'Force de l'Abîme'. ]], 0, 0, 0, 11575, 1587, 1560, 0, 0, 0, 1, 2, 12, 0},
    [1560] = {1560, "Portail de l'Abîme", [[ L'énergie chaotique du Néant tourbillonnant, s'infiltrant dans la Citadelle des Tempêtes, provoque l'ouverture d'un portail vers l'Abîme, d'où une énergie ténébreuse commence à affluer vers Solarian. Le flux d'énergie se concentrera sur toute créature dotée d'une volonté suffisante qui se trouverait sur le chemin entre le Portail et Solarian. Le Portail de l'Abîme confère à sa cible 1 charge de 'Force de l'Abîme' toutes les 2 sec. ]], 0, 0, 308540, 11575, 1570, 1561, 1559, 0, 0, 2, 2, 12, 0},
    [1561] = {1561, "Force de l'Abîme", [[ La Grande Astronome absorbe l'énergie de l'Abîme. Qui sait ce qui se produira lorsqu'elle aura absorbé suffisamment de cette énergie ténébreuse. ]], 0, 0, 308543, 11575, 1562, 0, 1560, 0, 0, 3, 2, 12, 0},
    [1562] = {1562, "Force de l'Abîme", [[ Un ennemi de Solarian ou l'un des assistants de la Grande Astronome absorbe l'énergie de l'Abîme. Les dégâts qu'il inflige augmentent de 1%, mais il subit $[4 824$]$[2 776$]$[1 200$] points de dégâts de magie noire toutes les 1 sec. Absorber une trop grande quantité de cette énergie ténébreuse mènera inévitablement à quelque chose de très, très mauvais. ]], 0, 0, 308544, 11575, 0, 1563, 1560, 0, 0, 4, 2, 12, 0},
    [1563] = {1563, "Incarnation de l'Abîme", [[ L'énergie de l'Abîme jaillit du corps de la victime, prenant forme, ce qui entraîne sa mort immédiate et douloureuse. La victime ne peut ni quitter son corps ni être ressuscitée avant la fin du combat. ]], 0, 0, 308546, 11575, 0, 1564, 1562, 0, 0, 5, 2, 12, 0},
    [1564] = {1564, "Incarnation de l'Abîme", [[ L'énergie de l'Abîme prend la forme d'une aberration et attaque les ennemis. ]], 50866, 0, 0, 11575, 0, 1565, 1563, 0, 0, 6, 1, 12, 0},
    [1565] = {1565, "Flot de l'Abîme", [[ Un flot d'énergie de l'Abîme tourmentant la chair et l'esprit de l'ennemi, infligeant $[4 16490$]$[2 15520$]$[1 4000$] points de dégâts de magie noire toutes les 1 sec. pendant 5 sec., puis conférant à la cible l'effet 'Force de l'Abîme'. ]], 0, 0, 308570, 11575, 1567, 1566, 1564, 0, 0, 7, 2, 12, 0},
    [1566] = {1566, "Force de l'Abîme", [[ La cible du 'Flot de l'Abîme' absorbe l'énergie de l'Abîme. Les dégâts qu'elle inflige augmentent de 1%, mais elle subit $[4 824$]$[2 776$]$[1 200$] points de dégâts de magie noire toutes les 1 sec. Absorber une trop grande quantité de cette énergie ténébreuse mènera inévitablement à quelque chose de très, très mauvais. ]], 0, 0, 308544, 11575, 0, 0, 1565, 0, 0, 8, 2, 12, 0},
    [1567] = {1567, "Ténèbres corrosives", [[ Une aura d'énergie ténébreuse brûlant les ennemis dans un rayon de 20 m, leur infligeant $[4 9893$]$[2 9312$]$[1 2400$] points de dégâts de magie noire toutes les 3 sec. L'aura persiste même après la mort de l'Incarnation de l'Abîme. ]], 0, 0, 308571, 11575, 1568, 0, 1564, 0, 0, 9, 2, 12, 0},
    [1568] = {1568, "Fusion des ténèbres", [[ L'Incarnation de l'Abîme subit 99% de dégâts en moins si une autre 'Incarnation de l'Abîme', ou ses restes, se trouve dans un rayon de 10 m. ]], 0, 0, 308573, 11575, 1569, 0, 1564, 0, 0, 10, 2, 12, 0},
    [1569] = {1569, "Éruption de l'Abîme", [[ Lorsque ses points de vie tombent à 35%, l'Incarnation de l'Abîme se remplit d'énergie ténébreuse jusqu'à exploser, infligeant $[4 13191$]$[2 12416$]$[1 3200$] points de dégâts de magie noire à tous les ennemis, ainsi que $[4 41224$]$[2 38800$]$[1 10000$] points de dégâts de magie noire supplémentaires à tous les ennemis dans un rayon de 10 m. L'Incarnation de l'Abîme meurt après avoir utilisé cette capacité. ]], 0, 0, 308575, 11575, 0, 0, 1564, 0, 0, 11, 2, 12, 0},
    [1570] = {1570, "Marque de l'Astronome", [[ Solarian marque d'un sceau d'ensorcellement un ennemi aléatoire qui n'est pas sa cible actuelle. Après 6 sec., le 'Courroux de l'Astronome' s'abat sur l'ennemi marqué, infligeant $[4 13191$]$[2 12416$]$[1 3200$] points de dégâts occultes à la cible et à ses alliés dans un rayon de 6 m. Si le 'Courroux' touche la cible et au moins deux de ses alliés, la 'Marque de l'Astronome' est dissipée ; sinon, le porteur de la marque est projeté dans les airs. ]], 0, 0, 308548, 11575, 1573, 1571, 1559, 0, 0, 12, 2, 12, 0},
    [1571] = {1571, "Courroux de l'Astronome", [[ Une force d'ensorcellement inflige au porteur de la 'Marque de l'Astronome' et à ses alliés proches $[4 13191$]$[2 12416$]$[1 3200$] points de dégâts occultes. Si le 'Courroux' touche moins de trois cibles, le porteur de la marque est projeté dans les airs. ]], 0, 0, 308549, 11575, 1572, 0, 1570, 0, 0, 13, 2, 12, 0},
    [1572] = {1572, "Marque inversée", [[ Vous avez protégé un allié d'une mort certaine, mais vous êtes désormais soumis aux enchantements de la Grande Astronome. Subit $[4 16490$]$[2 15520$]$[1 4000$] points de dégâts de magie sacrée toutes les 2 sec. pendant 60 sec. ]], 0, 0, 308551, 11575, 0, 0, 1570, 0, 0, 14, 2, 12, 0},
    [1573] = {1573, "Flèches d'ensorcellement", [[ La Grande Astronome tire des flèches d'ensorcellement pendant 5 sec., infligeant $[4 23498$]$[2 22116$]$[1 5700$] points de dégâts occultes toutes les 1 sec. À la fin de ce sort, Solarian frappe la cible de l'effet 'Instabilité d'ensorcellement'. Alterne l'utilisation de cette capacité avec les 'Flèches de lumière'. ]], 0, 0, 308552, 11575, 1575, 1574, 1559, 0, 0, 15, 2, 12, 0},
    [1574] = {1574, "Instabilité d'ensorcellement", [[ Les dégâts occultes subis sont augmentés de 50%. Combiné avec 'Lumière débordante', provoque une mort instantanée. ]], 0, 0, 308554, 11575, 0, 0, 1573, 0, 0, 16, 2, 12, 0},
    [1575] = {1575, "Flèches de lumière", [[ La Grande Astronome tire des flèches de lumière pendant 5 sec., infligeant $[4 18139$]$[2 17072$]$[1 4400$] points de dégâts de magie sacrée toutes les 1 sec. À la fin de ce sort, Solarian frappe la cible de l'effet 'Lumière débordante'. Alterne l'utilisation de cette capacité avec les 'Flèches d'ensorcellement'. ]], 0, 0, 308555, 11575, 1577, 1576, 1559, 0, 0, 17, 2, 12, 0},
    [1576] = {1576, "Lumière débordante", [[ Les dégâts de magie sacrée subis sont augmentés de 50%. Combiné avec 'Instabilité d'ensorcellement', provoque une mort instantanée. ]], 0, 0, 308557, 11575, 0, 0, 1575, 0, 0, 18, 2, 12, 0},
    [1577] = {1577, "Invocation d'assistants", [[ La Grande Astronome Solarian invoque à son aide un 'Prêtre du Hall de Solarian' et un 'Astronome du Hall de Solarian'. ]], 0, 0, 308558, 11575, 0, 1578, 1559, 0, 0, 19, 2, 12, 0},
    [1578] = {1578, "Prêtre du Hall de Solarian", [[ Un maître de la magie sacrée vient soutenir la Grande Astronome. ]], 19051, 0, 0, 11575, 1582, 1579, 1577, 0, 0, 20, 1, 12, 0},
    [1579] = {1579, "Châtiment", [[ Frappe l'ennemi de la puissance furieuse de la lumière, lui infligeant $[4 16490$]$[2 15520$]$[1 4000$] points de dégâts de magie sacrée et augmentant de 20% les dégâts qu'il subit du 'Châtiment'. ]], 0, 0, 308560, 11575, 1580, 0, 1578, 0, 0, 21, 2, 12, 0},
    [1580] = {1580, "Soin suprême", [[ Invoque le pouvoir de la lumière pour tenter de restaurer 20% des points de vie maximum de la cible. ]], 0, 0, 308561, 11575, 1581, 0, 1578, 0, 0, 22, 2, 12, 0},
    [1581] = {1581, "Anneau de lumière aveuglante :", [[ Le prêtre émet un éclat de lumière insoutenable, infligeant $[4 9893$]$[2 9312$]$[1 2400$] points de dégâts de magie sacrée à tous les ennemis, tout en désorientant pendant 6 sec. ceux qui le regardaient au moment du lancer de ce sort. ]], 0, 0, 308562, 11575, 0, 0, 1578, 0, 0, 23, 2, 12, 0},
    [1582] = {1582, "Visionnaire du Hall de Solarian", [[ Un maître de la magie occulte vient soutenir la Grande Astronome. ]], 19474, 0, 0, 11575, 0, 1583, 1577, 0, 0, 24, 1, 12, 0},
    [1583] = {1583, "Tir d'ensorcellement", [[ Frappe l'ennemi d'une charge d'énergie d'ensorcellement, lui infligeant $[4 24734$]$[2 23280$]$[1 6000$] points de dégâts occultes et augmentant de 20% les dégâts qu'il subit du 'Tir d'ensorcellement'. ]], 0, 0, 308564, 11575, 1584, 0, 1582, 0, 0, 25, 2, 12, 0},
    [1584] = {1584, "Flamme stellaire", [[ Fait s'abattre sur les ennemis une flamme stellaire, infligeant instantanément $[4 6595$]$[2 6208$]$[1 1600$] points de dégâts occultes, puis $[4 6595$]$[2 6208$]$[1 1600$] points de dégâts occultes toutes les 2 sec. pendant 12 sec. ]], 0, 0, 308565, 11575, 1585, 0, 1582, 0, 0, 26, 2, 12, 0},
    [1585] = {1585, "Barrière d'ensorcellement", [[ L'astronome s'entoure d'une barrière de magie occulte empêchant l'interruption de ses sorts, absorbant $[4 1236749$]$[2 1164000$]$[1 300000$] points. ]], 0, 0, 308566, 11575, 1586, 0, 1582, 0, 0, 27, 2, 12, 0},
    [1586] = {1586, "Tempête d'ensorcellement", [[ L'astronome commence à absorber l'énergie d'ensorcellement, infligeant $[4 6595$]$[2 6208$]$[1 1600$] points de dégâts occultes à tous les ennemis toutes les 2 sec. pendant 20 sec. ]], 0, 0, 308567, 11575, 0, 0, 1582, 0, 0, 28, 2, 12, 0},
    [1587] = {1587, "Phase 2 : Le Seigneur de l'Abîme", [[ Lorsque ses points de vie tombent à 30%, ou après avoir atteint 100 charges de 'Force de l'Abîme', Solarian fusionne totalement avec les Forces de l'Abîme, se transformant en Seigneur de l'Abîme. Dès cet instant, l'ancienne Grande Astronome se déplace librement dans l'arène, poursuivant ses ennemis. ]], 0, 0, 0, 11575, 0, 1588, 0, 0, 0, 29, 2, 12, 0},
    [1588] = {1588, "Seigneur de l'Abîme", [[ La Grande Astronome fusionne avec l'Abîme, se transformant en Seigneur de l'Abîme. Les dégâts subis sont réduits de 50%, ses attaques de corps à corps infligent des dégâts de magie noire. En accumulant 100 charges de l'effet 'Pouvoir de l'Abîme', Solarian absorbera la force vitale de tous ses ennemis, les tuant instantanément. Chaque fois qu'une 'Incarnation de l'Abîme' meurt, Solarian perd 5% de ses points de vie actuels. ]], 0, 0, 308576, 11575, 1589, 0, 1587, 0, 0, 30, 2, 12, 0},
    [1589] = {1589, "Don de l'Abîme", [[ La Grande Astronome confère à tous les 'Astronomes' et 'Prêtres' restants, vivants ou morts, le don de l'Abîme, les transformant en 'Incarnations de l'Abîme'. ]], 0, 0, 308577, 11575, 1590, 0, 1587, 0, 0, 31, 2, 12, 0},
    [1590] = {1590, "Portail de l'Abîme - Invocation", [[ Le Portail de l'Abîme s'active, engendrant une 'Incarnation de l'Abîme' et maintenant un flux d'énergie ténébreuse vers Solarian ou tout ennemi se trouvant sur le chemin entre le Portail et Solarian. ]], 0, 0, 308578, 11575, 1601, 1591, 1587, 0, 0, 32, 2, 12, 0},
    [1591] = {1591, "Pouvoir de l'Abîme", [[ La Grande Astronome absorbe l'énergie de l'Abîme, augmentant de 1% les dégâts infligés. À 100 charges cumulées, Solarian acquiert une force suffisante pour tuer instantanément tous ses ennemis. ]], 0, 0, 308580, 11575, 1593, 1592, 1590, 0, 0, 33, 2, 12, 0},
    [1592] = {1592, "Absorption", [[ La Grande Astronome Solarian absorbe la force vitale de tous ses ennemis, les tuant instantanément. ]], 0, 0, 308581, 11575, 0, 0, 1591, 0, 0, 34, 2, 12, 0},
    [1593] = {1593, "Force de l'Abîme", [[ Un ennemi de Solarian ou l'un des assistants de la Grande Astronome absorbe l'énergie de l'Abîme. Les dégâts qu'il inflige augmentent de 1%, mais il subit $[4 824$]$[2 776$]$[1 200$] points de dégâts de magie noire toutes les 1 sec. Absorber une trop grande quantité de cette énergie ténébreuse mènera inévitablement à quelque chose de très, très mauvais. ]], 0, 0, 308544, 11575, 0, 1594, 1590, 0, 0, 35, 2, 12, 0},
    [1594] = {1594, "Incarnation de l'Abîme", [[ L'énergie de l'Abîme jaillit du corps de la victime, prenant forme, ce qui entraîne sa mort immédiate et douloureuse. La victime ne peut ni quitter son corps ni être ressuscitée avant la fin du combat. ]], 0, 0, 308546, 11575, 0, 1595, 1593, 0, 0, 36, 2, 12, 0},
    [1595] = {1595, "Incarnation de l'Abîme", [[ L'énergie de l'Abîme prend la forme d'une aberration et attaque les ennemis. ]], 50866, 0, 0, 11575, 0, 1596, 1594, 0, 0, 37, 1, 12, 0},
    [1596] = {1596, "Flot de l'Abîme", [[ Un flot d'énergie de l'Abîme tourmentant la chair et l'esprit de l'ennemi, infligeant $[4 16490$]$[2 15520$]$[1 4000$] points de dégâts de magie noire toutes les 1 sec. pendant 5 sec., puis conférant à la cible l'effet 'Force de l'Abîme'. ]], 0, 0, 308570, 11575, 1597, 0, 1595, 0, 0, 38, 2, 12, 0},
    [1597] = {1597, "Force de l'Abîme", [[ La cible du 'Flot de l'Abîme' absorbe l'énergie de l'Abîme. Les dégâts qu'elle inflige augmentent de 1%, mais elle subit $[4 824$]$[2 776$]$[1 200$] points de dégâts de magie noire toutes les 1 sec. Absorber une trop grande quantité de cette énergie ténébreuse mènera inévitablement à quelque chose de très, très mauvais. ]], 0, 0, 308544, 11575, 1598, 0, 1596, 0, 0, 39, 2, 12, 0},
    [1598] = {1598, "Ténèbres corrosives", [[ Une aura d'énergie ténébreuse brûlant les ennemis dans un rayon de 20 m, leur infligeant $[4 9893$]$[2 9312$]$[1 2400$] points de dégâts de magie noire toutes les 3 sec. L'aura persiste même après la mort de l'Incarnation de l'Abîme. ]], 0, 0, 308571, 11575, 1599, 0, 1595, 0, 0, 40, 2, 12, 0},
    [1599] = {1599, "Fusion des ténèbres", [[ L'Incarnation de l'Abîme subit 99% de dégâts en moins si une autre 'Incarnation de l'Abîme', ou ses restes, se trouve dans un rayon de 10 m. ]], 0, 0, 308573, 11575, 1600, 0, 1595, 0, 0, 41, 2, 12, 0},
    [1600] = {1600, "Éruption de l'Abîme", [[ Lorsque ses points de vie tombent à 35%, l'Incarnation de l'Abîme se remplit d'énergie ténébreuse jusqu'à exploser, infligeant $[4 13191$]$[2 12416$]$[1 3200$] points de dégâts de magie noire à tous les ennemis, ainsi que $[4 41224$]$[2 38800$]$[1 10000$] points de dégâts de magie noire supplémentaires à tous les ennemis dans un rayon de 10 m. L'Incarnation de l'Abîme meurt après avoir utilisé cette capacité. ]], 0, 0, 308575, 11575, 0, 0, 1595, 0, 0, 42, 2, 12, 0},
    [1601] = {1601, "Contact de l'Abîme", [[ Solarian effectue une attaque frappant tous les ennemis devant lui, infligeant $[4 32980$]$[2 31040$]$[1 8000$] points de dégâts de magie noire. Les ennemis touchés subissent 20% de dégâts de magie noire en plus jusqu'à la fin du combat. ]], 0, 0, 308582, 11575, 1602, 0, 1587, 0, 0, 43, 2, 12, 0},
    [1602] = {1602, "Terreur de l'Abîme", [[ Solarian fait appel aux forces de l'Abîme. Chaque ennemi émet un éclat d'énergie ténébreuse, infligeant $[4 6595$]$[2 6208$]$[1 1600$] points de dégâts de magie noire à lui-même et à ses alliés dans un rayon de 4 m. Si l'éclat émis par un ennemi touche moins de deux alliés, celui-ci est saisi de terreur et fuit Solarian pendant 10 sec. N'affecte pas les ennemis attaqués au corps à corps par une 'Incarnation de l'Abîme'. ]], 0, 0, 308585, 11575, 0, 1603, 1587, 0, 0, 44, 2, 12, 0},
    [1603] = {1603, "Éclat de l'Abîme", [[ Solarian fait appel aux forces de l'Abîme. Chaque ennemi émet un éclat d'énergie ténébreuse, infligeant $[4 6595$]$[2 6208$]$[1 1600$] points de dégâts de magie noire à lui-même et à ses alliés dans un rayon de 4 m. Si l'éclat émis par un ennemi touche moins de deux alliés, celui-ci est saisi de terreur et fuit Solarian pendant 10 sec. N'affecte pas les ennemis attaqués au corps à corps par une 'Incarnation de l'Abîme'. ]], 0, 0, 308586, 11575, 0, 0, 1602, 0, 0, 45, 2, 12, 0},
    [1604] = {1604, "Phase 1 : Permettez-moi de vous présenter mes conseillers...", [[ Les conseillers de Kael'thas entrent tour à tour dans le combat, défendant les idéaux de leur maître. ]], 0, 0, 0, 11576, 1628, 1605, 0, 0, 0, 1, 2, 12, 0},
    [1605] = {1605, "Taladred Voleur de lumière", [[ Éventreur armé d'une arme vivante enchantée, Taladred se défend habilement contre les attaques magiques, mais reste vulnérable aux attaques physiques. ]], 20236, 0, 0, 11576, 1612, 1606, 1604, 0, 0, 2, 1, 12, 0},
    [1606] = {1606, "Réflexion de sorts", [[ Les sorts sont impuissants face à l'arme enchantée de Voleur de lumière. Les dégâts magiques qu'il subit sont réduits de 25%. Périodiquement, son arme enchantée s'anime et exécute une attaque tourbillonnante infligeant $[4 24734$]$[2 23280$]$[1 6000$] dégâts physiques à tous les ennemis dans un rayon de 6 m. ]], 0, 0, 308730, 11576, 1607, 0, 1605, 0, 0, 3, 2, 12, 0},
    [1607] = {1607, "Frappe furieuse", [[ Un coup empli de haine, infligeant $[4 65960$]$[2 62080$]$[1 16000$] dégâts physiques et provoquant un saignement infligeant $[4 24734$]$[2 23280$]$[1 6000$] dégâts physiques toutes les 2 sec. pendant 15 sec. ]], 0, 0, 308732, 11576, 1608, 0, 1605, 0, 0, 4, 2, 12, 0},
    [1608] = {1608, "Cri de guerre", [[ Voleur de lumière pousse un cri de guerre, galvanisant ses alliés actifs. Les dégâts qu'ils infligent sont augmentés de 10% jusqu'à la fin du combat. ]], 0, 0, 308733, 11576, 1609, 0, 1605, 0, 0, 5, 2, 12, 0},
	[1609] = {1609, "Dévastateur", [[ Taladred lance son arme sur l'ennemi le plus éloigné dans un rayon de 40 m, lui infligeant des dégâts égaux à $[4 41$]$[2 38$]$[1 10$]% de ses points de vie actuels et le frappant de 'Blessure mortelle'. L'arme lancée s'anime, se mettant à tournoyer dans un tourbillon d'acier, infligeant $[4 32980$]$[2 31040$]$[1 8000$] dégâts physiques toutes les 3 sec. à tous les ennemis dans un rayon de 6 m. Après 60 secondes, les enchantements qui la maintiennent en vie se dissipent. La portée d'utilisation augmente si aucune cible appropriée n'est trouvée. ]], 0, 0, 308736, 11576, 0, 1610, 1605, 0, 0, 6, 2, 12, 0},
    [1610] = {1610, "Blessure mortelle", [[ Le Dévastateur vous a infligé une blessure mortelle. Subit $[4 8245$]$[2 7760$]$[1 2000$] dégâts physiques toutes les 3 sec. jusqu'à la fin du combat. ]], 0, 0, 308737, 11576, 1611, 0, 1609, 0, 0, 7, 2, 12, 0},
    [1611] = {1611, "Dévastation", [[ La hache animée tournoie dans un tourbillon d'acier, infligeant $[4 32980$]$[2 31040$]$[1 8000$] dégâts physiques toutes les 3 sec. à tous les ennemis dans un rayon de 6 m. ]], 0, 0, 308738, 11576, 0, 0, 1609, 0, 0, 8, 2, 12, 0},
    [1612] = {1612, "Seigneur Sanguinar", [[ Paladin des ténèbres armé d'un puissant marteau et d'un bouclier, Sanguinar entre dans le combat en résistant à la majeure partie des dégâts magiques qu'il subit. ]], 20178, 0, 0, 11576, 1617, 1613, 1604, 0, 0, 9, 1, 12, 0},
    [1613] = {1613, "Égide des ténèbres", [[ Une bénédiction des ténèbres protège le Seigneur Sanguinar, réduisant de 25% les dégâts magiques qu'il subit, tout en infligeant $[4 6595$]$[2 6208$]$[1 1600$] points de dégâts de magie noire toutes les 2 sec. à tous les ennemis dans un rayon de 40 m. ]], 0, 0, 308739, 11576, 1614, 0, 1612, 0, 0, 10, 2, 12, 0},
    [1614] = {1614, "Justice des ténèbres", [[ Frappe l'ennemi de la puissance des ténèbres, lui infligeant $[4 32980$]$[2 31040$]$[1 8000$] points de dégâts de magie noire. Les dégâts infligés par cette capacité ignorent les effets d'invulnérabilité et de résistance. Augmente de 100% les dégâts subis par la cible de la 'Justice des ténèbres'. ]], 0, 0, 308741, 11576, 1615, 0, 1612, 0, 0, 11, 2, 12, 0},
    [1615] = {1615, "Consécration des ténèbres", [[ Le Seigneur Sanguinar consacre le sol sur lequel il se tient avec la puissance des ténèbres, infligeant $[4 9893$]$[2 9312$]$[1 2400$] points de dégâts de magie noire toutes les 3 sec. aux ennemis présents sur cette zone, pendant 30 sec. ]], 0, 0, 308742, 11576, 1616, 0, 1612, 0, 0, 12, 2, 12, 0},
    [1616] = {1616, "Bouclier vengeur", [[ Sanguinar lance un bouclier chargé d'énergie des ténèbres sur l'ennemi le plus éloigné dans un rayon de 40 m, lui infligeant $[4 12367$]$[2 11640$]$[1 3000$] points de dégâts de magie noire et interrompant son sort en cours. Le bouclier rebondit de l'ennemi touché vers son allié le plus proche, touchant jusqu'à 3 cibles. L'ennemi dont le sort a été interrompu ne peut lancer de sort de la même école pendant 10 sec. La portée d'utilisation augmente si aucune cible appropriée n'est trouvée. ]], 0, 0, 308743, 11576, 0, 0, 1612, 0, 0, 13, 2, 12, 0},
    [1617] = {1617, "Grand Astronome Capernian", [[ Mage de sang armée d'un bâton d'énergie de feu chaotique, Capernian entre dans le combat en repoussant continuellement les ennemis au corps à corps, mais reste vulnérable aux attaques à distance et aux sorts. ]], 20237, 0, 0, 11576, 1622, 1618, 1604, 0, 0, 14, 1, 12, 0},
    [1618] = {1618, "Tourbillon de flammes", [[ Capernian s'entoure d'un tourbillon de flammes de terreur. Toutes les 3 sec., le tourbillon émet une onde de choc repoussant tous les ennemis dans un rayon de 10 m de 20 m en arrière, et infligeant à tous les ennemis dans un rayon de 40 m $[4 7420$]$[2 6984$]$[1 1800$] points de dégâts de feu. Ce sort ignore les effets de résistance et d'immunité. ]], 0, 0, 308745, 11576, 1619, 0, 1617, 0, 0, 15, 2, 12, 0},
    [1619] = {1619, "Flèche de flamme de terreur", [[ Frappe l'ennemi d'une flèche de flamme, infligeant $[4 32980$]$[2 31040$]$[1 8000$] points de dégâts de feu. Ce sort ignore les effets de résistance et d'immunité. ]], 0, 0, 308747, 11576, 1620, 0, 1617, 0, 0, 16, 2, 12, 0},
    [1620] = {1620, "Embrasement", [[ Capernian enflamme l'ennemi et ses alliés dans un rayon de 6 m avec des flammes de terreur, lui infligeant 12000 dégâts de feu toutes les 3 sec. pendant 30 sec. Ce sort ignore les effets de résistance et d'immunité. ]], 0, 0, 308748, 11576, 1621, 0, 1617, 0, 0, 17, 2, 12, 0},
    [1621] = {1621, "Bombe de terreur vivante", [[ Capernian instille la terreur en deux ennemis choisis au hasard dans un rayon de 40 m, les forçant à fuir dans la panique pendant 10 sec. Pendant la durée de cet effet, les ennemis touchés subissent $[4 1648$]$[2 1552$]$[1 400$] points de dégâts de feu toutes les 1 sec. À la fin de l'effet ou s'il est dissipé, une explosion se produit, infligeant $[4 8245$]$[2 7760$]$[1 2000$] points de dégâts de feu à tous les ennemis dans un rayon de 6 m et propageant cet effet à tous les ennemis touchés. La portée d'utilisation augmente si aucune cible appropriée n'est trouvée. ]], 0, 0, 308749, 11576, 0, 0, 1617, 0, 0, 18, 2, 12, 0},
    [1622] = {1622, "Ingénieur en chef Telonicus", [[ Mystique armé de deux dagues, Telonicus attaque ses ennemis en esquivant les attaques de corps à corps et à distance grâce à des réflexes surnaturels. ]], 20177, 0, 0, 11576, 0, 1623, 1604, 0, 0, 19, 1, 12, 0},
    [1623] = {1623, "Esquive", [[ Telonicus esquive toutes les attaques à distance et de corps à corps comme s'il se dissolvait dans l'air. La probabilité d'être touché au corps à corps et à distance est réduite de 25%. Utilise la capacité 'Éventail de lames scintillant' toutes les 3 sec. ]], 0, 0, 308752, 11576, 1625, 1624, 1622, 0, 0, 20, 2, 12, 0},
    [1624] = {1624, "Éventail de lames scintillant", [[ Un éventail de lames enchantées, infligeant $[4 6595$]$[2 6208$]$[1 1600$] dégâts physiques et $[4 6595$]$[2 6208$]$[1 1600$] points de dégâts occultes à tous les ennemis dans un rayon de 40 m. ]], 0, 0, 308753, 11576, 0, 0, 1623, 0, 0, 21, 2, 12, 0},
    [1625] = {1625, "Frappe scintillante", [[ Un coup sournois, infligeant $[4 32980$]$[2 31040$]$[1 8000$] points de dégâts occultes et provoquant un saignement infligeant $[4 16490$]$[2 15520$]$[1 4000$] dégâts physiques toutes les 2 sec. ]], 0, 0, 308755, 11576, 1626, 0, 1622, 0, 0, 22, 2, 12, 0},
    [1626] = {1626, "Lancer mortel scintillant", [[ Telonicus lance ses dagues sur deux ennemis choisis au hasard, leur infligeant $[4 13191$]$[2 12416$]$[1 3200$] points de dégâts occultes et absorbant 25% de leur réserve de mana. Cette capacité cible toujours les ennemis les plus éloignés dans un rayon de 40 m. La portée d'utilisation augmente si aucune cible appropriée n'est trouvée. ]], 0, 0, 308757, 11576, 1627, 0, 1622, 0, 0, 23, 2, 12, 0},
    [1627] = {1627, "Frappe de l'esprit", [[ Telonicus attaque l'esprit de l'ennemi pendant 60 sec., lui infligeant $[4 3297$]$[2 3104$]$[1 800$] points de dégâts occultes toutes les 1 sec. et l'étourdissant pendant 5 sec. toutes les 10 sec. ]], 0, 0, 308760, 11576, 0, 0, 1622, 0, 0, 24, 2, 12, 0},
    [1628] = {1628, "Phase 2 : Le Serment de Sang", [[ Deux minutes après la mort du dernier conseiller, Kael'thas les ressuscite, les liant par le Serment de Sang. Après 6 minutes, ou après la mort de deux conseillers, Kael'thas entre dans le combat, entamant la Phase 3. ]], 0, 0, 0, 11576, 1653, 1629, 0, 0, 0, 25, 2, 12, 0},
    [1629] = {1629, "Serment de Sang", [[ Les conseillers de Kael'thas sont liés par un serment puissant qui leur permet de résister à n'importe quel assaut, en réparant instantanément les dégâts subis. Seuls les efforts combinés d'au moins dix ennemis peuvent surpasser l'effet du serment. La présence d'autres conseillers à proximité renforce le serment, empêchant sa dissipation. ]], 0, 0, 308744, 11576, 1630, 0, 1628, 0, 0, 26, 2, 12, 0},
