    [11001] = {11001, "Calcination de la chair", [[ Votre chair se calcine sous vos yeux ! Les 30000 prochains points de soins que vous recevrez seront absorbés, et les dégâts infligés seront réduits de 50 % pendant 15 sec. Si 'Calcination de la chair' n'est pas dissipé avant la fin de sa durée, il déclenchera l'effet 'Géhenne ardente'. ]], 0, 0, 66237, 1619, 11002, 0, 11000, 0, 0, 2, 2, -1, 0},
    [11002] = {11002, "Géhenne ardente", [[ 'Géhenne ardente' inflige $[4 3834$]$[2 3834$]$[3 3834$]$[1 3834$] points de dégâts de feu par seconde à tous les alliés pendant 5 sec. 'Géhenne ardente' apparaît si l'effet 'Calcination de la chair' n'est pas dissipé avant la fin de sa durée. 'Calcination de la chair' est dissipé après absorption de 30000 points de soins. ]], 0, 0, 66242, 1619, 11003, 0, 11000, 0, 0, 3, 2, -1, 0},
    [11003] = {11003, "Boule de feu Fielleuse", [[ Inflige $[4 22915$]$[2 22915$]$[3 22915$]$[1 22915$] points de dégâts de feu et, en plus, $[4 9222$]$[2 9222$]$[3 9222$]$[1 9222$] points de dégâts de feu par seconde pendant 5 sec. ]], 0, 0, 66532, 1619, 11004, 0, 11000, 0, 0, 4, 2, -1, 0},
