    [11055] = {11055, "Détermination", [[ Le scarabée restaure ses points de vie et devient insensible à l'étourdissement ainsi qu'aux effets entravant le déplacement. La vitesse de déplacement augmente de 100 %. ]], 0, 0, 66092, 1623, 11056, 0, 11054, 0, 0, 8, 2, -1, 0},
