    [11143] = {11143, "Bond", [[ Transporte l'invocateur de 20 m vers l'avant, en l'absence d'obstacle sur le chemin. Libère l'invocateur des effets d'étourdissement et des effets limitant le déplacement. ]], 0, 0, 65793, 1620, 11144, 0, 11138, 0, 0, 4, 2, -1, 0},
