    [11145] = {11145, "Explosion d'ensorcellement", [[ Provoque une explosion de magie arcanique autour de l'invocateur, infligeant $[4 8265$]$[2 8265$]$[3 8265$]$[1 8265$] points de dégâts de magie arcanique à toutes les cibles dans un rayon de 10 m. ]], 0, 0, 65800, 1620, 11146, 0, 11138, 0, 0, 4, 2, -1, 0},
    [11146] = {11146, "Salve d'ensorcellement", [[ Lance plusieurs flèches magiques sur l'adversaire, infligeant $[4 7671$]$[2 7671$]$[3 7671$]$[1 7671$] points de dégâts de magie arcanique. ]], 0, 0, 65799, 1620, 11147, 0, 11138, 0, 0, 4, 2, -1, 0},
