    [11148] = {11148, "Iriet Pas-dans-l'Ombre", [[ Voleuse combattant aux côtés des champions de l'Alliance après le combat contre le Seigneur Jaraxxus. ]], 29776, 0, 0, 1620, 11158, 11149, 0, 1, 0, 1, 0, -1, 0},
    [11149] = {11149, "Éventail de lames", [[ Lancer instantané des deux armes sur tous les adversaires dans un rayon de 10 m, infligeant 90 % des dégâts d'arme. ]], 0, 0, 65955, 1620, 11150, 0, 11148, 0, 0, 4, 2, -1, 0},
    [11150] = {11150, "Hémorragie", [[ Un coup violent infligeant des dégâts équivalents à 110 % des dégâts d'arme. L'hémorragie provoquée par le coup augmente les dégâts physiques infligés à la cible jusqu'à 75 points. Dure 10 coups ou 15 sec. La durée de la série de coups augmente de 1. ]], 0, 0, 65954, 1620, 11151, 0, 11148, 0, 0, 4, 2, -1, 0},
    [11151] = {11151, "Poison neutralisant", [[ Empoisonne l'adversaire, réduisant de 50 % l'effet des soins qu'il reçoit pendant 15 sec. ]], 0, 0, 65962, 1620, 11152, 0, 11148, 0, 0, 4, 2, -1, 0},
    [11152] = {11152, "Aveuglement", [[ Aveugle la cible, la faisant errer sans but pendant 10 sec. Tout dégât infligé annule l'effet. ]], 0, 0, 65960, 1620, 11153, 0, 11148, 0, 0, 4, 2, -1, 0},
    [11153] = {11153, "Cape des ombres", [[ Retire tous les effets de sorts hostiles et augmente de 90 % la chance de résister à tous les sorts pendant 5 sec. Ne retire pas les effets empêchant l'utilisation de la capacité 'Cape des ombres'. ]], 0, 0, 65961, 1620, 11154, 0, 11148, 0, 0, 4, 2, -1, 0},
    [11154] = {11154, "Éviscération", [[ Coup final infligeant $[4 8376$]$[2 8376$]$[3 8376$]$[1 8376$] points de dégâts physiques. ]], 0, 0, 65957, 1620, 11155, 0, 11148, 0, 0, 4, 2, -1, 0},
    [11155] = {11155, "Pas dans l'ombre", [[ Traverse l'ombre pour apparaître derrière l'adversaire. ]], 0, 0, 66178, 1620, 11156, 0, 11148, 0, 0, 4, 2, -1, 0},
    [11156] = {11156, "Rafale de lames", [[ Augmente la vitesse d'attaque de 20 %, tout en infligeant également un coup à l'adversaire le plus proche. Durée : 15 sec. ]], 0, 0, 65956, 1620, 11157, 0, 11148, 0, 0, 4, 2, -1, 0},
    [11157] = {11157, "Accessoire JcJ", [[ Retire tous les effets de ralentissement et tous les effets de perte de contrôle du personnage. ]], 0, 0, 65547, 1620, 0, 0, 11148, 0, 0, 4, 2, 12, 0},
