    [11159] = {11159, "Renouveau", [[ Rend à un allié $[4 29797$]$[2 29797$]$[3 29797$]$[1 29797$] points de vie au moment du lancement du sort, puis $[4 49707$]$[2 49707$]$[3 49707$]$[1 49707$] points de plus sur 21 sec. ]], 0, 0, 66067, 1620, 11160, 0, 11158, 0, 0, 4, 2, -1, 0},
    [11160] = {11160, "Peau d'écorce", [[ La peau du druide devient aussi solide que de l'écorce. Tous les dégâts subis sont réduits de 40 %. Ce sort peut être utilisé même étourdi, gelé, paralysé, effrayé ou endormi. Utilisable sous toutes les formes. Durée : 12 sec. ]], 0, 0, 65860, 1620, 11161, 0, 11158, 0, 0, 4, 2, -1, 0},
    [11161] = {11161, "Fleur de vie", [[ Rend $[4 2892$]$[2 2892$]$[3 2892$]$[1 2892$] points de vie chaque seconde et $[4 14814$]$[2 14814$]$[3 14814$]$[1 14814$] points de vie lorsque l'effet est dissipé ou prend fin. ]], 0, 0, 66093, 1620, 11162, 0, 11158, 0, 0, 4, 2, -1, 0},
    [11162] = {11162, "Rajeunissement", [[ Rend à un allié $[4 154110$]$[2 154110$]$[3 154110$]$[1 154110$] points de vie pendant 15 sec. ]], 0, 0, 66065, 1620, 11163, 0, 11158, 0, 0, 4, 2, -1, 0},
