    [11164] = {11164, "Sérénité", [[ Rend $[4 60220$]$[2 60220$]$[3 60220$]$[1 60220$] points de vie à tous les membres proches du groupe toutes les 2 sec. pendant 10 sec. Nécessite un maintien du sort. ]], 0, 0, 66086, 1620, 11165, 0, 11158, 0, 0, 4, 2, -1, 0},
    [11165] = {11165, "Étreinte de la nature", [[ Une fois activée, donne 100 % de chance que l'adversaire qui frappe l'invocateur soit immobilisé par la 'Colère des arbres'. Nombre de charges : 1. Durée : 45 sec. ]], 0, 0, 66071, 1620, 11166, 0, 11158, 0, 0, 4, 2, -1, 0},
    [11166] = {11166, "Épines", [[ Des épines poussent sur la cible amie, infligeant $[4 738$]$[2 738$]$[3 738$]$[1 738$] points de dégâts de nature aux adversaires à chaque attaque au corps à corps. Durée : 600 min. ]], 0, 0, 66068, 1620, 11167, 0, 11158, 0, 0, 4, 2, -1, 0},
    [11167] = {11167, "Accessoire JcJ", [[ Retire tous les effets de ralentissement et tous les effets de perte de contrôle du personnage. ]], 0, 0, 65547, 1620, 0, 0, 11158, 0, 0, 4, 2, 12, 0},
