    [11172] = {11172, "Feu lunaire", [[ Brûle l'adversaire, lui infligeant $[4 3753$]$[2 3753$]$[3 3753$]$[1 3753$] points de dégâts de magie arcanique et $[4 6006$]$[2 6006$]$[3 6006$]$[1 6006$] points de dégâts supplémentaires de magie arcanique pendant 12 sec. ]], 0, 0, 65856, 1620, 11173, 0, 11168, 0, 0, 4, 2, -1, 0},
    [11173] = {11173, "Essaim d'insectes", [[ Un essaim d'insectes attaque l'adversaire, réduisant de 3 % sa chance de toucher au corps à corps et à distance et lui infligeant $[4 23688$]$[2 23688$]$[3 23688$]$[1 23688$] points de dégâts de nature sur 12 sec. ]], 0, 0, 65855, 1620, 11174, 0, 11168, 0, 0, 4, 2, -1, 0},
