    [11175] = {11175, "Peau d'écorce", [[ La peau du druide devient aussi solide que de l'écorce. Tous les dégâts subis sont réduits de 40 %. Ce sort peut être utilisé même étourdi, gelé, paralysé, effrayé ou endormi. Utilisable sous toutes les formes. Durée : 12 sec. ]], 0, 0, 65860, 1620, 11176, 0, 11168, 0, 0, 4, 2, -1, 0},
    [11176] = {11176, "Colère des arbres", [[ Enveloppe la cible de racines qui la maintiennent en place et lui infligent $[4 2425$]$[2 2425$]$[3 2425$]$[1 2425$] points de dégâts de nature pendant 10 sec. Des dégâts extérieurs peuvent interrompre cet effet. ]], 0, 0, 65857, 1620, 11177, 0, 11168, 0, 0, 4, 2, -1, 0},
    [11177] = {11177, "Tornade", [[ Projette l'adversaire dans les airs, l'empêchant de toute action. Il devient alors invulnérable pendant 6 sec. Vous ne pouvez appliquer 'Tornade' qu'à une seule cible à la fois. ]], 0, 0, 65859, 1620, 11178, 0, 11168, 0, 0, 4, 2, -1, 0},
