    [11179] = {11179, "Brienne Tombée-de-la-Nuit", [[ Prêtresse des Ténèbres combattant aux côtés des champions de l'Alliance après le combat contre le Seigneur Jaraxxus. ]], 29778, 0, 0, 1620, 11190, 11180, 0, 1, 0, 1, 0, -1, 0},
    [11180] = {11180, "Horreur abyssale", [[ Effraie la cible, la forçant à lâcher son arme de la main droite et son arme à distance pendant 10 sec., et à trembler de peur pendant 3 sec. ]], 0, 0, 65545, 1620, 11181, 0, 11179, 0, 0, 4, 2, -1, 0},
