    [11182] = {11182, "Mutisme", [[ Réduit l'adversaire au silence, l'empêchant de lancer des sorts pendant 5 sec. ]], 0, 0, 65542, 1620, 11183, 0, 11179, 0, 0, 4, 2, -1, 0},
    [11183] = {11183, "Toucher du vampire", [[ Inflige à l'adversaire $[4 21157$]$[2 21157$]$[3 21157$]$[1 21157$] points de dégâts de magie noire sur 15 sec. ]], 0, 0, 65490, 1620, 11184, 0, 11179, 0, 0, 4, 2, -1, 0},
    [11184] = {11184, "Torture de l'esprit", [[ Inflige à l'adversaire des dégâts de magie noire et réduit sa vitesse de déplacement pendant 3 sec. ]], 0, 0, 65488, 1620, 11185, 0, 11179, 0, 0, 4, 2, -1, 0},
    [11185] = {11185, "Dissipation de sorts", [[ Dissipe la magie agissant sur la cible, retirant jusqu'à 2 effets négatifs d'un allié ou jusqu'à 2 effets positifs d'un adversaire. ]], 0, 0, 65546, 1620, 11186, 0, 11179, 0, 0, 4, 2, -1, 0},
    [11186] = {11186, "Fusion avec les Ténèbres", [[ Vous vous dissolvez dans les Ténèbres. Tous les dégâts que vous subissez sont réduits de 90 %. Vous ne pouvez ni attaquer ni lancer de sorts, mais vous restaurez 6 % de mana chaque seconde pendant 6 sec. Ce sort peut être utilisé même si vous êtes étourdi, effrayé ou réduit au silence. Son utilisation dissipe les effets d'entrave et de limitation de mouvement, et confère une immunité à ceux-ci pendant la durée du sort. ]], 0, 0, 65544, 1620, 11187, 0, 11179, 0, 0, 4, 2, -1, 0},
    [11187] = {11187, "Mot des Ténèbres : Douleur", [[ Prononce le Mot des Ténèbres, qui inflige des dégâts de magie noire à l'adversaire toutes les 3 sec. pendant 15 sec. ]], 0, 0, 65541, 1620, 11188, 0, 11179, 0, 0, 4, 2, -1, 0},
    [11188] = {11188, "Explosion mentale", [[ Frappe l'esprit de la cible, infligeant $[4 8290$]$[2 8290$]$[3 8290$]$[1 8290$] points de dégâts de magie noire. ]], 0, 0, 65492, 1620, 11189, 0, 11179, 0, 0, 4, 2, -1, 0},
    [11189] = {11189, "Accessoire JcJ", [[ Retire tous les effets de ralentissement et tous les effets de perte de contrôle du personnage. ]], 0, 0, 65547, 1620, 0, 0, 11179, 0, 0, 4, 2, 12, 0},
    [11190] = {11190, "Shokul", [[ Guerrier combattant aux côtés des champions de l'Alliance après le combat contre le Seigneur Jaraxxus. ]], 29779, 0, 0, 1620, 0, 11191, 0, 1, 0, 1, 0, -1, 0},
    [11191] = {11191, "Tourbillon de lames", [[ Fondre sur les adversaires proches en tourbillonnant et les attaquer pendant 8 sec., une fois par seconde. Pris dans le tourbillon de lames, vous pouvez vous déplacer mais pas utiliser d'autres capacités ; vous ne connaissez ni pitié, ni remords, ni peur, et seule la mort peut vous arrêter. ]], 0, 0, 65947, 1620, 11192, 0, 11190, 0, 0, 4, 2, -1, 0},
    [11192] = {11192, "Représailles", [[ Pendant 12 sec., vous contre-attaquez instantanément tout adversaire qui vous attaque au corps à corps (mais pas dans le dos). 'Représailles' peut être déclenché par un maximum de 20 attaques. ]], 0, 0, 65932, 1620, 11193, 0, 11190, 0, 0, 4, 2, -1, 0},
    [11193] = {11193, "Désarmement", [[ Prive l'adversaire de son arme portée en main droite, ou de son arme à distance, pendant 10 sec. ]], 0, 0, 65935, 1620, 11194, 0, 11190, 0, 0, 4, 2, -1, 0},
    [11194] = {11194, "Domination", [[ Donne instantanément l'ascendant sur l'adversaire. Vous infligez des dégâts d'arme normaux, augmentés de $[4 52$]$[2 52$]$[3 52$]$[1 52$] points. Cette capacité ne peut être utilisée que si la cible a esquivé une attaque. 'Domination' ne peut être bloquée, parée ni esquivée. ]], 0, 0, 65924, 1620, 11195, 0, 11190, 0, 0, 4, 2, -1, 0},
    [11195] = {11195, "Fissure d'armure", [[ Un coup qui endommage l'armure de l'adversaire et applique l'effet 'Fissure d'armure'. Cet effet réduit l'armure de 4 %, se cumule jusqu'à 5 fois et dure 30 sec. Le coup augmente aussi considérablement la menace (le niveau de menace dépend directement de la puissance d'attaque). ]], 0, 0, 65936, 1620, 11196, 0, 11190, 0, 0, 4, 2, -1, 0},
    [11196] = {11196, "Ruée", [[ Se précipite sur l'adversaire et l'étourdit pendant 1,5 sec. ]], 0, 0, 65927, 1620, 11197, 0, 11190, 0, 0, 4, 2, -1, 0},
    [11197] = {11197, "Coup fatal", [[ Coup cruel infligeant à l'adversaire des dégâts d'arme augmentés de $[4 570$]$[2 570$]$[3 570$]$[1 570$] points, laissant sur son corps une grave blessure qui réduit l'efficacité de tous les sorts de soins de 50 % pendant 10 sec. ]], 0, 0, 65926, 1620, 11198, 0, 11190, 0, 0, 4, 2, -1, 0},
    [11198] = {11198, "Lancer écrasant", [[ Lancer d'arme infligeant à l'adversaire des dégâts d'arme. Réduit l'armure de l'adversaire de 20 % pendant 10 sec., ou retire tous les effets d'invulnérabilité. ]], 0, 0, 65940, 1620, 11199, 0, 11190, 0, 0, 4, 2, -1, 0},
    [11199] = {11199, "Cri terrifiant", [[ Le guerrier pousse un cri terrifiant qui fige l'adversaire de peur pendant 8 sec. ]], 0, 0, 65931, 1620, 11200, 0, 11190, 0, 0, 4, 2, -1, 0},
    [11200] = {11200, "Accessoire JcJ", [[ Retire tous les effets de ralentissement et tous les effets de perte de contrôle du personnage. ]], 0, 0, 65547, 1620, 0, 0, 11190, 0, 0, 4, 2, 12, 0},
    [11201] = {11201, "Roujka", [[ Chasseresse combattant aux côtés des champions de la Horde après le combat contre le Seigneur Jaraxxus. ]], 29786, 0, 0, 1621, 11212, 11202, 0, 1, 0, 1, 0, -1, 0},
    [11202] = {11202, "Tir loyal", [[ Tir loyal infligeant à la cible des dégâts d'arme. ]], 0, 0, 65867, 1621, 11203, 0, 11201, 0, 0, 4, 2, -1, 0},
    [11203] = {11203, "Piège de glace", [[ Pose un piège de glace qui crée autour de lui une épaisse couche de glace pendant 30 sec. dès qu'un premier adversaire s'en approche. Tous les adversaires dans un rayon de 10 m sont ralentis de 50 % tant qu'ils restent dans la zone d'effet. Le piège dure 30 sec. Un seul piège peut être posé à la fois. ]], 0, 0, 65880, 1621, 11204, 0, 11201, 0, 0, 4, 2, -1, 0},
    [11204] = {11204, "Décrochage", [[ Vous bondissez en arrière, tentant de sortir du combat. ]], 0, 0, 65869, 1621, 11205, 0, 11201, 0, 0, 4, 2, -1, 0},
    [11205] = {11205, "Taillader les ailes", [[ Mutile l'adversaire, réduisant sa vitesse de déplacement de 50 % pendant 10 sec. ]], 0, 0, 66207, 1621, 11206, 0, 11201, 0, 0, 4, 2, -1, 0},
    [11206] = {11206, "Tir de précision", [[ Augmente les dégâts à distance de $[4 2625$]$[2 2625$]$[3 2625$]$[1 2625$] et réduit de 50 % l'efficacité des soins appliqués à la cible. Durée : 10 sec. ]], 0, 0, 65883, 1621, 11207, 0, 11201, 0, 0, 4, 2, -1, 0},
    [11207] = {11207, "Tir explosif", [[ Tir d'un projectile explosif infligeant à l'ennemi $[4 3265$]$[2 3265$]$[3 3265$]$[1 3265$] points de dégâts de feu. La charge continue d'infliger des dégâts à la cible chaque seconde pendant 2 sec. ]], 0, 0, 65866, 1621, 11208, 0, 11201, 0, 0, 4, 2, -1, 0},
    [11208] = {11208, "Endiguement", [[ Augmente de 100 % la chance de parade et de 100 % la chance d'esquiver les sorts des adversaires situés devant vous. Sous l'effet de cette capacité, vous ne pouvez pas attaquer. Durée : 5 sec. ]], 0, 0, 65871, 1621, 11209, 0, 11201, 0, 0, 4, 2, -1, 0},
    [11209] = {11209, "Morsure de vouivre", [[ Une morsure qui endort la cible pendant 30 sec. Tout dégât infligé interrompt l'effet du sort. Quand la cible se réveille, la morsure inflige $[4 3694$]$[2 3694$]$[3 3694$]$[1 3694$] points de dégâts de nature pendant 6 sec. Une seule 'Morsure' de chaque chasseur peut affecter chaque cible à la fois. ]], 0, 0, 65878, 1621, 11210, 0, 11201, 0, 0, 4, 2, -1, 0},
