    [11211] = {11211, "Accessoire JcJ", [[ Retire tous les effets de ralentissement et tous les effets de perte de contrôle du personnage. ]], 0, 0, 65547, 1621, 0, 0, 11201, 0, 0, 4, 2, 12, 0},
    [11212] = {11212, "Gorgrim Rupture-Sombre", [[ Chevalier de la mort combattant aux côtés des champions de la Horde après le combat contre le Seigneur Jaraxxus. ]], 29782, 0, 0, 1621, 11222, 11213, 0, 1, 0, 1, 0, -1, 0},
    [11213] = {11213, "Toucher de givre", [[ Inflige de 3355 à 3646 points de dégâts de givre et engourdit l'adversaire. L'afflige de la maladie 'Gel', qui inflige des dégâts périodiques et réduit la vitesse d'attaque au corps à corps et à distance de 14 % pendant 15 sec. ]], 0, 0, 66021, 1621, 11214, 0, 11212, 0, 0, 4, 2, -1, 0},
    [11214] = {11214, "Frappe de glace", [[ Inflige instantanément à l'adversaire 60 % des dégâts d'arme et 150 points de dégâts de givre supplémentaires. Cette attaque ne peut être esquivée, bloquée ni parée. ]], 0, 0, 66047, 1621, 11215, 0, 11212, 0, 0, 4, 2, -1, 0},
    [11215] = {11215, "Chaînes de glace", [[ Des chaînes de glace enserrent l'adversaire, réduisant sa vitesse de déplacement à 5 % de la normale. Chaque seconde, l'adversaire récupère $47805s2 % de sa vitesse de déplacement normale. Durée : $47805d. ]], 0, 0, 66020, 1621, 11216, 0, 11212, 0, 0, 4, 2, -1, 0},
    [11216] = {11216, "Visage de la mort", [[ Libère une charge d'énergie impie, infligeant $[4 7896$]$[2 7896$]$[3 7896$]$[1 7896$] points de dégâts de magie noire à l'adversaire ou soignant un allié mort-vivant de ${4625*1.5} points de vie. ]], 0, 0, 66019, 1621, 11217, 0, 11212, 0, 0, 4, 2, -1, 0},
    [11217] = {11217, "Gel", [[ Une maladie qui inflige des dégâts de givre toutes les 3 sec. et réduit la vitesse d'attaque au corps à corps et à distance de la cible de 14 % pendant 15 sec. ]], 0, 0, 67767, 1621, 11218, 0, 11212, 0, 0, 4, 2, -1, 0},
