    [11307] = {11307, "Étreinte de la nature", [[ Une fois activée, donne 100 % de chance que l'adversaire qui frappe l'invocateur soit immobilisé par la 'Colère des arbres'. Nombre de charges : 1. Durée : 45 sec. ]], 0, 0, 66071, 1621, 11308, 0, 11300, 0, 0, 4, 2, -1, 0},
