    [11314] = {11314, "Feu lunaire", [[ Brûle l'adversaire, lui infligeant $[4 3772$]$[2 3772$]$[3 3772$]$[1 3772$] points de dégâts de magie arcanique et $[4 6006$]$[2 6006$]$[3 6006$]$[1 6006$] points de dégâts supplémentaires de magie arcanique pendant 12 sec. ]], 0, 0, 65856, 1621, 11315, 0, 11310, 0, 0, 4, 2, -1, 0},
    [11315] = {11315, "Essaim d'insectes", [[ Un essaim d'insectes attaque l'adversaire, réduisant de 3 % sa chance de toucher au corps à corps et à distance et lui infligeant $[4 21303$]$[2 21303$]$[3 21303$]$[1 21303$] points de dégâts de nature sur 12 sec. ]], 0, 0, 65855, 1621, 11316, 0, 11310, 0, 0, 4, 2, -1, 0},
