    [11325] = {11325, "Toucher du vampire", [[ Inflige à l'adversaire $[4 19035$]$[2 19035$]$[3 19035$]$[1 19035$] points de dégâts de magie noire sur 15 sec. ]], 0, 0, 65490, 1621, 11326, 0, 11321, 0, 0, 4, 2, -1, 0},
    [11326] = {11326, "Torture de l'esprit", [[ Inflige à l'adversaire des dégâts de magie noire et réduit sa vitesse de déplacement pendant 3 sec. ]], 0, 0, 65488, 1621, 11327, 0, 11321, 0, 0, 4, 2, -1, 0},
    [11327] = {11327, "Dissipation de sorts", [[ Dissipe la magie agissant sur la cible, retirant jusqu'à 2 effets négatifs d'un allié ou jusqu'à 2 effets positifs d'un adversaire. ]], 0, 0, 65546, 1621, 11328, 0, 11321, 0, 0, 4, 2, -1, 0},
    [11328] = {11328, "Fusion avec les Ténèbres", [[ Vous vous dissolvez dans les Ténèbres. Tous les dégâts que vous subissez sont réduits de 90 %. Vous ne pouvez ni attaquer ni lancer de sorts, mais vous restaurez 6 % de mana chaque seconde pendant 6 sec. Ce sort peut être utilisé même si vous êtes étourdi, effrayé ou réduit au silence. Son utilisation dissipe les effets d'entrave et de limitation de mouvement, et confère une immunité à ceux-ci pendant la durée du sort. ]], 0, 0, 65544, 1621, 11329, 0, 11321, 0, 0, 4, 2, -1, 0},
    [11329] = {11329, "Mot des Ténèbres : Douleur", [[ Prononce le Mot des Ténèbres, qui inflige des dégâts de magie noire à l'adversaire toutes les 3 sec. pendant 15 sec. ]], 0, 0, 65541, 1621, 11330, 0, 11321, 0, 0, 4, 2, -1, 0},
    [11330] = {11330, "Explosion mentale", [[ Frappe l'esprit de la cible, infligeant $[4 8311$]$[2 8311$]$[3 8311$]$[1 8311$] points de dégâts de magie noire. ]], 0, 0, 65492, 1621, 11331, 0, 11321, 0, 0, 4, 2, -1, 0},
    [11331] = {11331, "Accessoire JcJ", [[ Retire tous les effets de ralentissement et tous les effets de perte de contrôle du personnage. ]], 0, 0, 65547, 1621, 0, 0, 11321, 0, 0, 4, 2, 12, 0},
    [11332] = {11332, "Narrok Brise-Acier", [[ Guerrier combattant aux côtés des champions de la Horde après le combat contre le Seigneur Jaraxxus. ]], 29793, 0, 0, 1621, 0, 11333, 0, 1, 0, 1, 0, -1, 0},
    [11333] = {11333, "Tourbillon de lames", [[ Fondre sur les adversaires proches en tourbillonnant et les attaquer pendant 8 sec., une fois par seconde. Pris dans le tourbillon de lames, vous pouvez vous déplacer mais pas utiliser d'autres capacités ; vous ne connaissez ni pitié, ni remords, ni peur, et seule la mort peut vous arrêter. ]], 0, 0, 65947, 1621, 11334, 0, 11332, 0, 0, 4, 2, -1, 0},
    [11334] = {11334, "Représailles", [[ Pendant 12 sec., vous contre-attaquez instantanément tout adversaire qui vous attaque au corps à corps (mais pas dans le dos). 'Représailles' peut être déclenché par un maximum de 20 attaques. ]], 0, 0, 65932, 1621, 11335, 0, 11332, 0, 0, 4, 2, -1, 0},
    [11335] = {11335, "Désarmement", [[ Prive l'adversaire de son arme portée en main droite, ou de son arme à distance, pendant 10 sec. ]], 0, 0, 65935, 1621, 11336, 0, 11332, 0, 0, 4, 2, -1, 0},
    [11336] = {11336, "Domination", [[ Donne instantanément l'ascendant sur l'adversaire. Vous infligez des dégâts d'arme normaux, augmentés de $[4 52$]$[2 52$]$[3 52$]$[1 52$] points. Cette capacité ne peut être utilisée que si la cible a esquivé une attaque. 'Domination' ne peut être bloquée, parée ni esquivée. ]], 0, 0, 65924, 1621, 11337, 0, 11332, 0, 0, 4, 2, -1, 0},
    [11337] = {11337, "Fissure d'armure", [[ Un coup qui endommage l'armure de l'adversaire et applique l'effet 'Fissure d'armure'. Cet effet réduit l'armure de 4 %, se cumule jusqu'à 5 fois et dure 30 sec. Le coup augmente aussi considérablement la menace (le niveau de menace dépend directement de la puissance d'attaque). ]], 0, 0, 65936, 1621, 11338, 0, 11332, 0, 0, 4, 2, -1, 0},
    [11338] = {11338, "Ruée", [[ Se précipite sur l'adversaire et l'étourdit pendant 1,5 sec. ]], 0, 0, 65927, 1621, 11339, 0, 11332, 0, 0, 4, 2, -1, 0},
    [11339] = {11339, "Coup fatal", [[ Coup cruel infligeant à l'adversaire des dégâts d'arme augmentés de $[4 570$]$[2 570$]$[3 570$]$[1 570$] points, laissant sur son corps une grave blessure qui réduit l'efficacité de tous les sorts de soins de 50 % pendant 10 sec. ]], 0, 0, 65926, 1621, 11340, 0, 11332, 0, 0, 4, 2, -1, 0},
    [11340] = {11340, "Lancer écrasant", [[ Lancer d'arme infligeant à l'adversaire des dégâts d'arme. Réduit l'armure de l'adversaire de 20 % pendant 10 sec., ou retire tous les effets d'invulnérabilité. ]], 0, 0, 65940, 1621, 11341, 0, 11332, 0, 0, 4, 2, -1, 0},
    [11341] = {11341, "Cri terrifiant", [[ Le guerrier pousse un cri terrifiant qui fige l'adversaire de peur pendant 8 sec. ]], 0, 0, 65931, 1621, 11342, 0, 11332, 0, 0, 4, 2, -1, 0},
    [11342] = {11342, "Accessoire JcJ", [[ Retire tous les effets de ralentissement et tous les effets de perte de contrôle du personnage. ]], 0, 0, 65547, 1621, 0, 0, 11332, 0, 0, 4, 2, 12, 0},
    [11400] = {11400, "Onyxia", [[ Onyxia est la mère de la lignée des dragons noirs d'Azeroth, installée dans son antre. Sous sa forme humaine, elle trame des intrigues ; sous sa forme de dragon, elle inspire la terreur. Comme tous les membres de sa lignée, empoisonnée par la folie des dieux anciens, elle ne cessera jamais de semer le chaos. Onyxia doit mourir. ]], 8570, 0, 0, 1651, 0, 11401, 0, 1, 0, 1, 0, -1, 0},
    [11401] = {11401, "Phase 1 : Fille d'Aile de Mort", [[ Onyxia s'éveille de son sommeil et attaque ses adversaires en utilisant ses capacités naturelles de dragon. ]], 0, 0, 0, 1651, 11406, 11402, 11400, 0, 0, 2, 2, -1, 0},
