    [11406] = {11406, "Phase 2 : Je vais tous vous brûler !", [[ À 66 % de ses points de vie, Onyxia bat des ailes et s'envole, se déplaçant au-dessus du champ de bataille en projetant des vagues de flammes, tout en invoquant ses serviteurs. ]], 0, 0, 0, 1651, 11409, 11407, 11400, 0, 0, 4, 2, -1, 0},
