    [11408] = {11408, "Souffle", [[ Le souffle enflammé d'Onyxia frappe tous les adversaires au sol, leur infligeant $[2 6615$]$[1 6615$] points de dégâts de feu. ]], 0, 0, 17086, 1651, 11415, 0, 11406, 0, 0, 4, 2, -1, 0},
    [11409] = {11409, "Phase 3 : Connaissez votre place !", [[ Lorsque les points de vie d'Onyxia tombent à 33 %, elle atterrit et la phase 3 commence. Immédiatement après l'atterrissage, elle utilise 'Rugissement tonitruant'. Durant cette phase, elle utilise de nouvelles capacités et cesse d'invoquer des serviteurs. ]], 0, 0, 0, 1651, 0, 11410, 11400, 0, 0, 4, 2, -1, 0},
