    [11425] = {11425, "Volonté de Sartharion", [[ La présence de Sartharion renforce les dragons du crépuscule, augmentant leurs points de vie maximum de 25 %. Cet effet augmente également les points de vie de Sartharion de 25 %. ]], 0, 0, 61254, 1616, 11426, 0, 11419, 0, 0, 4, 2, -1, 0},
