    [11712] = {11712, "Domination de l'esprit", [[ Soumet l'adversaire ciblé pendant 12 sec. L'adversaire soumis inflige 200% de dégâts supplémentaires et son efficacité de soins augmente de 500%. ]], 0, 0, 71289, 1625, 0, 0, 11706, 0, 0, 4, 2, 12, 0},
    [11713] = {11713, "Saurfang le Mortel", [[ Saurfang le Mortel, autrefois connu sous le nom de Dranosh Saurfang, fils du plus célèbre général orque, est le dernier boss du premier quartier de la Citadelle de la Couronne de glace. Après sa défaite, trois ailes de la Citadelle (l'Antre de la peste, la Salle Écarlate et les Galeries des Glacevol) s'ouvrent aux joueurs et peuvent être terminées dans n'importe quel ordre. ]], 30790, 0, 0, 1628, 0, 11714, 0, 1, 0, 1, 0, -1, 0},
    [11714] = {11714, "Puissance du sang", [[ Saurfang augmente de taille de 1% et inflige 1% de dégâts supplémentaires pour chaque unité de puissance du sang accumulée. ]], 0, 0, 72371, 1628, 11715, 0, 11713, 0, 0, 4, 2, -1, 0},
    [11715] = {11715, "Rune de sang", [[ Lors d'une attaque de mêlée, Saurfang draine les points de vie de la cible et récupère les siens en quantité multipliée. ]], 0, 0, 72410, 1628, 11716, 0, 11713, 0, 0, 4, 2, -1, 0},
    [11716] = {11716, "Liens de sang", [[ Lorsque les capacités et créatures invoquées de Saurfang infligent des dégâts, cela alimente la puissance du sang. ]], 0, 0, 72178, 1628, 11717, 0, 11713, 0, 0, 4, 2, -1, 0},
    [11717] = {11717, "Sang bouillonnant", [[ Fait bouillir le sang de l'adversaire, lui infligeant $[1 6000$]$[2 7500$]$[3 7500$]$[4 7500$] pts de dégâts physiques toutes les 3 sec. pendant 15 sec. ]], 0, 0, 72385, 1628, 11718, 0, 11713, 0, 0, 4, 2, -1, 0},
    [11718] = {11718, "Anneau de sang", [[ Un adversaire au hasard projette du sang autour de lui, infligeant $[1 9895$]$[2 12369$]$[3 12369$]$[4 12369$] pts de dégâts physiques aux adversaires proches. ]], 0, 0, 72380, 1628, 11719, 0, 11713, 0, 0, 4, 2, -1, 0},
    [11719] = {11719, "Marque du guerrier déchu", [[ Les attaques de mêlée de Saurfang le Mortel touchent également la cible marquée, infligeant des dégâts physiques supplémentaires. Si la cible meurt sous l'effet de cette marque, Saurfang récupère 5% de ses points de vie maximum. ]], 0, 0, 72293, 1628, 11720, 0, 11713, 0, 0, 4, 2, -1, 0},
    [11720] = {11720, "Furie", [[ Saurfang entre en furie, augmentant sa vitesse d'attaque de 30%. ]], 0, 0, 72737, 1628, 11721, 0, 11713, 0, 0, 4, 2, -1, 0},
    [11721] = {11721, "Invocation de monstres de sang", [[ Deux monstres de sang répondent à l'appel de Saurfang. ]], 0, 0, 72173, 1628, 11722, 0, 11713, 0, 0, 4, 2, -1, 0},
    [11722] = {11722, "Monstre de sang", [[ La rage de Saurfang prenant vie, incarnée dans une aberration répugnante, représentant une menace pour le raid. ]], 31107, 0, 0, 1628, 0, 11723, 11713, 0, 0, 4, 2, -1, 0},
