    [11724] = {11724, "Peau résistante", [[ La peau de cette créature est extrêmement résistante aux influences extérieures. Elle réduit les dégâts de zone de 95% et les dégâts de maladie de 70%. ]], 0, 0, 72723, 1628, 11725, 0, 11722, 0, 0, 4, 2, -1, 0},
