    [11730] = {11730, "Spores gazeuses", [[ Libère des spores gazeuses, infectant 2 cibles au hasard (3 cibles au hasard dans les raids à 25 joueurs). La spore explose au bout de 12 secondes et inflige $[1 2401$]$[2 3001$]$[3 3001$]$[4 3001$] pts de dégâts à tous les alliés proches. Les dégâts des spores gazeuses renforcent l'immunité de la cible, augmentant sa résistance à la putréfaction. ]], 0, 0, 69278, 1629, 11731, 0, 11726, 0, 0, 4, 2, -1, 0},
    [11731] = {11731, "Vapeurs putrides dans les poumons", [[ L'inhalation des vapeurs putrides augmente les dégâts infligés de 25% et la vitesse d'attaque de 25%. ]], 0, 0, 69166, 1629, 11732, 0, 11726, 0, 0, 4, 2, -1, 0},
