    [11760] = {11760, "Phase 3 : Mutation effrénée !", [[ Le Professeur Van Poison se met à boire toutes les potions les unes après les autres ! ]], 0, 0, 71893, 1631, 11765, 11761, 11747, 0, 0, 4, 2, -1, 0},
    [11761] = {11761, "Force du mutant", [[ Augmente les dégâts infligés de 50%, augmente la vitesse d'attaque de 50%. À chaque attaque, la mutation progresse, infligeant à l'invocateur des dégâts croissants toutes les 3 sec. ]], 0, 0, 71603, 1631, 11762, 0, 11760, 0, 0, 4, 2, -1, 0},
