    [11779] = {11779, "Prince Valanar", [[ L'un des membres du Conseil des Princes de sang, il commence le combat sous l'effet de la "Sphère de sang". ]], 30858, 0, 0, 1632, 11784, 11780, 0, 1, 0, 1, 0, -1, 0},
    [11780] = {11780, "Bombe cinétique", [[ Invoque une sphère d'énergie cinétique qui tombe lentement vers le sol et explose au contact, infligeant 11340-13860 pts de dégâts physiques aux adversaires dans une grande zone et les repoussant. Les attaques à distance chargent la sphère, retardant sa chute et la faisant remonter. ]], 0, 0, 72052, 1632, 11781, 0, 11779, 0, 0, 4, 2, -1, 0},
    [11781] = {11781, "Tourbillon secouant", [[ Crée près de la cible un tourbillon d'énergie qui inflige des dégâts aux adversaires proches et les repousse. ]], 0, 0, 72037, 1632, 11782, 0, 11779, 0, 0, 4, 2, -1, 0},
