    [11972] = {11972, "Tempérament violent", [[ Gruul accumule de la rage. Chaque joueur tué augmente sa jauge de rage de 20 unités. Toutes les 6 secondes, Gruul accumule 1 pt de rage. ]], 0, 0, 305198, 1565, 11973, 0, 11966, 0, 0, 4, 2, 12, 0},
    [11973] = {11973, "Coup étourdissant", [[ Gruul s'abat sur sa cible actuelle de toute sa puissance, infligeant $[4 200001$]$[2 485002$]$[1 200001$] pts de dégâts physiques répartis entre toutes les cibles dans un cône devant lui et les repoussant de 20 m. Chaque cible touchée accorde au boss une charge de "Frénésie de Gruul".
Si la capacité touche moins de 10 adversaires, Gruul entre en frénésie, accumulant 100 pts de rage et utilisant immédiatement le "Coup infernal". ]], 0, 0, 305183, 1565, 11975, 11974, 11966, 0, 0, 4, 2, 12, 0},
    [11974] = {11974, "Frénésie de Gruul", [[ Gruul intensifie son assaut, puisant sa force dans sa rage. Les dégâts infligés augmentent de 5%. ]], 0, 0, 305184, 1565, 0, 0, 11973, 0, 0, 4, 2, 12, 0},
