    [11976] = {11976, "Courroux ardent", [[ Une énergie ignée fait rage dans le corps de Gruul, augmentant ses dégâts de feu infligés de 10%. ]], 0, 0, 305187, 1565, 0, 0, 11975, 0, 0, 4, 2, 12, 0},
