    [12045] = {12045, "Phase 1 : À moi, Minuit !", [[ Attumen commence le combat monté sur Minuit et combat ainsi jusqu'à ce que son niveau de santé tombe à 50%. ]], 0, 0, 0, 1553, 12050, 12046, 12041, 0, 0, 4, 2, 12, 0},
    [12046] = {12046, "Coup fatal", [[ Attumen frappe d'un coup d'épée. Tous les ennemis dans un rayon de 12 m devant Attumen subissent $[3 25000$]$[1 80000$] points de dégâts physiques. Leur santé maximale est réduite à 50% de sa valeur normale pendant 5 sec. ]], 0, 0, 305250, 1553, 12047, 0, 12045, 0, 0, 4, 2, 12, 0},
    [12047] = {12047, "Présence insaisissable", [[ L'incantateur invoque un fantôme qui poursuit les ennemis. Ce fantôme inflige à tous les joueurs $[3 5000$]$[1 16000$] points de dégâts de magie sombre toutes les 1 sec. jusqu'à ce qu'il soit dissipé. Si l'effet est dissipé sur un joueur qui n'en est pas la cible marquée, tous les joueurs subissent $[3 25000$]$[1 80000$] points de dégâts de magie sombre. ]], 0, 0, 305251, 1553, 12048, 0, 12045, 0, 0, 4, 2, 12, 0},
    [12048] = {12048, "Cheval fantôme", [[ L'incantateur invoque un cheval fantomatique qui charge un joueur aléatoire, lui infligeant $[3 17500$]$[1 56000$] points de dégâts physiques et le repoussant de 5 mètres. ]], 0, 0, 305255, 1553, 0, 12049, 12045, 0, 0, 4, 2, 12, 0},
    [12049] = {12049, "Ruée", [[ L'incantateur se jette sur l'ennemi, lui infligeant $[3 17500$]$[1 56000$] points de dégâts physiques et le repoussant de 5 mètres. ]], 0, 0, 305256, 1553, 0, 0, 12048, 0, 0, 4, 2, 12, 0},
    [12050] = {12050, "Phase 2 : Rage du chasseur", [[ Attumen s'enflamme de rage, descend de Minuit et acquiert de nouvelles capacités. Durant cette phase, Minuit est invulnérable aux dégâts. La phase dure jusqu'à la mort d'Attumen. ]], 0, 0, 0, 1553, 12055, 12051, 12041, 0, 0, 4, 2, 12, 0},
    [12051] = {12051, "Coup fatal", [[ Attumen frappe d'un coup d'épée. Tous les ennemis dans un rayon de 12 m devant Attumen subissent $[3 18750$]$[1 60000$] points de dégâts physiques. Leur santé maximale est réduite à 35% de sa valeur normale pendant 10 sec. ]], 0, 0, 305257, 1553, 12052, 0, 12050, 0, 0, 4, 2, 12, 0},
    [12052] = {12052, "Tourments partagés", [[ L'incantateur assène un puissant coup d'épée en un large arc, infligeant $[3 187500$]$[1 600000$] points de dégâts de magie sombre, répartis équitablement entre toutes les cibles touchées par l'épée dans un rayon de 12 m. ]], 0, 0, 305259, 1553, 12053, 0, 12050, 0, 0, 4, 2, 12, 0},
    [12053] = {12053, "Impulsion spectrale", [[ L'incantateur invoque un fantôme qui possède un joueur aléatoire. Le joueur possédé subit $[3 7500$]$[1 24000$] points de dégâts de magie sombre toutes les 2 secondes, et sa vitesse de déplacement est réduite de 30%. ]], 0, 0, 305260, 1553, 12054, 0, 12050, 0, 0, 4, 2, 12, 0},
