    [12056] = {12056, "Galop", [[ Minuit se cabre et charge en avant, infligeant $[3 56250$]$[1 180000$] points de dégâts de feu à tous les ennemis devant elle. ]], 0, 0, 305263, 1553, 12057, 0, 12055, 0, 0, 4, 2, 12, 0},
    [12057] = {12057, "Piétinement puissant", [[ Minuit se cabre et frappe le sol de ses sabots avant. Tous les joueurs subissent $[3 16250$]$[1 52000$] points de dégâts de feu, et l'incantation de tout sort dans la zone d'effet est interrompue pendant 4 sec. ]], 0, 0, 305264, 1553, 12058, 0, 12055, 0, 0, 4, 2, 12, 0},
