    [12065] = {12065, "Aveuglement", [[ Aveugle la cible. Elle erre sans but pendant 10 sec. maximum. Tout dégât infligé annule l'effet. ]], 0, 0, 34694, 1554, 12066, 0, 12060, 0, 0, 4, 2, 3, 0},
    [12066] = {12066, "Phase 1 : Réception solennelle", [[ Moroès entame le combat contre ses ennemis sans manquer aux bonnes manières, renouvelant périodiquement les plats sur les tables et invoquant des danseurs. ]], 0, 0, 0, 1554, 12077, 12067, 12060, 0, 0, 4, 2, 12, 0},
    [12067] = {12067, "Blessure lacérante", [[ Lacère la chair de l'ennemi, lui infligeant $[3 25000$]$[1 80000$] points de dégâts physiques. La cible subit $[3 7500$]$[1 24000$] points de dégâts physiques par seconde pendant 7 sec. Si l'ennemi est déjà affecté par « Piqûre empoisonnée », il meurt instantanément. ]], 0, 0, 305463, 1554, 12068, 0, 12066, 0, 0, 4, 2, 12, 0},
    [12068] = {12068, "Danseurs fantomatiques", [[ Plusieurs danseurs fantomatiques apparaissent à des points libres aléatoires de la salle et forment une ronde. Tant qu'aucun joueur ne se trouve au centre de la ronde, celle-ci utilise la capacité « Soupirs mélancoliques ». Un joueur qui se retrouve au centre de la ronde perd le contrôle de son personnage pendant 10 secondes et se joint à la danse. Une fois la danse terminée, la ronde disparaît et le joueur reçoit l'effet « Épuisement ». ]], 0, 0, 305472, 1554, 12072, 12069, 12066, 0, 0, 4, 2, 12, 0},
    [12069] = {12069, "Soupirs mélancoliques", [[ Les danseurs fantomatiques sont attristés que leur art reste sans attention. Toutes les 3 sec., ils soupirent tristement, empêchant tous les ennemis de lancer des sorts pendant 2 sec. et leur infligeant $[3 5000$]$[1 16000$] points de dégâts de magie sombre. ]], 0, 0, 305476, 1554, 12070, 0, 12068, 0, 0, 4, 2, 12, 0},
    [12070] = {12070, "Danse", [[ Vous dansez irrésistiblement au centre de la ronde, et aucune force ne peut vous en détourner pendant les 10 prochaines sec. ]], 0, 0, 305478, 1554, 12071, 0, 12068, 0, 0, 4, 2, 12, 0},
    [12071] = {12071, "Épuisement", [[ Vous êtes épuisé et pouvez à peine vous déplacer. Les dégâts que vous infligez sont réduits de 80%, l'efficacité des soins que vous prodiguez est réduite de 80%. Vous ressentez clairement le besoin de vous asseoir et de vous restaurer. ]], 0, 0, 305479, 1554, 0, 0, 12068, 0, 0, 4, 2, 12, 0},
    [12072] = {12072, "Mets de fête", [[ Invoque un cuisinier qui dispose des mets appétissants sur les tables vides. ]], 0, 0, 305480, 1554, 0, 12073, 12066, 0, 0, 4, 2, 12, 0},
    [12073] = {12073, "Rôti excellent", [[ Le plat que vous avez mangé était une viande d'excellente qualité. Les dégâts que vous infligez sont augmentés de 20%. Vous êtes rassasié et ne pouvez pas participer à la ronde ou au festin pendant 60 sec. ]], 0, 0, 305484, 1554, 12074, 0, 12072, 0, 0, 4, 2, 12, 0},
    [12074] = {12074, "Poisson étrange", [[ Le plat que vous avez mangé était une variété de poisson qui vous semble vaguement familière. Vous récupérez 5% de votre réserve de mana maximale toutes les 5 secondes. Vous êtes rassasié et ne pouvez pas participer à la ronde ou au festin pendant 60 sec. ]], 0, 0, 305485, 1554, 12075, 0, 12072, 0, 0, 4, 2, 12, 0},
    [12075] = {12075, "Pudding effrayant", [[ Vous doutez encore que manger cette bouillie ait été une bonne idée. Votre vitesse de déplacement est réduite de 60% et vous subissez $[3 12500$]$[1 40000$] points de dégâts de nature toutes les 5 sec. Vous êtes rassasié et ne pouvez pas participer à la ronde ou au festin pendant 60 sec. ]], 0, 0, 305486, 1554, 12076, 0, 12072, 0, 0, 4, 2, 12, 0},
    [12076] = {12076, "Léger mécontentement", [[ Moroès semble encore plus renfrogné que d'habitude, car les invités ne veulent pas apprécier les plats proposés lors de cette réception. Les dégâts qu'il subit, ainsi que ses alliés, sont réduits de 10%. Cumulable jusqu'à 10 fois. ]], 0, 0, 305487, 1554, 0, 0, 12072, 0, 0, 4, 2, 12, 0},
    [12077] = {12077, "Phase 2 : Série de meurtres", [[ La réception est terminée et les bonnes manières sont oubliées. Moroès entame un véritable combat, alternant coups fatals, ruses perfides et poison. Tous les plats et danseurs existants disparaissent. ]], 0, 0, 0, 1554, 0, 12078, 12060, 0, 0, 4, 2, 12, 0},
    [12078] = {12078, "Mécontentement envers les invités", [[ Moroès est très mécontent que vous ignoriez sa merveilleuse réception et ses jeux. Les dégâts qu'il inflige sont augmentés de 500%, et ceux qu'il subit sont réduits de 90%. ]], 0, 0, 305471, 1554, 12079, 0, 12077, 0, 0, 4, 2, 12, 0},
    [12079] = {12079, "Blessure lacérante", [[ Lacère la chair de l'ennemi, lui infligeant $[3 25000$]$[1 80000$] points de dégâts physiques. La cible subit $[3 7500$]$[1 24000$] points de dégâts physiques par seconde pendant 7 sec. Si l'ennemi est déjà affecté par « Piqûre empoisonnée », il meurt instantanément. ]], 0, 0, 305463, 1554, 12080, 0, 12077, 0, 0, 4, 2, 12, 0},
    [12080] = {12080, "Piqûre empoisonnée", [[ Un coup instantané infligeant $[3 21875$]$[1 70000$] points de dégâts de nature et empoisonnant l'ennemi, lui infligeant $[3 3750$]$[1 12000$] points de dégâts de nature par seconde pendant 7 sec. Si l'ennemi est déjà affecté par « Blessure lacérante », il meurt instantanément. ]], 0, 0, 305464, 1554, 12081, 0, 12077, 0, 0, 4, 2, 12, 0},
    [12081] = {12081, "Série de meurtres", [[ Moroès traverse les ombres, apparaissant successivement dans le dos de chacun de ses ennemis, en commençant par le plus proche, et leur assène un coup dévastateur. Les trois derniers coups affligent les ennemis de « Garrot ». ]], 0, 0, 305460, 1554, 12083, 12082, 12077, 0, 0, 4, 2, 12, 0},
    [12082] = {12082, "Garrot", [[ Subit $[3 5000$]$[1 16000$] points de dégâts physiques toutes les 3 sec. L'efficacité des sorts de soins reçus est réduite de 33%. ]], 0, 0, 305462, 1554, 0, 0, 12081, 0, 0, 4, 2, 12, 0},
    [12083] = {12083, "Lancer mortel", [[ Moroès lance un couteau droit dans le cœur de l'ennemi le plus éloigné, lui infligeant d'énormes dégâts qui font chuter sa santé actuelle à $[3 12$]$[1 40$]% de son maximum. L'ennemi touché reçoit la « Marque de la mort ». ]], 0, 0, 305469, 1554, 0, 12084, 12077, 0, 0, 4, 2, 12, 0},
    [12084] = {12084, "Marque de la mort", [[ Votre cœur vient d'être transpercé par le couteau de Moroès. Si votre santé n'atteint pas 90% ou plus dans les 8 sec, vous mourrez. ]], 0, 0, 305470, 1554, 0, 0, 12083, 0, 0, 4, 2, 12, 0},
    [12085] = {12085, "Seigneur Crispin Ference", [[ Invité de Moroès, guerrier protecteur. ]], 16638, 0, 0, 1554, 12089, 12086, 0, 1, 0, 1, 0, -1, 0},
    [12086] = {12086, "Défense de fer", [[ Réduit de 75% les dégâts physiques et magiques subis par l'incantateur pendant 15 sec. ]], 0, 0, 29390, 1554, 12087, 0, 12085, 0, 0, 4, 2, -1, 0},
    [12087] = {12087, "Coup de bouclier", [[ Assène un puissant coup de bouclier à l'ennemi. L'ennemi subit des dégâts physiques et son incantation est interrompue. ]], 0, 0, 11972, 1554, 12088, 0, 12085, 0, 0, 4, 2, -1, 0},
    [12088] = {12088, "Désarmement", [[ Désarme l'ennemi, l'empêchant d'attaquer avec son arme pendant 10 sec. ]], 0, 0, 8379, 1554, 0, 0, 12085, 0, 0, 4, 2, -1, 0},
    [12089] = {12089, "Seigneur Robin Daris", [[ Invité de Moroès, guerrier berserker. ]], 19328, 0, 0, 1554, 12093, 12090, 0, 1, 0, 1, 0, -1, 0},
    [12090] = {12090, "Coup fatal", [[ Inflige 125% des dégâts de l'arme à l'ennemi et lui laisse une blessure grave, réduisant l'efficacité de tout sort de soins de 50% pendant 5 sec. ]], 0, 0, 29572, 1554, 12091, 0, 12089, 0, 0, 4, 2, -1, 0},
    [12091] = {12091, "Tourbillon", [[ Tournoyant, l'incantateur frappe les ennemis proches, infligeant à chacun des dégâts normaux et $[3 375$]$[1 1200$] points de dégâts supplémentaires. Durée : 2 sec. ]], 0, 0, 29573, 1554, 12092, 0, 12092, 0, 0, 4, 2, -1, 0},
    [12092] = {12092, "Tendons tranchés", [[ Inflige 20% des dégâts de l'arme à l'ennemi et réduit sa vitesse de déplacement pendant 10 sec. ]], 0, 0, 9080, 1554, 0, 0, 12089, 0, 0, 4, 2, -1, 0},
    [12093] = {12093, "Baron Rafe Dreuger", [[ Invité de Moroès, paladin vindicateur. ]], 16637, 0, 0, 1554, 12096, 12094, 0, 1, 0, 1, 0, -1, 0},
    [12094] = {12094, "Marteau de la justice", [[ Étourdit l'ennemi, l'empêchant de se déplacer et d'attaquer pendant 6 sec. ]], 0, 0, 13005, 1554, 12095, 0, 12093, 0, 0, 4, 2, -1, 0},
    [12095] = {12095, "Justice de l'obéissance", [[ Abat la justice sur l'ennemi, lui infligeant $[3 1863$]$[1 5964$] points de dégâts sacrés. ]], 0, 0, 29386, 1554, 0, 0, 12093, 0, 0, 4, 2, -1, 0},
    [12096] = {12096, "Dame Keira Berrybuck", [[ Invitée de Moroès, paladin soigneuse. ]], 16639, 0, 0, 1554, 12100, 12097, 0, 1, 0, 1, 0, -1, 0},
    [12097] = {12097, "Grande bénédiction de puissance", [[ Confère à toutes les cibles alliées proches une bénédiction augmentant leur puissance d'attaque de 550 pendant 300 min. ]], 0, 0, 29381, 1554, 12098, 0, 12096, 0, 0, 4, 2, -1, 0},
    [12098] = {12098, "Lumière des cieux", [[ Invoque les pouvoirs de la Lumière pour soigner un allié de $[3 6430$]$[1 20576$] points. ]], 0, 0, 29562, 1554, 12099, 0, 12099, 0, 0, 4, 2, -1, 0},
    [12099] = {12099, "Bouclier divin", [[ Protège l'incantateur de toutes les attaques et sorts pendant 10 sec., mais réduit sa vitesse d'attaque de 50% durant cette période. ]], 0, 0, 29382, 1554, 0, 0, 12096, 0, 0, 4, 2, -1, 0},
    [12100] = {12100, "Dame Catriona von'Indi", [[ Invitée de Moroès, prêtresse soigneuse. ]], 16640, 0, 0, 1554, 12105, 12101, 0, 1, 0, 1, 0, -1, 0},
    [12101] = {12101, "Dissipation de sort", [[ Dissipe les effets magiques de la cible, retirant 1 effet négatif d'un allié ou 1 effet positif d'un ennemi. ]], 0, 0, 15090, 1554, 12102, 0, 12100, 0, 0, 4, 2, -1, 0},
    [12102] = {12102, "Mot de pouvoir : Bouclier", [[ Protège un allié d'un bouclier actif pendant 30 sec. et absorbant $[3 31250$]$[1 100000$] points de dégâts physiques ou magiques. Tant que le bouclier est actif, les attaques physiques n'interrompent pas l'incantation. ]], 0, 0, 29408, 1554, 12103, 0, 12100, 0, 0, 4, 2, -1, 0},
    [12103] = {12103, "Grand soin", [[ Invoque les pouvoirs de la Lumière pour soigner un allié, lui rendant $[3 16800$]$[1 53760$] points de vie. ]], 0, 0, 29564, 1554, 12104, 0, 12100, 0, 0, 4, 2, -1, 0},
    [12104] = {12104, "Feu sacré", [[ L'ennemi est enveloppé de flammes, le brûlant et lui infligeant des dégâts de feu supplémentaires toutes les 2 sec. pendant 8 sec. ]], 0, 0, 29563, 1554, 0, 0, 12100, 0, 0, 4, 2, -1, 0},
    [12105] = {12105, "Baronne Dorothea Millstipe", [[ Invitée de Moroès, prêtresse des ténèbres. ]], 19327, 0, 0, 1554, 0, 12106, 0, 1, 0, 1, 0, -1, 0},
    [12106] = {12106, "Torture mentale", [[ Inflige des dégâts de magie sombre à l'ennemi et réduit sa vitesse de déplacement pendant 6 sec. ]], 0, 0, 29407, 1554, 12107, 0, 12105, 0, 0, 4, 2, -1, 0},
    [12107] = {12107, "Apparence des ténèbres", [[ Adopte l'Apparence des ténèbres, augmentant les dégâts de magie sombre infligés de 20% et réduisant les dégâts physiques subis en mêlée de 20%. L'Apparence des ténèbres persiste jusqu'à annulation. ]], 0, 0, 29406, 1554, 12108, 0, 12105, 0, 0, 4, 2, -1, 0},
    [12108] = {12108, "Combustion de mana", [[ Un éclair qui consume le mana. Pour chaque point de mana consumé par l'éclair, la victime subit 0,5 point de dégâts. ]], 0, 0, 29405, 1554, 0, 0, 12105, 0, 0, 4, 2, -1, 0},
    [12109] = {12109, "Vierge de la Vertu", [[ La Vierge de la Vertu, pure créature des Titans, est le troisième boss de Karazhan et combat en s'appuyant sur sa magie de lumière. ]], 16198, 0, 0, 1555, 0, 12110, 0, 1, 0, 1, 0, -1, 0},
    [12110] = {12110, "Pénitence", [[ Plonge toutes les cibles hostiles proches dans une profonde méditation, les paralysant pendant 12 sec. L'effet est dissipé dès qu'un dégât est infligé. ]], 0, 0, 29511, 1555, 12111, 0, 12109, 0, 0, 4, 2, 3, 0},
    [12111] = {12111, "Feu sacré", [[ L'ennemi est enveloppé de flammes, le brûlant et lui infligeant des dégâts de feu supplémentaires toutes les 2 sec. pendant 12 sec. ]], 0, 0, 29522, 1555, 12112, 0, 12109, 0, 0, 4, 2, 3, 0},
    [12112] = {12112, "Colère des cieux", [[ Envoie dans toutes les directions des charges d'énergie sacrée, infligeant $[3 2505$]$[1 8016$] points de dégâts sacrés à tous les ennemis dans un rayon de 80 m. Les dégâts augmentent de 40% à chaque rebond. ]], 0, 0, 32445, 1555, 12113, 0, 12109, 0, 0, 4, 2, 3, 0},
    [12113] = {12113, "Terre sacrée", [[ Inflige $[3 978$]$[1 3132$] points de dégâts sacrés et empêche l'incantation de sorts pendant 1 sec. ]], 0, 0, 29512, 1555, 12114, 0, 12109, 0, 0, 4, 2, 3, 0},
    [12114] = {12114, "Berserk", [[ Augmente la vitesse d'attaque et de déplacement de l'incantateur de 150% et les dégâts qu'il inflige de 500% pendant 300 min. Confère l'immunité aux effets de provocation. ]], 0, 0, 26662, 1555, 12115, 0, 12109, 0, 0, 4, 2, 3, 0},
    [12115] = {12115, "Éclair sacré", [[ Inflige à un joueur $[3 13750$]$[1 44000$] points de dégâts sacrés et se propage à d'autres joueurs. Les dégâts augmentent de 30% à chaque nouvelle cible. ]], 0, 0, 305270, 1555, 12116, 0, 12109, 0, 0, 4, 2, 12, 0},
    [12116] = {12116, "Terre sacrée", [[ Frappe la cible de magie de lumière ; 5 secondes plus tard, une parcelle de terre sacrée apparaît sous elle, infligeant $[3 5625$]$[1 18000$] points de dégâts sacrés toutes les 2 sec. pendant 20 sec. à tous les joueurs présents dans la zone. Cet effet est cumulable jusqu'à 10 fois. ]], 0, 0, 305271, 1555, 12117, 0, 12109, 0, 0, 4, 2, 12, 0},
    [12117] = {12117, "Choc des cieux", [[ Inflige à tous les ennemis $[3 25000$]$[1 80000$] points de dégâts sacrés et augmente les dégâts sacrés subis de 35%. Effet cumulable jusqu'à 30 fois. ]], 0, 0, 305276, 1555, 12118, 0, 12109, 0, 0, 4, 2, 12, 0},
    [12118] = {12118, "Pénitence universelle", [[ Paralyse tous les joueurs pendant 30 sec., ou jusqu'à ce qu'ils subissent des dégâts du sort « Terre sacrée ». Après avoir lancé « Pénitence universelle », la Vierge de la Vertu lance « Foyer de purification » et « Rempart sacré ». Elle lance ensuite périodiquement « Colère des cieux » jusqu'à ce que l'effet « Rempart sacré » se dissipe. ]], 0, 0, 305277, 1555, 12119, 0, 12109, 0, 0, 4, 2, 12, 0},
    [12119] = {12119, "Foyer de purification", [[ Invoque $[3 2$]$[1 8$] foyers de purification, reliés par un rayon de magie de lumière concentrée qui inflige $[3 43750$]$[1 140000$] points de dégâts sacrés à tous les ennemis qui le touchent. ]], 0, 0, 305279, 1555, 12121, 12120, 12109, 0, 0, 4, 2, 12, 0},
    [12120] = {12120, "Rayon de lumière", [[ Un rayon de magie de lumière concentrée qui inflige $[3 43750$]$[1 140000$] points de dégâts sacrés à tous les ennemis qui le touchent. ]], 0, 0, 305280, 1555, 0, 0, 12119, 0, 0, 4, 2, 12, 0},
    [12121] = {12121, "Rempart sacré", [[ Absorbe jusqu'à $[3 750000$]$[1 2400000$] points de dégâts et rend la Vierge de la Vertu insensible aux effets d'interruption. ]], 0, 0, 305285, 1555, 12122, 0, 12109, 0, 0, 4, 2, 12, 0},
    [12122] = {12122, "Colère des cieux", [[ Inflige $[3 93750$]$[1 300000$] points de dégâts sacrés à tous les ennemis. ]], 0, 0, 305286, 1555, 0, 0, 12109, 0, 0, 4, 2, 12, 0},
    [12123] = {12123, "« Le Petit Chaperon Rouge »", [[ Les représentations de l'Opéra de Karazhan changent.

Imaginez un instant que cette paisible vieille dame attende la visite de sa petite-fille... Cette charmante dame aux cheveux gris pourrait-elle vraiment vous effrayer ? ]], 0, 0, 0, 1556, 12128, 12124, 0, 1, 0, 1, 0, 3, 0},
    [12124] = {12124, "Le grand méchant loup", [[ Dans la représentation du « Petit Chaperon Rouge », vous devez affronter le terrible loup et le vaincre. ]], 17053, 0, 0, 1556, 0, 12125, 12123, 0, 0, 4, 2, 3, 0},
    [12125] = {12125, "Coup ample", [[ Étourdit tous les ennemis se trouvant devant l'incantateur pendant 4 sec. ]], 0, 0, 30761, 1556, 12126, 0, 12124, 0, 0, 4, 2, 3, 0},
    [12126] = {12126, "Hurlement terrifiant", [[ Les ennemis proches fuient, terrifiés, pendant 3 sec. ]], 0, 0, 30752, 1556, 12127, 0, 12124, 0, 0, 4, 2, 3, 0},
    [12127] = {12127, "Petit Chaperon Rouge", [[ La cible devient le Petit Chaperon Rouge. Cela augmente les chances que le grand méchant loup l'attrape et tente de l'avaler ! ]], 0, 0, 30753, 1556, 0, 0, 12124, 0, 0, 4, 2, 3, 0},
    [12128] = {12128, "« Le Magicien d'Oz »", [[ Les représentations de l'Opéra de Karazhan changent.

Aujourd'hui, nous allons sonder les profondeurs de l'âme humaine aux côtés de cette petite fille perdue, que de fidèles compagnons aident à retrouver le chemin de la maison ! Parviendra-t-elle à survivre ? Reverra-t-elle son foyer ? Seul le temps nous le dira. Et maintenant... que le spectacle commence ! ]], 0, 0, 0, 1556, 12148, 12129, 0, 0, 0, 4, 2, 3, 0},
    [12129] = {12129, "Dorothée", [[ Dorothée utilise la magie de givre et invoque Toto pour l'aider. ]], 17069, 0, 0, 1556, 12134, 12130, 12128, 0, 0, 4, 2, 3, 0},
    [12130] = {12130, "Flèche d'eau", [[ Tire sur l'ennemi une flèche d'eau, infligeant $[3 1958$]$[1 6266$] points de dégâts de givre. ]], 0, 0, 31012, 1556, 12131, 0, 12129, 0, 0, 4, 2, 3, 0},
    [12131] = {12131, "Invocation de Toto", [[ Invoque un chien aboyeur qui étourdira les ennemis proches. ]], 0, 0, 31014, 1556, 0, 12132, 12129, 0, 0, 4, 2, 3, 0},
    [12132] = {12132, "Toto", [[ Le familier de Dorothée. Représente un danger au corps à corps. ]], 17079, 0, 0, 1556, 0, 12133, 12131, 0, 0, 4, 2, 3, 0},
    [12133] = {12133, "Jappement agaçant", [[ Immobilise l'ennemi et le réduit au silence, l'empêchant d'attaquer ou de lancer des sorts pendant 2 sec. ]], 0, 0, 31015, 1556, 0, 0, 12132, 0, 0, 4, 2, 3, 0},
    [12134] = {12134, "L'Homme de Paille", [[ Une créature mécanique faite de... paille. Vulnérable au feu, mais représente néanmoins un danger pour le groupe. ]], 17076, 0, 0, 1556, 12138, 12135, 12128, 0, 0, 4, 2, 3, 0},
    [12135] = {12135, "Assommoir", [[ Un coup à la tête qui fait perdre connaissance à la cible pendant 3 sec. ]], 0, 0, 31046, 1556, 12136, 0, 12134, 0, 0, 4, 2, 3, 0},
    [12136] = {12136, "Effacement de mémoire", [[ La cible oublie ce qu'elle allait dire et reste muette pendant 4 sec. ]], 0, 0, 31069, 1556, 12137, 0, 12134, 0, 0, 4, 2, 3, 0},
    [12137] = {12137, "Paille en feu", [[ Vous êtes en feu ! ]], 0, 0, 31075, 1556, 0, 0, 12134, 0, 0, 4, 2, 3, 0},
    [12138] = {12138, "L'Homme de Fer-Blanc", [[ Un bûcheron de fer animé, doucement rongé par la rouille, mais toujours aussi puissant. ]], 17187, 0, 0, 1556, 12141, 12139, 12128, 0, 0, 4, 2, 3, 0},
    [12139] = {12139, "Frappe tranchante", [[ Inflige des dégâts physiques à l'ennemi et à ses alliés proches, touchant jusqu'à 3 cibles. ]], 0, 0, 31043, 1556, 12140, 0, 12138, 0, 0, 4, 2, 3, 0},
    [12140] = {12140, "Rouille", [[ L'Homme de Fer-Blanc rouille, ce qui réduit sa vitesse de déplacement de 10 unités pendant 30 sec. ]], 0, 0, 31086, 1556, 0, 0, 12138, 0, 0, 4, 2, 3, 0},
    [12141] = {12141, "Le Lion Peureux", [[ Un tigre couard, vulnérable à la peur, mais dont les griffes sont dangereuses au corps à corps. ]], 18261, 0, 0, 1556, 12145, 12142, 12128, 0, 0, 4, 2, 3, 0},
    [12142] = {12142, "Cri de terreur", [[ Un cri qui fait fuir 3 ennemis proches pendant 2 sec. ]], 0, 0, 31013, 1556, 12143, 0, 12141, 0, 0, 4, 2, 3, 0},
    [12143] = {12143, "Lacération d'armure", [[ Brise l'armure de l'ennemi, la réduisant de 5000 unités pendant 8 sec. ]], 0, 0, 31042, 1556, 12144, 0, 12141, 0, 0, 4, 2, 3, 0},
    [12144] = {12144, "Mutilation", [[ Inflige à l'ennemi $[3 7672$]$[1 24552$] points de dégâts, puis $[3 9393$]$[1 30060$] points de dégâts supplémentaires sur 15 sec. ]], 0, 0, 31041, 1556, 0, 0, 12141, 0, 0, 4, 2, 3, 0},
    [12145] = {12145, "La Sorcière", [[ La terrible sorcière a poursuivi Dorothée et ses amis, et vous menace maintenant à votre tour ! ]], 17550, 0, 0, 1556, 0, 12146, 12128, 0, 0, 4, 2, 3, 0},
    [12146] = {12146, "Tornade", [[ Projette le joueur dans les airs. ]], 0, 0, 38517, 1556, 12147, 0, 12145, 0, 0, 4, 2, 3, 0},
    [12147] = {12147, "Éclair en chaîne", [[ Un éclair qui se propage d'une cible à un autre ennemi proche. Le sort touche jusqu'à 5 cibles, chaque cible suivante subissant des dégâts de nature de plus en plus importants. ]], 0, 0, 32337, 1556, 0, 0, 12145, 0, 0, 4, 2, 3, 0},
    [12148] = {12148, "« Roméo et Juliette »", [[ Les représentations de l'Opéra de Karazhan changent.

Aujourd'hui... nous allons assister à une histoire d'amour ! Mais souvenez-vous, toutes les histoires d'amour ne finissent pas bien. Parfois, l'amour frappe comme la foudre. Mais pourquoi vous raconter ? Vous verrez par vous-mêmes quelle tragédie attend ces amants, dont les chemins se sont croisés par la volonté des étoiles ! Et maintenant... regardez ! ]], 0, 0, 0, 1556, 12162, 12150, 0, 0, 0, 4, 2, 3, 0},
    [12150] = {12150, "Amour éternel", [[ Restaure la totalité de la santé. ]], 0, 0, 30951, 1556, 12151, 0, 12148, 0, 0, 4, 2, 3, 0},
