    [12234] = {12234, "Flèche infernale renforcée", [[ Ininterrompable. L'incantateur embrase le joueur et tous ses alliés dans un rayon de 5 mètres. Cet effet inflige $[3 25000$]$[1 80000$] points de dégâts de feu, puis $[3 4375$]$[1 14000$] points de dégâts supplémentaires toutes les 1 sec. pendant 10 sec. Une flèche infernale tirée sur le joueur annule l'effet « Gelure ». ]], 0, 0, 305327, 1559, 0, 0, 12232, 0, 0, 4, 2, 12, 0},
    [12235] = {12235, "Hiver infini", [[ Utilisé lorsque la réserve de mana atteint 100%.

L'incantateur invoque une tempête de neige qui gèle tout le champ de bataille pendant 10 sec. Tous les joueurs subissent $[3 3750$]$[1 12000$] points de dégâts de givre chaque seconde pendant 10 sec, et leur vitesse de déplacement est réduite de 9%. Effet cumulable jusqu'à 10 fois. Le déplacement dissipe une application de « Hiver infini ». ]], 0, 0, 305329, 1559, 12236, 0, 12212, 0, 0, 4, 2, 12, 0},
    [12236] = {12236, "Couronne de flammes", [[ Utilisé lorsque la réserve de mana atteint 100%.

Crée un anneau de feu qui explose s'il est traversé, tuant tous les ennemis proches. Se dissipe après 10 sec. ]], 0, 0, 305330, 1559, 12237, 0, 12212, 0, 0, 4, 2, 12, 0},
    [12237] = {12237, "Invocation de familiers", [[ Utilisé lorsque la réserve de mana atteint 100%.

L'incantateur disparaît du champ de bataille et invoque 3 familiers qui bombardent des joueurs aléatoires du sort « Éclat arcanique ». ]], 0, 0, 305331, 1559, 0, 12238, 12212, 0, 0, 4, 2, 12, 0},
    [12238] = {12238, "Familier", [[ Une créature arcanique qui attaque les ennemis de l'Ombre d'Arane avec des éclats arcaniques. ]], 14273, 0, 0, 1559, 0, 12239, 12237, 0, 0, 4, 2, 12, 0},
    [12239] = {12239, "Éclat arcanique", [[ Frappe un joueur aléatoire, lui infligeant $[3 5625$]$[1 18000$] points de dégâts arcaniques. Chaque utilisation suivante de cette capacité infligera 20% de dégâts supplémentaires. ]], 0, 0, 305332, 1559, 0, 0, 12238, 0, 0, 4, 2, 12, 0},
    [12240] = {12240, "Colère du Néant", [[ Un dragon spectral, doté d'une puissance magique à couper le souffle, réside dans l'observatoire de Karazhan et est le huitième boss de ce raid. Le combat alterne entre une phase normale et une phase spectrale. ]], 15363, 0, 0, 1561, 0, 12241, 0, 1, 0, 1, 0, -1, 0},
    [12241] = {12241, "Autorité", [[ Les dégâts infligés sont augmentés de 200%. ]], 0, 0, 38549, 1561, 12242, 0, 12240, 0, 0, 4, 2, 3, 0},
    [12242] = {12242, "Porte du Néant - Sérénité", [[ Restaure les forces vitales de la Colère du Néant, la soignant de 4000 points chaque seconde. ]], 0, 0, 30467, 1561, 12243, 12248, 12240, 0, 0, 4, 2, 3, 0},
    [12243] = {12243, "Porte du Néant - Domination", [[ Emplit la Colère du Néant d'énergie, augmentant les dégâts qu'elle inflige de 1%. ]], 0, 0, 30468, 1561, 12244, 12249, 12240, 0, 0, 4, 2, 3, 0},
    [12244] = {12244, "Porte du Néant - Inébranlabilité", [[ Renforce la carapace de la Colère du Néant, réduisant les dégâts qu'elle subit de $[3 1$]$[1 4$]%. ]], 0, 0, 30466, 1561, 12245, 12250, 12240, 0, 0, 4, 2, 3, 0},
    [12245] = {12245, "Combustion du Néant", [[ L'incantateur inflige automatiquement $[3 187$]$[1 600$] points de dégâts de magie sombre toutes les 5 sec. aux ennemis proches. Dure jusqu'à annulation. ]], 0, 0, 30522, 1561, 12246, 0, 12240, 0, 0, 4, 2, 3, 0},
    [12246] = {12246, "Souffle du Néant", [[ Utilisé uniquement pendant la phase spectrale. Inflige $[3 8885$]$[1 28434$] points de dégâts arcaniques aux ennemis dans un cône devant l'incantateur. ]], 0, 0, 38523, 1561, 12247, 0, 12240, 0, 0, 4, 2, 3, 0},
    [12247] = {12247, "Portail de l'Abîme", [[ Ouvre un immense portail de l'Abîme qui persiste pendant 6 sec et inflige toutes les 2 sec $[3 828$]$[1 2652$] points de dégâts de magie sombre à tous les ennemis dans la zone choisie. ]], 0, 0, 30533, 1561, 12251, 0, 12240, 0, 0, 4, 2, 3, 0},
    [12248] = {12248, "Porte du Néant - Sérénité", [[ La cible est emplie de sérénité, et les soins qu'elle reçoit sont bien plus efficaces. Réduit le coût en mana des sorts ainsi que la réserve de mana maximale de la cible. ]], 0, 0, 30422, 1561, 0, 0, 12242, 0, 0, 4, 2, 3, 0},
    [12249] = {12249, "Porte du Néant - Domination", [[ La cible est emplie de puissance ; les dégâts qu'elle inflige augmentent, mais les soins qu'elle reçoit diminuent et elle devient vulnérable aux dégâts magiques. ]], 0, 0, 30423, 1561, 0, 0, 12243, 0, 0, 4, 2, 3, 0},
    [12250] = {12250, "Porte du Néant - Inébranlabilité", [[ Confère à la cible la force de résister aux attaques de la Colère du Néant. ]], 0, 0, 30421, 1561, 0, 0, 12244, 0, 0, 4, 2, 3, 0},
    [12251] = {12251, "Phase normale", [[ La Colère du Néant combat en conservant sa forme physique instable. ]], 0, 0, 0, 1561, 12258, 12252, 12240, 0, 0, 4, 2, 12, 0},
    [12252] = {12252, "Porte du néant", [[ La Colère du Néant ouvre un portail vers l'Abîme ! ]], 0, 0, 305400, 1561, 12257, 12253, 12251, 0, 0, 4, 2, 12, 0},
    [12253] = {12253, "Vent du néant", [[ L'énergie sombre qui pulse dans le portail vous renforce, augmentant votre vitesse de déplacement de 30%. ]], 0, 0, 305401, 1561, 12254, 0, 12252, 0, 0, 4, 2, 12, 0},
    [12254] = {12254, "Porte du Néant - Puissance", [[ Vous êtes submergé par la force ténébreuse de la porte du néant. Les dégâts infligés et l'efficacité des soins prodigués sont augmentés de 100%, les dégâts subis sont réduits de 50%. Le contact du rayon avec tout autre personnage déclenche une « Explosion du néant ». Toutes les 5 secondes, crée une zone de « Ténèbres corruptrices » à votre position. ]], 0, 0, 305402, 1561, 12255, 0, 12252, 0, 0, 4, 2, 12, 0},
    [12255] = {12255, "Explosion du néant", [[ Une explosion infligeant $[3 37500$]$[1 120000$] points de dégâts de magie sombre et repoussant les ennemis sur 25 mètres. Se déclenche au contact du rayon d'énergie de la Porte du Néant. ]], 0, 0, 305419, 1561, 12256, 0, 12252, 0, 0, 4, 2, 12, 0},
    [12256] = {12256, "Ténèbres corruptrices", [[ L'énergie de la Porte du Néant se déverse à l'extérieur, souillant la zone autour de vous d'une tache d'énergie abyssale. Inflige $[3 7500$]$[1 24000$] points de dégâts de magie sombre par seconde. Tant que vous êtes dans cette zone, vous ne pouvez ni attaquer ni lancer de sorts. ]], 0, 0, 305405, 1561, 0, 0, 12252, 0, 0, 4, 2, 12, 0},
    [12257] = {12257, "Souffle du néant", [[ La Colère du Néant prend une profonde inspiration et expire un nuage d'énergie arcanique, infligeant $[3 35000$]$[1 112000$] points de dégâts arcaniques et augmentant de 200% les dégâts arcaniques subis pendant 25 sec. ]], 0, 0, 305407, 1561, 0, 0, 12251, 0, 0, 4, 2, 12, 0},
    [12258] = {12258, "Phase spectrale", [[ La Colère du Néant absorbe l'énergie de l'Abîme, se dissolvant partiellement en elle et commençant à bombarder ses ennemis d'éclats de souffle du néant. ]], 0, 0, 0, 1561, 0, 12259, 12240, 0, 0, 4, 2, 12, 0},
    [12259] = {12259, "Vengeance de l'abîme", [[ La Colère du Néant s'enveloppe d'énergie ténébreuse qui renvoie 50% des dégâts subis à l'ennemi. ]], 0, 0, 305408, 1561, 12260, 0, 12258, 0, 0, 4, 2, 12, 0},
    [12260] = {12260, "Portes spectrales", [[ La Colère du Néant ouvre des portails supplémentaires, invoquant leur puissance à son aide. ]], 0, 0, 305410, 1561, 0, 12261, 12258, 0, 0, 4, 2, 12, 0},
    [12261] = {12261, "Instabilité", [[ Le portail émet une énergie instable, infligeant $[3 2500$]$[1 8000$] points de dégâts arcaniques chaque seconde à tous les ennemis. ]], 0, 0, 305411, 1561, 12262, 0, 12260, 0, 0, 4, 2, 12, 0},
    [12262] = {12262, "Porte du néant - Fureur", [[ Vous sombrez dans une rage incontrôlable. Les dégâts que vous infligez sont augmentés de 100%, votre armure est réduite de 100%, l'efficacité des soins que vous prodiguez est réduite de 100%. Vous subissez $[3 5000$]$[1 16000$] points de dégâts de magie sombre toutes les 2 secondes. ]], 0, 0, 305413, 1561, 12263, 0, 12260, 0, 0, 4, 2, 12, 0},
    [12263] = {12263, "Porte du néant - Silence", [[ Vous récupérez 5% de votre réserve de mana toutes les 3 secondes, mais toutes les 6 secondes, vos sorts risquent d'être interrompus. Si l'incantation d'un sort est interrompue, vous ne pouvez plus lancer de sort de la même école pendant 10 sec. Vous subissez $[3 5000$]$[1 16000$] points de dégâts de nature toutes les 2 secondes. ]], 0, 0, 305415, 1561, 12264, 0, 12260, 0, 0, 4, 2, 12, 0},
    [12264] = {12264, "Porte du néant - Désespoir", [[ La Colère du Néant concentre son attention sur vous, ignorant toute autre menace. Les dégâts que vous infligez sont réduits de 90%, et l'efficacité des soins que vous recevez de 50%. Vous ne pouvez pas vous déplacer. ]], 0, 0, 305418, 1561, 0, 0, 12260, 0, 0, 4, 2, 12, 0},
    [12265] = {12265, "Terestian Sabot-Malade", [[ Un sombre satyre, Terestian Sabot-Malade, est le sixième boss de Karazhan et se terre quelque part dans la bibliothèque. ]], 11343, 0, 0, 1560, 0, 12266, 0, 1, 0, 1, 0, -1, 0},
    [12266] = {12266, "Portail démoniaque", [[ Ouvre un portail vers le Maelström du Néant, à travers lequel des démons franchissent régulièrement le passage pour aider l'incantateur au combat. ]], 0, 0, 30171, 1560, 12270, 12267, 12265, 0, 0, 4, 2, 3, 0},
    [12267] = {12267, "Invocation d'un diablotin maléfique", [[ Invoque un diablotin maléfique. ]], 0, 0, 30184, 1560, 0, 12268, 12266, 0, 0, 4, 2, 3, 0},
    [12268] = {12268, "Diablotin maléfique", [[ Un sbire de Terestian, représentant une menace mineure pour le groupe s'il est seul. Bien entendu, une horde de ces diablotins doit être éliminée au plus vite. ]], 16944, 0, 0, 1560, 0, 12269, 12267, 0, 0, 4, 2, 3, 0},
