    [12273] = {12273, "Flèche des ténèbres", [[ Inflige $[3 4350$]$[1 13920$] points de dégâts de magie sombre aux ennemis proches. ]], 0, 0, 30055, 1560, 12274, 0, 12265, 0, 0, 4, 2, 3, 0},
    [12274] = {12274, "Main démoniaque", [[ Invoque une météorite démoniaque, infligeant $[3 21875$]$[1 70000$] points de dégâts de magie sombre à tous les ennemis dans un rayon de 8 m autour de la cible et invoquant 5 diablotins sauvages. ]], 0, 0, 305345, 1560, 12279, 12275, 12265, 0, 0, 4, 2, 12, 0},
    [12275] = {12275, "Diablotin sauvage", [[ Un sbire de Terestian, représentant une menace mineure pour le groupe s'il est seul. Bien entendu, une horde de ces diablotins doit être éliminée au plus vite. ]], 16944, 0, 0, 1560, 0, 12276, 12274, 0, 0, 4, 2, 12, 0},
    [12276] = {12276, "Boule de feu Fel", [[ Inflige $[3 2500$]$[1 8000$] points de dégâts de magie Fel, puis $[3 1250$]$[1 4000$] points de dégâts de magie Fel supplémentaires par seconde pendant 3 sec. ]], 0, 0, 305347, 1560, 12277, 0, 12275, 0, 0, 4, 2, 12, 0},
    [12277] = {12277, "Ultime explosion", [[ En mourant, le diablotin sauvage explose, infligeant $[3 5000$]$[1 16000$] points de dégâts de feu à tous les ennemis dans un rayon de 4 m. ]], 0, 0, 305348, 1560, 12278, 0, 12275, 0, 0, 4, 2, 12, 0},
    [12278] = {12278, "Ruse démoniaque", [[ Après avoir été étourdi, banni, interrompu ou avoir subi un effet similaire, le démon devient plus prudent et acquiert une immunité à tous ces effets pendant 4 sec. ]], 0, 0, 305349, 1560, 0, 0, 12275, 0, 0, 4, 2, 12, 0},
    [12279] = {12279, "Graine de corruption", [[ Implante dans l'ennemi une graine démoniaque qui inflige $[3 25012$]$[1 80040$] points de dégâts de magie sombre pendant 20 sec. Lorsque 45000 points de dégâts ont été infligés, ou à la mort de la victime, la graine explose, infligeant $[3 18750$]$[1 60000$] points de dégâts de magie sombre à tous les ennemis dans un rayon de 8 m autour de la cible et invoquant 2 diablotins maléfiques. ]], 0, 0, 305360, 1560, 12284, 12280, 12265, 0, 0, 4, 2, 12, 0},
    [12280] = {12280, "Diablotin maléfique", [[ Une version plus dangereuse du diablotin, représentant une menace sérieuse pour le groupe. ]], 16944, 0, 0, 1560, 0, 12281, 12279, 0, 0, 4, 2, 12, 0},
    [12281] = {12281, "Cible du diablotin maléfique", [[ Le diablotin maléfique vous a choisi comme victime. ]], 0, 0, 305362, 1560, 12282, 0, 12280, 0, 0, 4, 2, 12, 0},
    [12282] = {12282, "Flamme Fel", [[ Chaque attaque de mêlée a 75% de chances d'envelopper la cible de flammes, lui infligeant $[3 1062$]$[1 3400$] points de dégâts de feu toutes les 2 sec. pendant 8 sec. Effet cumulable jusqu'à 30 fois. ]], 0, 0, 305363, 1560, 12283, 0, 12280, 0, 0, 4, 2, 12, 0},
    [12283] = {12283, "Implosion", [[ Concentre toutes les forces vitales restantes et la magie Fel pour une attaque suicidaire, infligeant $[3 28125$]$[1 90000$] points de dégâts de magie Fel à tous les ennemis dans un rayon de 10 m. ]], 0, 0, 305365, 1560, 0, 0, 12280, 0, 0, 4, 2, 12, 0},
    [12284] = {12284, "Flèche démoniaque", [[ Frappe l'ennemi d'une flèche des ténèbres, infligeant $[3 25000$]$[1 80000$] points de dégâts de magie sombre et augmentant de 20% les dégâts de magie sombre qu'il subit pendant 15 sec. ]], 0, 0, 305367, 1560, 12285, 0, 12265, 0, 0, 4, 2, 12, 0},
    [12285] = {12285, "Marque du démon", [[ Marque l'ennemi d'un sceau démoniaque qui attire un démon. Le sceau inflige des dégâts de magie sombre progressivement croissants, commençant à $[3 1250$]$[1 4000$] points de dégâts. Toutes les 10 sec, le sceau tente de se propager aux alliés proches de la cible. Après un certain temps, on peut se débarrasser du sceau en plongeant dans les profondeurs de son esprit et en y vainquant le démon responsable de la possession. ]], 0, 0, 305351, 1560, 0, 12286, 12265, 0, 0, 4, 2, 12, 0},
    [12286] = {12286, "Méditation", [[ Plonger dans les profondeurs de son esprit pour tenter de se débarrasser de la possession. ]], 0, 0, 305354, 1560, 0, 12287, 12285, 0, 0, 4, 2, 12, 0},
    [12287] = {12287, "Souvenirs positifs", [[ Vous revivez les souvenirs positifs contenus dans la sphère, restaurant $[3 15625$]$[1 50000$] points de santé. Chaque souvenir revécu augmente les dégâts que vous infligez de 3%, et les soins que vous prodiguez de 2%. ]], 0, 0, 305358, 1560, 12288, 0, 12286, 0, 0, 4, 2, 12, 0},
    [12288] = {12288, "Diablotin maléfique", [[ Une version plus dangereuse du diablotin, nichée dans votre esprit à cause de la « Marque du démon ». Détruisez-le au plus vite ! ]], 16944, 0, 0, 1560, 0, 12289, 12286, 0, 0, 4, 2, 12, 0},
