    [12295] = {12295, "Terre calcinée", [[ Embrase le sol, infligeant 30000 points de dégâts à tout ce qui se trouve sur le terrain calciné pendant 30 sec. ]], 0, 0, 30129, 1562, 12296, 0, 12293, 0, 0, 4, 2, 3, 0},
