    [12299] = {12299, "Coup de queue", [[ Inflige $[3 562$]$[1 1800$] points de dégâts aux ennemis derrière l'incantateur et les repousse en arrière. ]], 0, 0, 25653, 1562, 12300, 0, 12293, 0, 0, 4, 2, 3, 0},
