    [12301] = {12301, "Phase aérienne", [[ Le Fléau s'élève dans les airs et poursuit le combat depuis là-haut.$[!3 En mode héroïque, au début de la phase, le Fléau de la Nuit dissipe toutes les zones de « Braises infernales ». La phase dure jusqu'à ce que tous les serviteurs du Fléau de la Nuit soient tués.$] ]], 0, 0, 0, 1562, 0, 12302, 12292, 0, 0, 4, 2, -1, 0},
    [12302] = {12302, "Pluie d'ossements", [[ Frappe la cible et les ennemis proches d'elle avec des éclats d'os, infligeant $[3 452$]$[1 1448$] points de dégâts physiques et invoquant 3 squelettes. ]], 0, 0, 37098, 1562, 12304, 12303, 12301, 0, 0, 4, 2, 3, 0},
