    [12305] = {12305, "Salve de boules de feu", [[ Des boules de feu sont lancées sur les ennemis dans un rayon de 40 mètres. ]], 0, 0, 30282, 1562, 12306, 0, 12301, 0, 0, 4, 2, 3, 0},
    [12306] = {12306, "Cendres brûlantes", [[ $[3 3757$]$[1 12024$] points de dégâts de feu sur 18 sec. ]], 0, 0, 30127, 1562, 12314, 0, 12301, 0, 0, 4, 2, 3, 0},
    [12307] = {12307, "Bûcher funéraire", [[ Le Fléau de la Nuit s'embrase avec une puissance renouvelée, infligeant $[3 15000$]$[1 48000$] points de dégâts de feu à tous les ennemis et laisse derrière lui une zone de « Braises infernales ». ]], 0, 0, 305375, 1562, 12309, 12308, 12293, 0, 0, 4, 2, 12, 0},
    [12308] = {12308, "Braises infernales", [[ Les flammes terrifiantes du Fléau de la Nuit font rage tout autour, infligeant $[3 10000$]$[1 32000$] points de dégâts de feu par seconde aux ennemis proches. ]], 0, 0, 305376, 1562, 0, 0, 12307, 0, 0, 4, 2, 12, 0},
    [12309] = {12309, "Combustion", [[ Le Fléau de la Nuit prend une profonde inspiration et expire devant lui un nuage de flammes et de ténèbres, infligeant $[3 50000$]$[1 160000$] points de dégâts de magie sombre, puis $[3 5000$]$[1 16000$] points de dégâts de feu supplémentaires toutes les 2 secondes pendant 8 sec. Les ennemis touchés reçoivent l'effet « Nécrose », qui augmente de 200% les dégâts de magie sombre qu'ils subissent pendant 45 sec. ]], 0, 0, 305377, 1562, 12311, 12310, 12293, 0, 0, 4, 2, 12, 0},
    [12310] = {12310, "Nécrose", [[ Le Fléau de la Nuit prend une profonde inspiration et expire devant lui un nuage de flammes et de ténèbres, infligeant $[3 50000$]$[1 160000$] points de dégâts de magie sombre, puis $[3 5000$]$[1 16000$] points de dégâts de feu supplémentaires toutes les 2 secondes pendant 8 sec. Les ennemis touchés reçoivent l'effet « Nécrose », qui augmente de 200% les dégâts de magie sombre qu'ils subissent pendant 45 sec. ]], 0, 0, 305379, 1562, 0, 0, 12309, 0, 0, 4, 2, 12, 0},
    [12311] = {12311, "Appel des flammes", [[ Le Fléau de la Nuit enveloppe les ennemis d'un voile de flammes, leur infligeant $[3 7500$]$[1 24000$] points de dégâts de feu. Si l'ennemi survit, il reçoit l'effet « Pyromancien ». ]], 0, 0, 305380, 1562, 0, 12312, 12293, 0, 0, 4, 2, 12, 0},
    [12312] = {12312, "Pyromancien", [[ Vous avez survécu à l'embrasement et avez acquis de nouvelles capacités. Les dégâts que vous infligez et l'efficacité des soins que vous prodiguez sont augmentés de 50%, et les dégâts de feu que vous subissez sont réduits de 100%. Si vous restez plus de deux secondes hors d'une zone de « Braises infernales », vous recevez l'effet « Hypothermie ». ]], 0, 0, 305382, 1562, 12313, 0, 12311, 0, 0, 4, 2, 12, 0},
    [12313] = {12313, "Hypothermie", [[ Vous vous trouvez hors d'une zone embrasée et souffrez d'un froid glacial. Les dégâts que vous infligez et l'efficacité des soins que vous prodiguez sont réduits de 100%, et vous subissez $[3 7500$]$[1 24000$] points de dégâts de givre toutes les deux secondes. ]], 0, 0, 305384, 1562, 0, 0, 12311, 0, 0, 4, 2, 12, 0},
    [12314] = {12314, "Appel ardent", [[ Le Fléau de la Nuit invoque les flammes dans l'âme des ennemis affectés par « Pyromancien » ou « Hypothermie », les remplaçant par « Possession ardente ». ]], 0, 0, 305386, 1562, 12319, 12315, 12301, 0, 0, 4, 2, 12, 0},
    [12315] = {12315, "Possession ardente", [[ Votre folie vous a asservi ! Les dégâts que vous infligez sont augmentés de 30%, et ceux que vous subissez sont réduits de 60%. Tant que votre santé n'a pas chuté à 20%, vous êtes sous le contrôle du Fléau de la Nuit. La suppression de cet effet déclenche une « Explosion d'ombre ». ]], 0, 0, 305388, 1562, 0, 12316, 12314, 0, 0, 4, 2, 12, 0},
    [12316] = {12316, "Explosion d'ombre", [[ La dissipation de la capacité d'asservissement du Fléau de la Nuit déclenche une explosion de magie sombre, créant une zone de ténèbres. Les ennemis présents dans cette zone subissent $[3 5000$]$[1 16000$] points de dégâts de magie sombre toutes les 2 secondes. Toutes les 3 secondes, cette zone fait apparaître un squelette. ]], 0, 0, 305390, 1562, 0, 12317, 12315, 0, 0, 4, 2, 12, 0},
