    [20852] = {20852, "Phase 3 : le vrai visage de la mort", [[ Lorsque le cerveau de Yogg-Saron atteint 30% de santé, la |cff71d5ff|Hspell:63894|h[Barrière d'ombre]|h|r tombe et il peut être attaqué directement. ]], 0, 0, 0, 11635, 20860, 20853, 0, 0, 0, 2, 2, -1, 0},
