    [20855] = {20855, "Regard du fou", [[ Un regard dans l'abîme de la folie ébranle votre esprit, infligeant $[2 9418$]$[4 18837$]$[3 15697$]$[1 9418$] unités de dégâts de magie noire et réduisant votre raison de 4% chaque seconde tant que vous regardez le lanceur de sorts. ]], 0, 0, 64163, 11635, 20856, 0, 20854, 0, 0, 2, 2, -1, 0},
