    [20857] = {20857, "Condensation des ténèbres", [[ Renforce les alliés dans un rayon de 20 m autour de la cible, restaurant $[2 337530$]$[4 675060$]$[3 562550$]$[1 337530$] unités de leur santé sur 20 sec. ]], 0, 0, 64468, 11635, 0, 0, 20856, 0, 0, 2, 2, -1, 0},
