    [20912] = {20912, "Malédiction de sang", [[ Augmente les dégâts physiques subis par l'ennemi de 1 unité pendant 600 min. ]], 0, 0, 12279, 11645, 0, 0, 0, 1, 256, 2, 2, -1, 0},
    [20913] = {20913, "Aura de représailles", [[ Inflige 20 unités de dégâts de nature à toute créature attaquant un membre proche du groupe du lanceur de sorts. Un seul aura de chaque paladin peut agir sur un joueur à la fois. L'aura dure 60 sec. ]], 0, 0, 8148, 11646, 20914, 0, 0, 1, 0, 2, 2, -1, 0},
