    [20915] = {20915, "Idole de guérison", [[ Invoque un totem qui guérit les alliés dans la zone environnante pendant 30 sec. ]], 0, 0, 11899, 11646, 20916, 0, 0, 1, 0, 2, 2, -1, 0},
    [20916] = {20916, "Vague de guérison", [[ Invoque les forces de la nature pour guérir un allié. ]], 0, 0, 12492, 11646, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [20917] = {20917, "Frappe tranchante", [[ Inflige 110% des dégâts de mêlée habituels à l'ennemi et à son allié le plus proche. ]], 0, 0, 40505, 11647, 20918, 0, 0, 1, 0, 2, 2, -1, 0},
