    [20919] = {20919, "Éclair en chaîne", [[ Un éclair qui saute d'une cible à un autre ennemi proche. Le sort touche jusqu'à 3 cibles, chaque cible suivante subissant des dégâts de nature de plus en plus élevés. ]], 0, 0, 12058, 11648, 20920, 0, 0, 1, 0, 2, 2, -1, 0},
