    [20927] = {20927, "En développement", [[  ]], 0, 0, 0, 11655, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [20930] = {20930, "Phase 1 : forme pure", [[ Tant qu'Hydross se trouve dans la partie centrale de la plateforme, où son corps subit un effet purificateur, il conservera cette forme. S'il quitte cette zone, la corruption qui l'empoisonne prendra le dessus, et il commencera à utiliser la capacité "Vapeurs toxiques". ]], 0, 0, 0, 11650, 20941, 20931, 0, 1, 0, 2, 2, -1, 0},
    [20931] = {20931, "Forme pure", [[ Les attaques de mêlée infligent des dégâts de magie de givre au lieu de dégâts physiques. ]], 0, 0, 309041, 11650, 20932, 0, 0, 1, 32, 2, 2, -1, 0},
    [20932] = {20932, "Marque d'Hydross", [[ Une marque magique frappant tous les ennemis, augmentant de 25% les dégâts de magie de givre qu'ils subissent. Chaque application suivante de cette capacité est renforcée, augmentant les dégâts subis de 25%, 50%, 100% et 250% respectivement. ]], 0, 0, 309042, 11650, 20933, 0, 0, 1, 16, 2, 2, -1, 0},
    [20933] = {20933, "Marque des Eaux", [[ La force des Eaux commence à se concentrer autour de trois ennemis (dont la cible actuelle d'Hydross), enfermant après 10 sec. les cibles marquées ainsi que tous leurs alliés dans un rayon de 6 m dans des tombeaux d'eau. Les ennemis touchés perdent 5% du niveau de menace généré chaque seconde. ]], 0, 0, 309046, 11650, 20936, 20934, 0, 1, 33, 2, 2, -1, 0},
    [20934] = {20934, "Tombeau d'eau", [[ Un tombeau d'eau enveloppe l'ennemi, l'empêchant d'agir, lui infligeant $[4 3600$]$[2 15520$]$[1 4000$] unités de dégâts de magie de givre toutes les 2 sec., et réduisant de 50% l'efficacité des soins reçus. Dissiper cet effet provoquera l'apparition d'une zone d'"Eaux pures". ]], 0, 0, 309048, 11650, 20935, 0, 0, 1, 128, 2, 2, -1, 0},
    [20935] = {20935, "Eaux pures", [[ La destruction du tombeau d'eau a fait apparaître une zone d'eaux pures, infligeant $[4 5400$]$[2 23280$]$[1 6000$] unités de dégâts de magie de givre à tous les ennemis dans un rayon de 6 m toutes les 2 sec. Se trouver dans cette zone confère une immunité totale aux effets d'étourdissement et réduit de 75% les dégâts des "Vapeurs toxiques".
 ]], 0, 0, 309050, 11650, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [20936] = {20936, "Poussée des vagues", [[ Un coup renforcé par la puissance de l'élément aquatique, infligeant $[4 27000$]$[2 116400$]$[1 30000$] dégâts de magie de givre et augmentant de 100% les dégâts subis par l'ennemi du "Tombeau d'eau". Empêche la dissipation du "Tombeau d'eau". Se cumule jusqu'à 20 fois. ]], 0, 0, 309051, 11650, 20937, 0, 0, 1, 1, 2, 2, -1, 0},
    [20937] = {20937, "Salve de flèches d'eau", [[ Cinq flèches d'eau s'élèvent dans les airs et, après quelques secondes, retombent sur la position d'ennemis aléatoires dans un rayon supérieur à 15 m, infligeant $[4 28800$]$[2 124160$]$[1 32000$] dégâts de magie de givre à tous les ennemis dans un rayon de 3 m du point d'impact. Si aucune cible appropriée n'est trouvée dans le rayon indiqué, les flèches d'eau viseront des ennemis aléatoires indépendamment de leur position. Ce sort ignore les ennemis affectés par les "Tombeaux d'eau". ]], 0, 0, 309052, 11650, 20938, 0, 0, 1, 0, 2, 2, -1, 0},
    [20938] = {20938, "Tsunami", [[ Hydross use de son pouvoir sur l'élément pour créer de multiples tourbillons d'eau afin d'emporter les ennemis. Tout ennemi pris dans la zone d'effet d'un tel tourbillon subira $[4 108000$]$[2 465600$]$[1 120000$] dégâts de magie de givre et sera repoussé de 20 m en arrière. Au contact d'une zone de "Vase toxique", la vitesse du tourbillon d'eau sera réduite de 85%, après quoi la vase toxique sera emportée. ]], 0, 0, 309055, 11650, 0, 20939, 0, 1, 16, 2, 2, -1, 0},
    [20939] = {20939, "Bouclier des vagues", [[ Hydross est immunisé à tous types d'effets tant qu'il n'a pas terminé d'utiliser la capacité "Tsunami". ]], 0, 0, 309056, 11650, 20940, 0, 0, 1, 0, 2, 2, -1, 0},
    [20940] = {20940, "Tourbillon du Tsunami", [[ Un tourbillon irrésistible emporte l'ennemi, le repoussant de 20 m en arrière et lui infligeant $[4 108000$]$[2 465600$]$[1 120000$] dégâts de magie de givre. ]], 0, 0, 309057, 11650, 0, 0, 0, 1, 16, 2, 2, -1, 0},
    [20941] = {20941, "Phase 2 : forme corrompue", [[ En quittant la partie centrale de la plateforme, la corruption s'empare d'Hydross, l'empoisonnant et transformant sa forme en forme corrompue. Dès qu'Hydross revient au centre de la plateforme, il est de nouveau purifié, et commence alors à utiliser la capacité "Tsunami". ]], 0, 0, 0, 11650, 0, 20942, 0, 1, 0, 2, 2, -1, 0},
    [20942] = {20942, "Forme corrompue", [[ Les attaques de mêlée infligent des dégâts de nature au lieu de dégâts physiques. ]], 0, 0, 309060, 11650, 20943, 0, 0, 1, 32, 2, 2, -1, 0},
    [20943] = {20943, "Marque de Corruption", [[ Une marque magique frappant tous les ennemis, augmentant de 25% les dégâts de nature qu'ils subissent. Chaque application suivante de cette capacité est renforcée, augmentant les dégâts subis de 25%, 50%, 100% et 250% respectivement. ]], 0, 0, 309061, 11650, 20944, 0, 0, 1, 16, 2, 2, -1, 0},
    [20944] = {20944, "Corrosion", [[ La corruption se concentre autour de trois ennemis (dont la cible actuelle d'Hydross), commençant à ronger leur chair. Les ennemis touchés subissent $[4 3600$]$[2 15520$]$[1 4000$] dégâts de nature toutes les 2 sec., et perdent 5% du niveau de menace généré chaque seconde. Dissiper cet effet provoquera une "Vague de poison". Dissiper la "Corrosion" d'un personnage se trouvant dans une zone d'"Eaux pures" ne provoquera pas de "Vague de poison", mais transformera la zone d'"Eaux pures" en zone de "Vase toxique". ]], 0, 0, 309065, 11650, 20947, 20945, 0, 1, 544, 2, 2, -1, 0},
    [20945] = {20945, "Vague de poison", [[ Dissiper la "Corrosion" provoque une vague de poison infligeant $[4 14400$]$[2 62080$]$[1 16000$] dégâts de nature à tous les ennemis dans un rayon de 30 m et les affectant de "Corrosion". ]], 0, 0, 309066, 11650, 20946, 0, 0, 1, 16, 2, 2, -1, 0},
    [20946] = {20946, "Vase toxique", [[ Les eaux pures ont absorbé la substance corrosive de la "Corrosion", se transformant en zone de "Vase toxique" infligeant $[4 5400$]$[2 23280$]$[1 6000$] dégâts de nature toutes les 2 sec. La "Vase toxique" peut ralentir la "Vague de Tsunami" de 85%, mais sera ensuite emportée de la plateforme. ]], 0, 0, 309067, 11650, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [20947] = {20947, "Frappe corrosive", [[ Une giclée de substance corrosive infligeant $[4 27000$]$[2 116400$]$[1 30000$] dégâts de nature et augmentant de 100% les dégâts subis par l'ennemi de la "Corrosion". Empêche la dissipation de la "Corrosion". Se cumule jusqu'à 20 fois. ]], 0, 0, 309068, 11650, 20948, 0, 0, 1, 1, 2, 2, -1, 0},
    [20948] = {20948, "Salve de poison", [[ Cinq charges de poison s'élèvent dans les airs et, après quelques secondes, retombent sur la position d'ennemis aléatoires dans un rayon supérieur à 15 m, infligeant $[4 28800$]$[2 124160$]$[1 32000$] dégâts de nature à tous les ennemis dans un rayon de 3 m du point d'impact. Si aucune cible appropriée n'est trouvée dans le rayon indiqué, les charges de poison viseront des ennemis aléatoires indépendamment de leur position. Ce sort ignore les ennemis affectés par la "Corrosion". ]], 0, 0, 309069, 11650, 20949, 0, 0, 1, 0, 2, 2, -1, 0},
    [20949] = {20949, "Vapeurs toxiques", [[ Hydross vaporise son poison, en remplissant le champ de bataille en 5 sec. Les ennemis ne se trouvant pas dans une zone d'"Eaux pures" sont étourdis, errant sans but pendant 10 sec. Les vapeurs toxiques infligent aussi 18000 dégâts de nature chaque seconde à tous les ennemis. ]], 0, 0, 309072, 11650, 0, 20950, 0, 1, 16, 2, 2, -1, 0},
    [20950] = {20950, "Intoxication", [[ En vous trouvant hors de la zone d'"Eaux pures" lors de l'apparition des vapeurs toxiques, vous serez empoisonné par elles et étourdi. ]], 0, 0, 309074, 11650, 20951, 0, 0, 1, 544, 2, 2, -1, 0},
    [20951] = {20951, "Barrière de Corruption", [[ Hydross est immunisé à tous types d'effets tant qu'il n'a pas terminé d'utiliser la capacité "Vapeurs toxiques". ]], 0, 0, 309073, 11650, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [20952] = {20952, "Phase 1 : Démon et Chasseur", [[ Leotheras commence le combat en prenant soit la Forme du Démon, soit en restant sous la Forme du Chasseur. Chacune de ses formes possède sa propre jauge de santé et ses propres capacités.
Après avoir perdu 10% de sa santé maximale, Leotheras change de forme. ]], 0, 0, 0, 11652, 20979, 20953, 0, 0, 0, 2, 2, -1, 0},
    [20953] = {20953, "Forme du Chasseur", [[  ]], 20514, 0, 0, 11652, 20968, 20954, 0, 1, 0, 2, 2, -1, 21215},
    [20954] = {20954, "Folie furieuse", [[ Leotheras accumule de la rage pendant le combat, quelle que soit sa forme. En atteignant 100 unités de rage, il utilise l'une de ses capacités spéciales. ]], 0, 0, 310475, 11652, 20962, 20955, 0, 1, 32, 2, 2, -1, 0},
    [20955] = {20955, "Sceaux démoniaques", [[ Six sceaux démoniaques apparaissent au sol et se chargent pendant les 5 sec. suivantes. Une fois chargé, chaque sceau s'active, libérant sa puissance sur les ennemis dans son rayon d'action. Si la libération d'un sceau ne touche aucun ennemi, une déferlante d'énergie chaotique de corruption inflige à tous les ennemis $[4 17100$]$[2 73720$]$[1 19000$] dégâts de corruption et augmente de 30% les dégâts de corruption qu'ils subissent pendant 60 sec. ]], 0, 0, 310487, 11652, 20960, 20956, 0, 1, 32, 2, 2, -1, 0},
    [20956] = {20956, "Libération du sceau", [[ Le sceau libère de l'énergie chaotique de corruption, infligeant $[4 17100$]$[2 73720$]$[1 19000$] dégâts de corruption à tous les ennemis et augmentant de 30% les dégâts de corruption qu'ils subissent pendant 60 sec. Se cumule jusqu'à 6 fois. ]], 0, 0, 310494, 11652, 20957, 0, 0, 1, 16, 2, 2, -1, 0},
    [20957] = {20957, "Sceau de Silence", [[ Le sceau se libère, affectant tous les ennemis dans un rayon de 6 m
d'une malédiction de silence, les empêchant totalement de lancer des sorts pendant 30 sec. Si le sceau n'a touché aucun ennemi, il déclenchera l'effet de "Libération du sceau". ]], 0, 0, 310488, 11652, 20958, 0, 0, 1, 0, 2, 2, -1, 0},
    [20958] = {20958, "Sceau des Chaînes", [[ Le sceau se libère, enchaînant tous les ennemis dans un rayon de 6 m avec des chaînes magiques, entravant totalement leurs mouvements pendant 30 sec. Si le sceau n'a touché aucun ennemi, il déclenchera l'effet de "Libération du sceau". ]], 0, 0, 310489, 11652, 20959, 0, 0, 1, 0, 2, 2, -1, 0},
    [20959] = {20959, "Sceau de Torture", [[ Le sceau se libère, affectant tous les ennemis dans un rayon de 6 m d'une malédiction de tourments atroces, leur infligeant 4000 dégâts de feu toutes les 0,5 sec. pendant 30 sec. Si le sceau n'a touché au moins trois ennemis, il déclenchera l'effet de "Libération du sceau". ]], 0, 0, 310490, 11652, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [20960] = {20960, "Vague de Corruption", [[ Une vague d'énergie de corruption concentrée émane du lanceur de sorts, frappant tous les ennemis et leur infligeant des dégâts égaux à 85% de leur santé maximale sous forme de dégâts de magie de corruption. Cette capacité ignore les effets de résistance. ]], 0, 0, 310495, 11652, 20961, 0, 0, 1, 36, 2, 2, -1, 0},
    [20961] = {20961, "Marque de Corruption", [[ Marque l'ennemi d'une monstrueuse marque de Corruption qui pulse de flammes de corruption, infligeant $[4 54000$]$[2 232800$]$[1 60000$] dégâts de magie de corruption toutes les 3 sec., répartis entre la victime de la marque et ses alliés proches dans un rayon de 10 m. Si les dégâts de la marque sont partagés par plus de six ennemis, la marque se propagera à eux. Il en va de même si la victime de la marque meurt. ]], 0, 0, 310496, 11652, 0, 0, 0, 1, 48, 2, 2, -1, 0},
    [20962] = {20962, "Armure infernale", [[ Les flammes infernales infligent $[4 3600$]$[2 15520$]$[1 4000$] dégâts de corruption à tous les ennemis dans un rayon de 10 m chaque seconde. ]], 0, 0, 310476, 11652, 20963, 0, 0, 1, 0, 2, 2, -1, 0},
    [20963] = {20963, "Assaut de Corruption", [[ Une série de 12 coups incroyablement rapides assénés en 3 sec. Chaque coup inflige $[4 27000$]$[2 116400$]$[1 30000$] dégâts physiques à tous les ennemis dans un rayon de 10 m dans un secteur de 180 degrés devant le lanceur de sorts. La série se termine par un coup final réduisant la santé maximale des ennemis de $[4 27$]$[2 116$]$[1 30$]% pendant 40 sec. ]], 0, 0, 310478, 11652, 20966, 20964, 0, 1, 1, 2, 2, -1, 0},
    [20964] = {20964, "Coup de Corruption", [[ Un coup incroyablement rapide infligeant $[4 27000$]$[2 116400$]$[1 30000$] dégâts physiques à tous les ennemis dans un rayon de 10 m dans un secteur de 180 degrés devant le lanceur de sorts. ]], 0, 0, 310479, 11652, 20965, 0, 0, 1, 0, 2, 2, -1, 0},
    [20965] = {20965, "Âme fendue", [[ Le coup final de l'"Assaut de Corruption" ne blesse pas le corps mais l'âme des ennemis, réduisant leur santé maximale de $[4 27$]$[2 116$]$[1 30$]%. Se cumule jusqu'à 3 fois. ]], 0, 0, 310480, 11652, 0, 0, 0, 1, 17, 2, 2, -1, 0},
    [20966] = {20966, "Ruée de Corruption", [[ Leotheras concentre son attention sur un ennemi pendant 3 sec., puis effectue une ruée fulgurante. Pendant la ruée, Leotheras frappe chaque ennemi dans un rayon de 6 m autour de lui, infligeant $[4 9000$]$[2 38800$]$[1 10000$] dégâts de corruption pour chaque ennemi touché par cette capacité. ]], 0, 0, 310481, 11652, 20967, 0, 0, 1, 2, 2, 2, -1, 0},
    [20967] = {20967, "Métamorphose", [[ Après avoir perdu 10% de sa santé maximale, Leotheras s'affaiblit, et son démon intérieur se libère, transformant Leotheras en forme démoniaque. ]], 0, 0, 310484, 11652, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [20968] = {20968, "Forme du Démon", [[  ]], 91709, 0, 0, 11652, 0, 20969, 0, 1, 0, 2, 2, -1, 200045},
    [20969] = {20969, "Folie furieuse", [[ Leotheras accumule de la rage pendant le combat, quelle que soit sa forme. En atteignant 100 unités de rage, il utilise l'une de ses capacités spéciales. ]], 0, 0, 310475, 11652, 20973, 20970, 0, 1, 32, 2, 2, -1, 0},
    [20970] = {20970, "Annihilation", [[ Le lanceur de sorts dirige un rayon d'énergie de corruption, effectuant un tour complet sur lui-même en 10 sec. L'ennemi en contact avec le rayon subit 20000 dégâts de corruption toutes les 0,25 sec. ]], 0, 0, 310508, 11652, 20971, 0, 0, 1, 16, 2, 2, -1, 0},
    [20971] = {20971, "Bombardement de Corruption", [[ Le lanceur de sorts invoque une déferlante de flèches de corruption, les dirigeant sur les positions des ennemis après 3 sec. Chaque flèche inflige $[4 27000$]$[2 116400$]$[1 30000$] dégâts de corruption à tous les ennemis dans un rayon de 3 m du point d'impact. ]], 0, 0, 310510, 11652, 20972, 0, 0, 1, 16, 2, 2, -1, 0},
    [20972] = {20972, "Incinération", [[ Le lanceur de sorts enflamme quatre ennemis aléatoires. Les ennemis touchés se consument pendant 12 sec., absorbant 200000 unités de soin chacun. Si cet effet n'est pas dissipé par un soin avant la fin du minuteur, l'ennemi touché meurt. ]], 0, 0, 310514, 11652, 0, 0, 0, 1, 20, 2, 2, -1, 0},
    [20973] = {20973, "Résonance de Corruption", [[ La force de corruption émise par Leotheras possédé affecte les ennemis lanceurs de sorts dans un rayon de 50 m, leur infligeant $[4 3600$]$[2 15520$]$[1 4000$] dégâts de corruption chaque seconde. ]], 0, 0, 310501, 11652, 20974, 0, 0, 1, 0, 2, 2, -1, 0},
    [20974] = {20974, "Griffes de Corruption", [[ Un coup de griffes empli de puissance démoniaque, infligeant $[4 18000$]$[2 77600$]$[1 20000$] dégâts de corruption, augmentant de 100% les dégâts subis par l'ennemi de cette capacité pendant 40 sec. ]], 0, 0, 310502, 11652, 20975, 0, 0, 1, 1, 2, 2, -1, 0},
    [20975] = {20975, "Chute de Corruption", [[ Un cercle magique au sol accumule de la corruption pendant 3 sec., puis provoque une explosion infligeant $[4 180000$]$[2 776000$]$[1 200000$] dégâts de corruption, répartis entre tous les ennemis dans un rayon de 10 m. Si les dégâts de l'explosion sont partagés par moins de 10 ennemis, le cercle magique déclenchera l'"Implosion de Corruption". ]], 0, 0, 310503, 11652, 20978, 20976, 0, 1, 32, 2, 2, -1, 0},
    [20976] = {20976, "Explosion de Corruption", [[ L'explosion inflige $[4 180000$]$[2 776000$]$[1 200000$] dégâts de corruption, répartis entre tous les ennemis dans un rayon de 10 m. Si les dégâts du cercle sont partagés par moins de 10 ennemis, l'effet "Implosion de Corruption" sera déclenché. ]], 0, 0, 310504, 11652, 20977, 0, 0, 1, 0, 2, 2, -1, 0},
    [20977] = {20977, "Implosion de Corruption", [[ L'explosion du cercle magique a été partagée par moins de 10 ennemis, entraînant un excès d'énergie chaotique qui inflige $[4 45000$]$[2 194000$]$[1 50000$] dégâts de corruption à chaque ennemi. ]], 0, 0, 310505, 11652, 0, 0, 0, 1, 16, 2, 2, -1, 0},
    [20978] = {20978, "Restauration du contrôle", [[ Après avoir perdu 10% de sa santé maximale, Leotheras réprime son démon intérieur, retrouvant sa forme normale. ]], 0, 0, 310506, 11652, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [20979] = {20979, "Phase 2 : Démon-Chasseur", [[ Lorsque la santé de Leotheras atteint 35% de son maximum, les deux parties de son être, oubliant leurs doutes et leur querelle, fusionnent en une seule entité, activant la "Métamorphose parfaite". ]], 0, 0, 0, 11652, 0, 20980, 0, 0, 0, 2, 2, -1, 0},
    [20980] = {20980, "Métamorphose parfaite", [[ Se trouvant au bord de la mort, Leotheras et son démon intérieur fusionnent en une seule et même entité, accédant à des capacités puissantes auparavant inaccessibles. Sa santé augmente alors de 100%. ]], 0, 0, 310518, 11652, 20981, 0, 0, 1, 0, 2, 2, -1, 0},
