    [20997] = {20997, "Regard perçant", [[ Le lanceur de sorts dirige un rayon d'énergie de corruption avec son regard, effectuant un demi-tour en 5 sec. L'ennemi en contact avec le rayon subit 10000 dégâts de corruption toutes les 0,25 sec. ]], 0, 0, 310516, 11652, 0, 0, 0, 1, 16, 2, 2, -1, 0},
    [20998] = {20998, "Des Profondeurs", [[ En se trouvant dans l'eau ou sous l'eau, les ennemis attirent le regard de créatures inconnues habitant les profondeurs du bassin du Sanctuaire du Serpent. Si un ennemi reste sous ce regard pendant plus de 5 secondes, l'un des habitants des profondeurs décidera sans doute de s'en nourrir. ]], 0, 0, 310540, 11651, 21000, 20999, 0, 1, 0, 2, 2, -1, 0},
    [20999] = {20999, "Dévoration", [[ L'habitant des profondeurs dévore l'ennemi ayant troublé son repos, le tuant instantanément. ]], 0, 0, 310541, 11651, 0, 0, 0, 1, 16, 2, 2, -1, 0},
    [21000] = {21000, "Malheur-Lacs", [[  ]], 48173, 0, 0, 11651, 0, 21001, 0, 0, 0, 2, 2, -1, 121217},
    [21001] = {21001, "Carapace épineuse", [[ Le corps de Malheur-Lacs est recouvert d'une solide carapace épineuse qui inflige 1000 dégâts physiques en réponse aux attaques de mêlée subies, et 4000 dégâts physiques en réponse aux dégâts subis de capacités de mêlée. Subir des dégâts de sorts ou d'attaques à distance provoque en retour une giclée de sang empoisonné infligeant 5000 dégâts de nature. ]], 0, 0, 310542, 11651, 21007, 21004, 0, 1, 34, 2, 2, -1, 0},
    [21003] = {21003, "Perdition", [[ Entoure le lanceur de sorts d'une aura de Perdition, qui inflige 5500 unités de dégâts de magie noire aux ennemis proches à chaque fois qu'il subit des dégâts d'un sort direct. Durée – 5 sec. ]], 0, 0, 59302, 644, 7720, 0, 0, 0, 128, 9, 2, 2, 0},
    [21004] = {21004, "Épine perforante", [[ Vous n'avez pas réussi à éviter les épines de la carapace de l'ennemi. Subissez 1000 dégâts physiques instantanément, ainsi que 500 dégâts physiques toutes les 0,5 sec. pendant 5 sec. Se cumule jusqu'à 100 fois. ]], 0, 0, 310545, 11651, 21005, 0, 0, 1, 0, 2, 2, -1, 0},
    [21005] = {21005, "Épine lacérante", [[ Vous n'avez pas réussi à éviter les épines déchirantes de la carapace de l'ennemi. Subissez 4000 dégâts physiques instantanément, ainsi que 2000 dégâts physiques toutes les 2 sec. pendant 6 sec. Se cumule jusqu'à 100 fois. ]], 0, 0, 310546, 11651, 21006, 0, 0, 1, 0, 2, 2, -1, 0},
    [21006] = {21006, "Sang empoisonné", [[ Les attaques à distance et les sorts provoquent en retour une giclée de sang empoisonné infligeant 5000 dégâts de nature instantanément, et 4000 dégâts de nature toutes les 3 sec. pendant 12 sec. Se cumule jusqu'à 100 fois. ]], 0, 0, 310547, 11651, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21007] = {21007, "Coup de pince puissant", [[ Un coup empli de puissance physique, infligeant $[4 144000$]$[2 620800$]$[1 160000$] unités de dégâts physiques à l'ennemi et à tous ses alliés dans un rayon de 6 m, augmentant aussi de 100% les dégâts de nature subis par tous les ennemis touchés pendant 30 sec. Se cumule jusqu'à 10 fois. ]], 0, 0, 310548, 11651, 21008, 0, 0, 1, 1, 2, 2, -1, 0},
    [21008] = {21008, "Vomissure toxique", [[ Une masse de poison et de nourriture à moitié digérée s'abat sur l'ennemi, lui infligeant ainsi qu'à tous ses alliés dans un rayon de 6 m $[4 72000$]$[2 310400$]$[1 80000$] unités de dégâts de nature. La vomissure toxique ronge aussi l'armure de tous les ennemis touchés, augmentant de 100% les dégâts qu'ils subissent du "Coup de pince puissant" pendant 30 sec., et réduisant leur vitesse de déplacement de 50%. ]], 0, 0, 310549, 11651, 21009, 0, 0, 1, 1, 2, 2, -1, 0},
    [21009] = {21009, "Flaque de vase", [[ Une flaque de vase toxique s'étend sous le lanceur de sorts, atteignant un rayon de 20 m en 5 sec. Les ennemis en contact avec la vase subissent 8000 dégâts de nature toutes les 2 sec., et la vitesse d'attaque et de déplacement du lanceur de sorts, tant qu'il est en contact avec la vase, augmente de 200%. ]], 0, 0, 310550, 11651, 21010, 0, 0, 1, 16, 2, 2, -1, 0},
    [21010] = {21010, "Paralysie lente", [[ Des vapeurs magiques enveloppent tous les ennemis, les paralysant après 10 sec. Ce sort est un effet magique et peut être dissipé. ]], 0, 0, 310555, 11651, 21011, 0, 0, 1, 144, 2, 2, -1, 0},
    [21011] = {21011, "Invocation des gardiens", [[ Invoque à son aide 1 Fléau des Courants et 1 Broyeur des Courants. ]], 0, 0, 0, 11651, 0, 21012, 0, 1, 32, 2, 2, -1, 0},
    [21012] = {21012, "Fléau des Courants", [[ L'une des gardiennes de Malheur-Lacs, maîtresse archère. Ne se déplace pas, tirant sur les ennemis à distance. ]], 19365, 0, 0, 11651, 21016, 21013, 0, 1, 0, 2, 2, -1, 200052},
    [21013] = {21013, "Tir de barrage massif", [[ La gardienne choisit une cible aléatoire ayant le plus de santé et commence un tir en cloche sur elle, frappant la cible et tous ses alliés dans un rayon de 15 m d'une grêle de flèches infligeant à la cible principale 8000 dégâts physiques ignorant l'armure toutes les 2 sec. pendant 10 sec., et à ses alliés 6000 dégâts physiques ignorant l'armure chaque seconde pendant 10 sec. ]], 0, 0, 310560, 11651, 21014, 0, 0, 1, 32, 2, 2, -1, 0},
    [21014] = {21014, "Tir puissant", [[ La gardienne se concentre sur l'ennemi ayant le deuxième plus haut niveau de menace envers Malheur-Lacs, et bande son arc pendant 3 sec., puis décoche un tir dévastateur infligeant 300000 dégâts physiques ignorant l'armure, répartis uniformément entre tous les ennemis transpercés par le tir. ]], 0, 0, 310564, 11651, 21015, 0, 0, 1, 16, 2, 2, -1, 0},
    [21015] = {21015, "Cri perçant", [[ Un cri perçant qui rend muets tous les ennemis pendant 6 sec. ]], 0, 0, 310566, 11651, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21016] = {21016, "Broyeur des Courants", [[ L'un des gardiens de Malheur-Lacs, redoutable guerrier. Poursuit les ennemis, combattant au corps à corps. ]], 20772, 0, 0, 11651, 0, 21017, 0, 1, 0, 2, 2, -1, 200053},
    [21017] = {21017, "Assaut croissant", [[ Le broyeur des courants inflige à la cible 80000 dégâts physiques, ainsi que 20000 dégâts physiques à tous les ennemis dans un rayon de 10 m autour de lui. Chaque utilisation de cette capacité augmente de 20% la vitesse d'attaque du "Broyeur des Courants". ]], 0, 0, 310567, 11651, 21018, 0, 0, 1, 2049, 2, 2, -1, 0},
    [21018] = {21018, "Rugissement de guerre", [[ Un cri qui remonte le moral de tous les alliés, augmentant de 10% les dégâts qu'ils infligent. Se cumule jusqu'à 100 fois. ]], 0, 0, 310568, 11651, 0, 0, 0, 1, 96, 2, 2, -1, 0},
    [21019] = {21019, "Phase 1 : \"Les gardiens de Karathress\"", [[ Au début du combat, Karathress s'appuie sur ses gardiens, dont les vies soutiennent la "Barrière des vagues". Il tirera cependant aussi profit de leur mort. ]], 0, 0, 0, 11653, 21061, 21020, 0, 1, 0, 2, 2, -1, 0},
    [21020] = {21020, "Karathress, seigneur des profondeurs", [[  ]], 20662, 0, 0, 11653, 21034, 21021, 0, 1, 0, 2, 2, -1, 21214},
    [21021] = {21021, "Barrière des vagues", [[ Les gardiens de Karathress maintiennent une barrière qui soigne Karathress. La barrière restaure 10% de la santé maximale de Karathress chaque seconde et existera tant que ses gardiens ne seront pas tués. ]], 0, 0, 309252, 11653, 21022, 0, 0, 0, 32, 2, 2, -1, 0},
    [21022] = {21022, "Flèche du Cataclysme", [[ Karathress abat sur l'un des ennemis de ses gardiens une flèche d'énergie élémentaire, infligeant des dégâts égaux à 66% de la santé maximale sous forme de dégâts élémentaires dans un rayon de 20 m, ainsi que $[4 16200$]$[2 69840$]$[1 18000$] dégâts élémentaires toutes les 2 sec. pendant 24 sec. ]], 0, 0, 309253, 11653, 21023, 0, 0, 0, 17, 2, 2, -1, 0},
    [21023] = {21023, "Brise-monde", [[ Karathress assène une série de coups dévastateurs, secouant le sol autour de lui, infligeant 15000 dégâts physiques chaque seconde pendant 6 sec. à tous les ennemis dans un rayon de 10 m autour de lui. ]], 0, 0, 309254, 11653, 21024, 0, 0, 0, 2, 2, 2, -1, 0},
    [21024] = {21024, "Berserk", [[ Si la phase 2 ne commence pas dans les 6 minutes suivant l'activation du boss et de ses adds, Karathress et ses serviteurs survivants reçoivent +500% des dégâts infligés. ]], 0, 0, 27680, 11653, 21025, 0, 0, 0, 2048, 2, 2, -1, 0},
    [21025] = {21025, "Puissance de Charybde", [[ À la mort du gardien, une partie de sa puissance passe à Karathress, lui donnant accès à de nouvelles capacités. ]], 0, 0, 309287, 11653, 21028, 21026, 0, 0, 0, 2, 2, -1, 0},
    [21026] = {21026, "Grande vague de soin", [[ Invoque la force des Eaux pour se soigner ou soigner un allié, restaurant à la cible 25% de sa santé maximale. ]], 0, 0, 309256, 11653, 21027, 0, 0, 0, 96, 2, 2, -1, 0},
    [21027] = {21027, "Salve de flèches d'eau", [[ Des flèches d'eau frappent tous les ennemis dans un rayon supérieur à 15 m, infligeant 22500 dégâts de magie de givre. ]], 0, 0, 309257, 11653, 0, 0, 0, 0, 0, 2, 2, -1, 0},
    [21028] = {21028, "Puissance de Volniss", [[ À la mort du gardien, une partie de sa puissance passe à Karathress, lui donnant accès à de nouvelles capacités. ]], 0, 0, 309273, 11653, 21031, 21029, 0, 0, 0, 2, 2, -1, 0},
    [21029] = {21029, "Œil de la tempête", [[ Crée une zone de tempête de 8 m de rayon, centrée sur le lanceur de sorts. Tous les ennemis dans la zone subissent 6000 dégâts de nature toutes les 2 sec. Un ennemi franchissant la limite de cette zone subit 50000 dégâts de nature. L'"Œil de la tempête" dure 8 secondes. ]], 0, 0, 309258, 11653, 21030, 0, 0, 0, 18, 2, 2, -1, 0},
    [21030] = {21030, "Fureur de la tempête", [[ Confère à la cible la puissance de l'orage, augmentant de 5% les dégâts infligés et la vitesse d'incantation pendant 60 sec. ]], 0, 0, 309260, 11653, 0, 0, 0, 0, 0, 2, 2, -1, 0},
    [21031] = {21031, "Puissance de Sharkiss", [[ À la mort du gardien, une partie de sa puissance passe à Karathress, lui donnant accès à de nouvelles capacités. ]], 0, 0, 309278, 11653, 0, 21032, 0, 0, 0, 2, 2, -1, 0},
    [21032] = {21032, "Lien de flammes", [[ Relie l'ennemi et ses deux alliés les plus proches par des fils de flammes, leur infligeant 14000 dégâts de feu toutes les 2 sec. Le lien de flammes peut être rompu si la distance entre les trois cibles de cette capacité dépasse 30 m. ]], 0, 0, 309261, 11653, 21033, 0, 0, 0, 32, 2, 2, -1, 0},
    [21033] = {21033, "Barrière de feu", [[ Entoure la cible d'une barrière de feu qui réduit de 10% les dégâts subis pendant 20 sec. Tant que la barrière est active, elle inflige 3000 dégâts de feu aux ennemis dans un rayon de 45 m chaque seconde. ]], 0, 0, 309265, 11653, 0, 0, 0, 0, 0, 2, 2, -1, 0},
    [21034] = {21034, "Volniss, gardien des profondeurs :", [[  ]], 20670, 0, 0, 11653, 21043, 21035, 0, 1, 0, 2, 2, -1, 21965},
    [21035] = {21035, "Bénédiction des vagues", [[ Karathress et ses gardiens sont liés par la bénédiction des vagues. Restaure 10% de la santé maximale chaque seconde à tous les alliés dans un rayon de 30 m. ]], 0, 0, 309251, 11654, 21036, 0, 0, 0, 0, 2, 2, -1, 0},
    [21036] = {21036, "Aura de Volniss", [[ La puissance de Volniss électrifie tous les ennemis dans un rayon de 45 m. Chaque fois qu'un ennemi électrifié termine l'incantation d'un sort non instantané, Volniss consume 10% de son mana maximal, infligeant des dégâts à sa santé équivalents au mana consumé. ]], 0, 0, 309267, 11653, 21037, 0, 0, 0, 32, 2, 2, -1, 0},
    [21037] = {21037, "Œil de la tempête", [[ Crée une zone de tempête de 8 m de rayon, centrée sur le lanceur de sorts. Tous les ennemis dans la zone subissent 6000 dégâts de nature toutes les 2 sec. Un ennemi franchissant la limite de cette zone subit 50000 dégâts de nature. L'"Œil de la tempête" dure 8 secondes. ]], 0, 0, 309258, 11653, 21038, 0, 0, 0, 18, 2, 2, -1, 0},
