    [21039] = {21039, "Furie de la tempête", [[ Une série de trois Coups de tempête, infligeant 36000 dégâts physiques et augmentant de 50% les dégâts subis par la cible du prochain "Coup de tempête" pendant 12 secondes. ]], 0, 0, 309270, 11653, 21041, 21040, 0, 0, 1, 2, 2, -1, 0},
    [21040] = {21040, "Coup de tempête", [[ Un coup renforcé par la puissance élémentaire, infligeant 36000 dégâts physiques et augmentant de 50% les dégâts subis par la cible des "Coups de tempête" pendant 12 sec. Se cumule jusqu'à 10 fois. ]], 0, 0, 309271, 11653, 0, 0, 0, 0, 1, 2, 2, -1, 0},
    [21041] = {21041, "Rafale de tempête", [[ Une rafale de vent fulgurante infligeant 12000 dégâts physiques à toutes les cibles dans un rayon de 45 m. ]], 0, 0, 309272, 11653, 21042, 0, 0, 0, 0, 2, 2, -1, 0},
    [21042] = {21042, "Puissance de Volniss", [[ En mourant, Volniss confère sa puissance à Karathress, lui donnant accès aux capacités "Œil de la tempête" et "Fureur de la tempête". ]], 0, 0, 309273, 11653, 0, 0, 0, 0, 0, 2, 2, -1, 0},
    [21043] = {21043, "Sharkiss, gardien des profondeurs", [[  ]], 20671, 0, 0, 11653, 21051, 21044, 0, 1, 0, 2, 2, -1, 21966},
    [21044] = {21044, "Bénédiction des vagues", [[ Karathress et ses gardiens sont liés par la bénédiction des vagues. Restaure 10% de la santé maximale chaque seconde à tous les alliés dans un rayon de 30 m. ]], 0, 0, 309250, 11653, 21045, 0, 0, 0, 0, 2, 2, -1, 0},
    [21045] = {21045, "Aura de Sharkiss", [[ La puissance de Sharkiss brûle tous les ennemis dans un rayon de 45 m, infligeant 1750 dégâts de feu en réponse à chaque attaque de mêlée réussie, et augmente de 200% le niveau de menace généré par les ennemis. ]], 0, 0, 309274, 11653, 21047, 0, 0, 0, 32, 2, 2, -1, 0},
    [21047] = {21047, "Lien de flammes", [[ Relie l'ennemi et ses deux alliés les plus proches par des fils de flammes, leur infligeant 14000 dégâts de feu toutes les 2 sec. Le lien de flammes peut être rompu si la distance entre les trois cibles de cette capacité dépasse 30 m. ]], 0, 0, 309264, 11653, 21048, 0, 0, 0, 32, 2, 2, -1, 0},
    [21048] = {21048, "Bouclier de feu", [[ Entoure un allié d'un bouclier de feu qui absorbe des dégâts équivalents à 10% de la santé de l'allié au moment de l'incantation. Tant que le bouclier est actif, il inflige $[4 4500$]$[2 19400$]$[1 5000$] dégâts de feu aux ennemis dans un rayon de 6 m chaque seconde. ]], 0, 0, 309302, 11653, 21049, 0, 0, 0, 2, 2, 2, -1, 0},
    [21049] = {21049, "Flamme dévastatrice", [[ Des flammes enveloppent l'ennemi, lui infligeant 24000 dégâts de feu et augmentant de 10% les dégâts de feu qu'il subit pendant 60 sec. Se cumule jusqu'à 100 fois. ]], 0, 0, 309277, 11653, 21050, 0, 0, 0, 1, 2, 2, -1, 0},
