    [21053] = {21053, "Aura de Charybde", [[ La puissance de Charybde gèle tous les ennemis dans un rayon de 45 m, réduisant de 50% leur vitesse d'attaque et d'incantation. ]], 0, 0, 309279, 11653, 21054, 0, 0, 0, 0, 2, 2, -1, 0},
    [21054] = {21054, "Courroux de la marée", [[ La force des Eaux s'abat sur les ennemis dans un rayon de 8 m, leur infligeant $[4 5400$]$[2 23280$]$[1 6000$] dégâts de magie de givre et réduisant leur vitesse de déplacement de 50% pendant 6 sec., et provoquant une zone d'"Eau pure" infligeant $[4 9000$]$[2 38800$]$[1 10000$] dégâts de magie de givre toutes les 2 sec. La taille de la zone augmente avec le nombre de cibles touchées par le "Courroux de la marée". ]], 0, 0, 309281, 11653, 21057, 21055, 0, 0, 34, 2, 2, -1, 0},
    [21055] = {21055, "Eau pure", [[ Une zone d'eau glacée infligeant $[4 9000$]$[2 38800$]$[1 10000$] dégâts de magie de givre toutes les 2 sec. à tous les ennemis qui s'y trouvent. L'"Œil de la tempête" peut électrifier cette zone, la transformant en piège mortel. ]], 0, 0, 309283, 11653, 21056, 0, 0, 0, 0, 2, 2, -1, 0},
    [21056] = {21056, "Tempête", [[ La zone d'"Eau pure" a absorbé les éclairs de l'"Œil de la tempête", et est maintenant électrifiée. Tout contact avec cette zone entraînera la mort instantanée de tout ennemi. ]], 0, 0, 309284, 11653, 0, 0, 0, 0, 16, 2, 2, -1, 0},
