    [21058] = {21058, "Lance d'eau", [[ Un flot d'eau irrésistible transperce la cible, lui infligeant $[4 64800$]$[2 279360$]$[1 72000$] dégâts de magie de givre. ]], 0, 0, 309286, 11653, 21059, 0, 0, 0, 1, 2, 2, -1, 0},
    [21059] = {21059, "Salve de flèches d'eau", [[ Des flèches d'eau frappent tous les ennemis dans un rayon supérieur à 15 m, infligeant 22500 dégâts de magie de givre. ]], 0, 0, 309257, 11653, 21060, 0, 0, 0, 0, 2, 2, -1, 0},
    [21060] = {21060, "Puissance de Charybde", [[ En mourant, Charybde confère sa puissance à Karathress, lui donnant accès aux capacités "Salve de flèches d'eau" et "Grande vague de soin". ]], 0, 0, 309287, 11653, 0, 0, 0, 0, 0, 2, 2, -1, 0},
    [21061] = {21061, "Phase 2 : Pour Dame Vashj !", [[ Après la mort de tous les gardiens, Karathress devient vulnérable - mais conserve les capacités des deux premiers gardiens tombés. ]], 0, 0, 0, 11653, 0, 21062, 0, 1, 0, 2, 2, -1, 0},
    [21062] = {21062, "Brise-monde", [[ Karathress assène une série de coups dévastateurs, secouant le sol autour de lui, infligeant 15000 dégâts physiques chaque seconde pendant 6 sec. à tous les ennemis dans un rayon de 10 m autour de lui. ]], 0, 0, 309254, 11653, 21064, 21063, 0, 0, 2, 2, 2, -1, 0},
    [21063] = {21063, "Coup fatal", [[ Karathress termine la série d'attaques du "Brise-monde" par un coup monstrueux sur son ennemi actuel, infligeant 105000 dégâts physiques et réduisant de 95% l'efficacité des soins reçus par la cible pendant 80 sec. Ce coup touche toujours sa cible, ne peut être esquivé ni paré. ]], 0, 0, 309288, 11653, 0, 0, 0, 0, 17, 2, 2, -1, 0},
    [21064] = {21064, "Tremblement de terre", [[ Karathress concentre toute sa puissance dans le "Brise-monde", provoquant une onde de choc infligeant 10000 dégâts ignorant l'armure à tous les ennemis, ainsi qu'à leurs alliés dans un rayon de 6 m. Les ennemis touchés seront repoussés dans une direction aléatoire de 6 m. ]], 0, 0, 309289, 11653, 21069, 21065, 0, 0, 48, 2, 2, -1, 0},
    [21065] = {21065, "Poussée d'adrénaline", [[ La vue de Karathress invulnérable fonçant droit sur vous provoque une poussée d'adrénaline, augmentant votre vitesse de déplacement de 100% pendant 30 sec. ]], 0, 0, 309291, 11653, 21066, 0, 0, 0, 32, 2, 2, -1, 0},
    [21066] = {21066, "Charge glissante", [[ Karathress devient totalement invulnérable, augmente sa vitesse de déplacement de 100% et commence à poursuivre l'ennemi le plus éloigné. Tout ennemi se trouvant sur son chemin sera frappé par le "Coup glissant". Après avoir atteint sa cible, Karathress se précipite vers l'ennemi le plus éloigné suivant. ]], 0, 0, 309292, 11653, 21067, 0, 0, 0, 32, 2, 2, -1, 0},
    [21067] = {21067, "Attention concentrée", [[ Vous êtes la cible de Karathress. Fuyez. ]], 0, 0, 309295, 11653, 21068, 0, 0, 0, 32, 2, 2, -1, 0},
    [21068] = {21068, "Coup glissant", [[ Karathress tente de vous écraser sur le chemin de sa cible, infligeant 20000 dégâts physiques ignorant l'armure. Les dégâts que vous subissez de cette capacité sont augmentés de 100%. ]], 0, 0, 309296, 11653, 0, 0, 0, 0, 48, 2, 2, -1, 0},
