    [21080] = {21080, "Phase 1 : \"Que l'abîme des vagues vous engloutisse !\"", [[ Le géant commence le combat en se battant au corps à corps, se protégeant grâce à ses solides écailles et utilisant des attaques de zone. ]], 0, 0, 0, 11654, 21093, 21081, 0, 0, 0, 2, 2, -1, 0},
    [21081] = {21081, "Perfidie du géant", [[ Le géant marin surveille attentivement tous ses ennemis, en plus de sa cible principale. Les attaques de mêlée déclenchent l'effet "Regard fixe". ]], 0, 0, 310135, 11654, 21083, 21082, 0, 1, 32, 2, 2, -1, 0},
    [21082] = {21082, "Regard fixe", [[ Le géant vous surveille attentivement. À 10 cumuls, Pas-des-Vagues effectuera un "Coup monumental" sur un autre joueur plutôt que sur sa cible actuelle. ]], 0, 0, 310136, 11654, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21083] = {21083, "Coup monumental", [[ Un coup empli d'une incroyable puissance physique, infligeant à l'ennemi des dégâts physiques égaux à $[4 135$]$[2 582$]$[1 150$]% de sa santé maximale, et générant une onde de choc en direction de la cible, infligeant $[4 58500$]$[2 252200$]$[1 65000$] dégâts physiques à tous les ennemis (à l'exception de la cible principale) jusqu'à 200 m de distance. L'ennemi principal touché par cette capacité reçoit une charge de l'effet "Armure détruite". ]], 0, 0, 310137, 11654, 21085, 21084, 0, 1, 17, 2, 2, -1, 0},
    [21084] = {21084, "Armure détruite", [[ Le Coup monumental a brisé votre armure, lui infligeant des dégâts irréparables. Le score d'armure est réduit de 4%. ]], 0, 0, 310138, 11654, 0, 0, 0, 1, 1, 2, 2, -1, 0},
    [21085] = {21085, "Peau épaisse", [[ La peau du géant marin résiste à la plupart des attaques magiques et à distance. Les dégâts qu'il subit des ennemis spécialisés à distance ou des lanceurs de sorts sont réduits de 30%. ]], 0, 0, 310139, 11654, 21086, 0, 0, 1, 0, 2, 2, -1, 0},
    [21086] = {21086, "Piétinement écrasant", [[ Le géant marin secoue le sol, infligeant 16000 dégâts physiques aux ennemis dans un rayon de 10 m, ainsi que 10000 dégâts de magie de givre à tous les ennemis à plus de 10 m, chaque seconde pendant 3 sec. ]], 0, 0, 310140, 11654, 21087, 0, 0, 1, 4, 2, 2, -1, 0},
    [21087] = {21087, "Étreinte du géant", [[ Morogrim attrape l'ennemi qui est sa cible actuelle, le serrant dans une tentative de l'écraser, infligeant 50000 dégâts physiques chaque seconde pendant 3 sec., puis le projette (ou ses restes) vers le bassin d'eau. Si la cible atteint la surface de l'eau, elle invoquera des murlocs aveugles au point d'impact. Annule complètement le niveau de menace généré par la cible envers Pas-des-Vagues. ]], 0, 0, 310143, 11654, 21089, 21088, 0, 1, 5, 2, 2, -1, 0},
    [21088] = {21088, "Odeur de sang", [[ Vous avez survécu à l'"Étreinte du géant", mais le sang de vos blessures attire 6 "Murlocs des grands fonds", qui vous repèrent et vous attaqueront pendant 2 min. ]], 0, 0, 310145, 11654, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21089] = {21089, "Murloc des grands fonds", [[ Un petit combattant de mêlée dangereux, aveugle, qui n'attaque que les ennemis se trouvant à faible distance de lui.
Capable de sentir le sang et de repérer ainsi ses ennemis. En entrant en rage, il aiguise sa perception et attaque l'ennemi le plus proche, où qu'il se trouve. ]], 31538, 0, 0, 11654, 0, 21090, 0, 1, 0, 2, 2, -1, 200034},
    [21090] = {21090, "Cécité", [[ Le murloc des profondeurs est aveugle et incapable de détecter ses ennemis à plus de 5 m. — à moins qu’ils ne soient affectés par « Odeur du sang ». Insensible à la provocation. ]], 0, 0, 310146, 11654, 21091, 0, 0, 1, 32, 2, 2, -1, 0},
    [21091] = {21091, "Frénésie sanguinaire", [[ Le murloc des profondeurs entre en rage après avoir goûté à la chair de ses ennemis sans être rassasié. Les dégâts qu’il inflige et sa vitesse d’attaque augmentent de 50%. Insensible à la provocation. Le murloc poursuivra et attaquera l’ennemi le plus proche ou un « Garde de Marcheflot ». ]], 0, 0, 310147, 11654, 21092, 0, 0, 1, 2112, 2, 2, -1, 0},
    [21092] = {21092, "Taillade", [[ Une attaque tranchante infligeant 100% des dégâts de l’arme et laissant une plaie qui inflige $[4 7200$]$[2 31040$]$[1 8000$] points de dégâts physiques toutes les 2 sec. Cumulable jusqu’à 100 fois. ]], 0, 0, 310148, 11654, 0, 0, 0, 1, 1, 2, 2, -1, 0},
    [21093] = {21093, "Phase 2 : « Les grands courants d’Ageon ! »", [[ Lorsque ses points de vie tombent à 50%, la peau de Morogrim devient vulnérable, et le sang qui s’en écoule remplit le bassin, plongeant tous les « Murlocs des profondeurs » dans une frénésie furieuse. Le géant utilise toutes ses capacités pour écraser ses ennemis et appelle des gardes à son secours. ]], 0, 0, 0, 11654, 0, 21094, 0, 0, 0, 2, 2, -1, 0},
    [21094] = {21094, "Ruse du géant", [[ Le géant marin surveille attentivement tous ses ennemis, en plus de sa cible principale. Ses attaques de mêlée appliquent l’effet « Regard insistant ». ]], 0, 0, 310135, 11654, 21096, 21095, 0, 1, 32, 2, 2, -1, 0},
    [21095] = {21095, "Regard insistant", [[ Le géant vous observe attentivement. À 10 cumuls, Marcheflot lancera « Frappe monumentale » sur un autre joueur au lieu de sa cible actuelle. ]], 0, 0, 310136, 11654, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21096] = {21096, "Frappe monumentale", [[ Une attaque débordante d’une puissance physique incroyable, infligeant à la cible des dégâts physiques équivalents à $[4 135$]$[2 582$]$[1 150$]% de son maximum de points de vie, et générant une onde de choc en direction de la cible, infligeant $[4 58500$]$[2 252200$]$[1 65000$] points de dégâts physiques à tous les ennemis (à l’exception de la cible principale) jusqu’à 200 m. La cible principale frappée par cette capacité reçoit une charge de l’effet « Armure détruite ». ]], 0, 0, 310137, 11654, 21098, 21097, 0, 1, 17, 2, 2, -1, 0},
    [21097] = {21097, "Armure détruite", [[ La frappe monumentale a broyé votre armure, lui infligeant des dégâts irréparables. Votre armure est réduite de 4%. ]], 0, 0, 310138, 11654, 0, 0, 0, 1, 1, 2, 2, -1, 0},
    [21098] = {21098, "Peau endommagée", [[ Le géant est blessé, et sa peau ne lui offre plus une protection significative. Les dégâts qu’il subit sont augmentés de 30%. L’odeur du sang rend les murlocs des profondeurs fous, les plongeant dans une « Frénésie sanguinaire ». ]], 0, 0, 310150, 11654, 21099, 0, 0, 1, 32, 2, 2, -1, 0},
    [21099] = {21099, "Rugissement d’invocation", [[ Un rugissement tonitruant qui interrompt l’incantation des ennemis et les empêche de lancer des sorts de cette école pendant 5 sec. En entendant ce rugissement, un « Garde de Marcheflot » vient au secours du lanceur depuis le côté opposé au bassin. ]], 0, 0, 310151, 11654, 21100, 0, 0, 1, 33, 2, 2, -1, 0},
    [21100] = {21100, "Garde de Marcheflot", [[ Un puissant combattant de mêlée dont les attaques de zone écrasent les murlocs des profondeurs. Il possède un tempérament particulièrement explosif et peut facilement changer de cible après avoir subi suffisamment de dégâts. ]], 66813, 0, 0, 11654, 21106, 21101, 0, 1, 0, 2, 2, -1, 200035},
    [21101] = {21101, "Zèle", [[ Tant qu’il se trouve dans un rayon de 40 m. de Morogrim, le garde subit 90% de dégâts en moins, tandis que les dégâts qu’il inflige augmentent de 50% et sa vitesse d’attaque de 100%. ]], 0, 0, 310158, 11654, 21102, 0, 0, 1, 32, 2, 2, -1, 0},
    [21102] = {21102, "Rugissement galvanisant", [[ Un cri guerrier qui galvanise le lanceur, tous les « Murlocs des profondeurs » et Marcheflot, augmentant les dégâts qu’ils infligent de 10%. ]], 0, 0, 310160, 11654, 21103, 0, 0, 1, 2112, 2, 2, -1, 0},
    [21103] = {21103, "Écrasement", [[ Le garde bondit puis s’écrase au sol, infligeant 200000 points de dégâts physiques à tous les ennemis ainsi qu’aux « Murlocs des profondeurs » dans un rayon de 6 m. autour du lanceur. ]], 0, 0, 310161, 11654, 21104, 0, 0, 1, 48, 2, 2, -1, 0},
    [21104] = {21104, "Coup furieux", [[ Une attaque infligeant 50000 points de dégâts physiques et augmentant de 10% les dégâts de tous les « Coups furieux » suivants. ]], 0, 0, 310162, 11654, 21105, 0, 0, 1, 0, 2, 2, -1, 0},
    [21105] = {21105, "Tempérament sauvage", [[ Lorsque ses points de vie tombent à 50%, le garde s’enflamme de rage et sombre dans une furie incontrôlable. Les dégâts qu’il inflige augmentent de 100%, et il cesse de distinguer ses ennemis des « Murlocs des profondeurs », poursuivant et attaquant la cible la plus proche jusqu’à sa mort. ]], 0, 0, 310164, 11654, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21106] = {21106, "Séisme", [[ Morogrim invoque un séisme, infligeant $[4 14400$]$[2 62080$]$[1 16000$] points de dégâts physiques ignorant l’armure à chaque ennemi ainsi qu’à leurs alliés les plus proches dans un rayon de 6 m. Le séisme renverse tous les ennemis pendant 1 sec. et réveille $[4 3$]$[2 15$]$[1 4$] « Murlocs des profondeurs » endormis dans le bassin, plus près du centre de l’arène. ]], 0, 0, 310152, 11654, 21110, 21107, 0, 1, 32, 2, 2, -1, 0},
    [21107] = {21107, "Murloc des profondeurs", [[ Un petit combattant de mêlée mais dangereux, aveugle, qui n’attaque que les ennemis se trouvant à faible distance de lui.
Il est capable de sentir le sang et de repérer ainsi ses ennemis. Pris de frénésie, ses sens s’aiguisent et il attaque l’ennemi le plus proche, où qu’il se trouve. ]], 31538, 0, 0, 11654, 0, 21108, 0, 1, 0, 2, 2, -1, 200034},
    [21108] = {21108, "Frénésie sanguinaire", [[ Le murloc des profondeurs entre en rage après avoir goûté à la chair de ses ennemis sans être rassasié. Les dégâts qu’il inflige et sa vitesse d’attaque augmentent de 50%. Insensible à la provocation. Le murloc poursuivra et attaquera l’ennemi le plus proche ou un « Garde de Marcheflot ». ]], 0, 0, 310147, 11654, 21109, 0, 0, 1, 2080, 2, 2, -1, 0},
    [21109] = {21109, "Taillade", [[ Une attaque tranchante infligeant 100% des dégâts de l’arme et laissant une plaie qui inflige $[4 7200$]$[2 31040$]$[1 8000$] points de dégâts physiques toutes les 2 sec. Cumulable jusqu’à 100 fois. ]], 0, 0, 310148, 11654, 0, 0, 0, 1, 1, 2, 2, -1, 0},
    [21110] = {21110, "Dessiccation", [[ Le géant marin maudit 5 ennemis aléatoires, les desséchant pendant 20 sec. Les ennemis desséchés subissent 10000 points de dégâts physiques ignorant l’armure toutes les 2 sec., et les dégâts qu’ils infligent, l’efficacité des soins prodigués et reçus sont réduits de 80% s’ils ne se trouvent pas dans l’eau. ]], 0, 0, 310155, 11654, 0, 21111, 0, 1, 4, 2, 2, -1, 0},
    [21111] = {21111, "Déshydratation", [[ Votre corps perd continuellement son humidité. Vous subissez 10000 points de dégâts physiques ignorant l’armure toutes les 2 sec. Les dégâts infligés ainsi que l’efficacité des soins prodigués et reçus sont réduits de 80%. ]], 0, 0, 310156, 11654, 0, 21112, 0, 1, 4, 2, 2, -1, 0},
    [21112] = {21112, "Déshydratation", [[ Votre corps perd continuellement son humidité, mais le fait de rester dans l’eau affaiblit l’effet de la malédiction. Vous subissez 5000 points de dégâts de givre toutes les 1 sec. ]], 0, 0, 310157, 11654, 0, 0, 0, 1, 4, 2, 2, -1, 0},
    [21113] = {21113, "Phase 1 : « Je vais vous détruire ! » ", [[ Dame Vashj commence le combat en restant stationnaire, bombardant ses ennemis à l’arc et utilisant les sorts de son arsenal de Sorcière des mers.
La phase durera jusqu’à ce que les points de vie de Dame Vashj tombent à 70%. ]], 0, 0, 0, 11655, 21124, 21114, 0, 0, 0, 2, 2, -1, 0},
    [21114] = {21114, "Champ statique", [[ Un voile provoquant des décharges de foudre qui infligent $[4 1800$]$[2 7760$]$[1 2000$] points de dégâts de nature à tous les ennemis toutes les 1 sec. ]], 0, 0, 310630, 11655, 21115, 0, 0, 1, 0, 2, 2, -1, 0},
    [21115] = {21115, "Tir de l’hydre", [[ Un tir magistral qui touche la cible désignée, son allié le plus proche et son allié le plus éloigné, infligeant aux deux premiers $[4 117000$]$[2 504400$]$[1 130000$] points de dégâts physiques, et au troisième $[4 57600$]$[2 248320$]$[1 64000$] points de dégâts de nature. ]], 0, 0, 310632, 11655, 21116, 0, 0, 1, 17, 2, 2, -1, 0},
    [21116] = {21116, "Invocation d’élémentaire", [[ Des élémentaires d’eau émergent de l’eau autour de l’arène et se dirigent vers Dame Vashj. ]], 0, 0, 310635, 11655, 21120, 21117, 0, 1, 32, 2, 2, -1, 0},
    [21117] = {21117, "Élémentaire enchanté", [[ Rempli d’énergie, cet élémentaire d’eau se dirige vers Dame Vashj en ignorant tous les ennemis. Lorsqu’il atteint Dame Vashj, il utilise « Explosion de vapeur ». ]], 20076, 0, 0, 11655, 0, 21118, 0, 1, 0, 2, 2, -1, 200054},
    [21118] = {21118, "Explosion de vapeur", [[ Lorsqu’il atteint Dame Vashj, l’élémentaire entre en contact avec le champ statique, provoquant une monstrueuse explosion d’eau et de vapeur qui inflige 7000 points de dégâts de Givrefeu à tous les ennemis, tout en augmentant de 100% les dégâts qu’ils subissent de ce sort pendant 5 sec. ]], 0, 0, 310641, 11655, 21119, 0, 0, 1, 48, 2, 2, -1, 0},
    [21119] = {21119, "Forme liquide", [[ À sa mort, l’élémentaire se répand sur une zone de 8 m de rayon. Les ennemis présents dans la zone subissent $[4 2700$]$[2 11640$]$[1 3000$] points de dégâts de givre toutes les 1 sec., tandis que les alliés récupèrent $[4 90000$]$[2 388000$]$[1 100000$] points de vie toutes les 2 sec. ]], 0, 0, 310642, 11655, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21120] = {21120, "Courroux statique", [[ Le lanceur déchaîne sa colère sur deux lanceurs de sorts ennemis aléatoires. Les ennemis touchés émettent des décharges d’énergie statique, infligeant à eux-mêmes ainsi qu’à leurs alliés dans un rayon de 5 m. $[4 3600$]$[2 15520$]$[1 4000$] points de dégâts de nature toutes les 1 sec., et chaque cible touchée reçoit une « Charge statique ». ]], 0, 0, 310636, 11655, 21123, 21121, 0, 1, 32, 2, 2, -1, 0},
    [21121] = {21121, "Charge statique", [[ Vous êtes chargé d’énergie statique. À 8 cumuls, elle se déchargera et déclenchera l’effet « Foudre ramifiée ». ]], 0, 0, 310638, 11655, 0, 21122, 0, 1, 32, 2, 2, -1, 0},
    [21122] = {21122, "Foudre ramifiée", [[ La charge statique accumulée par la cible se décharge sous la forme d’un éclair ramifié, frappant tous les alliés dans un rayon de 20 m. (mais pas le porteur de la charge lui-même) avec un éclair infligeant $[4 22500$]$[2 97000$]$[1 25000$] points de dégâts de nature, et confère à chaque cible touchée une « Charge statique ». ]], 0, 0, 310639, 11655, 0, 0, 0, 1, 16, 2, 2, -1, 0},
    [21123] = {21123, "Tir de mise à la terre", [[ Un tir spécial qui touche trois ennemis au corps à corps. Les cibles touchées subissent 8000 points de dégâts physiques ignorant l’armure toutes les 2 sec., tandis que les dégâts de nature qu’elles subissent sont réduits de 90%. Subir des dégâts de « Foudre ramifiée » ne déclenchera pas l’application de « Charge statique » et dissipera cet effet. ]], 0, 0, 310640, 11655, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21124] = {21124, "Phase 2 : « La tempête vous emportera ! »", [[ Lorsque ses points de vie tombent à 70%, Dame Vashj invoque la « Tempête », qui renforce certaines de ses capacités et lui en confère de nouvelles — tout en augmentant également l’effet des élémentaires enchantés. La phase dure jusqu’à ce que les points de vie de Dame Vashj tombent à 40%. ]], 0, 0, 0, 11655, 21139, 21125, 0, 0, 0, 2, 2, -1, 0},
    [21125] = {21125, "Tempête", [[ Les nuages s’amoncellent au-dessus du Sanctuaire du Serpent. À la fin de l’incantation, une tempête éclatera, faisant apparaître 4 « Tourbillons » et tuant instantanément tous les ennemis affectés par « Tir de mise à la terre ». ]], 0, 0, 310645, 11655, 21128, 21126, 0, 1, 48, 2, 2, -1, 0},
    [21126] = {21126, "Tourbillon déchaîné", [[ Un tourbillon déchaîné tourne autour de l’arène, soulevant dans les airs tout ennemi se trouvant dans un rayon de 6 m. ]], 0, 0, 310652, 11655, 0, 21127, 0, 1, 32, 2, 2, -1, 0},
    [21127] = {21127, "Tourbillon", [[ Le tourbillon vous emporte et vous soulève haut dans les airs. Vous ne pouvez pas vous déplacer, mais vous pouvez attaquer et lancer des sorts. Les rafales de vent vous infligent 3000 points de dégâts de nature toutes les 1 sec. ]], 0, 0, 310655, 11655, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21128] = {21128, "Champ statique", [[ Un voile provoquant des décharges de foudre qui infligent $[4 1800$]$[2 7760$]$[1 2000$] points de dégâts de nature à tous les ennemis toutes les 1 sec. ]], 0, 0, 310630, 11655, 21129, 0, 0, 1, 0, 2, 2, -1, 0},
    [21129] = {21129, "Tir de l’hydre", [[ Un tir magistral qui touche la cible désignée, son allié le plus proche et son allié le plus éloigné, infligeant aux deux premiers $[4 117000$]$[2 504400$]$[1 130000$] points de dégâts physiques, et au troisième $[4 57600$]$[2 248320$]$[1 64000$] points de dégâts de nature. ]], 0, 0, 310632, 11655, 21130, 0, 0, 1, 17, 2, 2, -1, 0},
    [21130] = {21130, "Invocation d’élémentaire", [[ Des élémentaires d’eau émergent de l’eau autour de l’arène et se dirigent vers Dame Vashj. ]], 0, 0, 310635, 11655, 21135, 21131, 0, 1, 32, 2, 2, -1, 0},
    [21131] = {21131, "Élémentaire enchanté", [[ Rempli d’énergie, cet élémentaire d’eau se dirige vers Dame Vashj en ignorant tous les ennemis. Lorsqu’il atteint Dame Vashj, il utilise « Explosion de vapeur ». ]], 20076, 0, 0, 11655, 0, 21132, 0, 1, 0, 2, 2, -1, 200054},
    [21132] = {21132, "Explosion de vapeur", [[ Lorsqu’il atteint Dame Vashj, l’élémentaire entre en contact avec le champ statique, provoquant une monstrueuse explosion d’eau et de vapeur qui inflige 7000 points de dégâts de Givrefeu à tous les ennemis, tout en augmentant de 100% les dégâts qu’ils subissent de ce sort pendant 5 sec. ]], 0, 0, 310641, 11655, 21133, 0, 0, 1, 48, 2, 2, -1, 0},
    [21133] = {21133, "Tension", [[ L’explosion de l’élémentaire accroît la tension, augmentant de 2% les dégâts infligés par Dame Vashj jusqu’à la fin du combat. ]], 0, 0, 310669, 11655, 21134, 0, 0, 1, 2048, 2, 2, -1, 0},
    [21134] = {21134, "Forme liquide", [[ À sa mort, l’élémentaire se répand sur une zone de 8 m de rayon. Les ennemis présents dans la zone subissent $[4 2700$]$[2 11640$]$[1 3000$] points de dégâts de givre toutes les 1 sec., tandis que les alliés récupèrent $[4 90000$]$[2 388000$]$[1 100000$] points de vie toutes les 2 sec. ]], 0, 0, 310642, 11655, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21135] = {21135, "Courroux statique impitoyable", [[ Le lanceur déchaîne sa colère sur deux lanceurs de sorts ennemis aléatoires. Les ennemis touchés émettent des décharges d’énergie statique, infligeant à eux-mêmes ainsi qu’à leurs alliés dans un rayon de 5 m. 4000 points de dégâts de nature toutes les 1 sec., et chaque cible touchée reçoit une « Surcharge statique ». ]], 0, 0, 310659, 11655, 21138, 21136, 0, 1, 32, 2, 2, -1, 0},
    [21136] = {21136, "Surcharge statique", [[ Vous êtes chargé d’énergie statique. À 8 cumuls, elle se déchargera et déclenchera l’effet « Désintégration ». ]], 0, 0, 310661, 11655, 0, 21137, 0, 1, 32, 2, 2, -1, 0},
    [21137] = {21137, "Désintégration", [[ La surcharge statique accumulée par la cible se décharge sous la forme d’un éclair ramifié d’une puissance monstrueuse, frappant tous les alliés dans un rayon de 20 m. (mais pas le porteur de la charge lui-même) avec un éclair infligeant 180000 points de dégâts de nature. Les courants d’air du « Tourbillon » peuvent empêcher cet effet. ]], 0, 0, 310662, 11655, 0, 0, 0, 1, 16, 2, 2, -1, 0},
    [21138] = {21138, "Double tir de givre", [[ Un double tir frappant les ennemis situés à la deuxième et à la troisième place dans la table de menace du lanceur. Le tir inflige 30000 points de dégâts de givre et augmente de 20% les dégâts de givre subis par ces ennemis pendant 30 sec. ]], 0, 0, 310668, 11655, 0, 0, 0, 1, 3, 2, 2, -1, 0},
    [21139] = {21139, "Phase 3 : « N’est-il pas temps d’aller vous cacher ? »", [[ Lorsque ses points de vie tombent à 40%, Dame Vashj cesse d’être stationnaire, utilise des attaques de mêlée et poursuit sa cible actuelle — tout en continuant d’utiliser ses capacités à distance et les sorts renforcés par la tempête. Les élémentaires enchantés disparaissent et ne réapparaissent plus jusqu’à la fin du combat — mais sont remplacés par des raies empoisonnées. ]], 0, 0, 0, 11655, 0, 21140, 0, 0, 0, 2, 2, -1, 0},
    [21140] = {21140, "Tourbillon déchaîné", [[ Un tourbillon déchaîné tourne autour de l’arène, soulevant dans les airs tout ennemi se trouvant dans un rayon de 6 m. ]], 0, 0, 310652, 11655, 21142, 21141, 0, 1, 32, 2, 2, -1, 0},
    [21141] = {21141, "Tourbillon", [[ Le tourbillon vous emporte et vous soulève haut dans les airs. Vous ne pouvez pas vous déplacer, mais vous pouvez attaquer et lancer des sorts. Les rafales de vent vous infligent 3000 points de dégâts de nature toutes les 1 sec. ]], 0, 0, 310655, 11655, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21142] = {21142, "Invocation de raies", [[ Deux raies empoisonnées viennent en aide à Dame Vashj. ]], 0, 0, 310657, 11655, 21147, 21143, 0, 1, 0, 2, 2, -1, 0},
    [21143] = {21143, "Raie empoisonnée", [[ Un lanceur mobile flottant qui vole haut au-dessus du champ de bataille, bombardant de poison les ennemis en contrebas. Seuls les combattants à distance soulevés dans les airs par le « Tourbillon » sont capables d’atteindre les raies et de les détruire. ]], 20828, 0, 0, 11655, 0, 21144, 0, 1, 0, 2, 2, -1, 200055},
    [21144] = {21144, "Éclair", [[ Une décharge électrique frappe un ennemi et lui inflige 11000 points de dégâts de nature. ]], 0, 0, 310664, 11655, 21145, 0, 0, 1, 4, 2, 2, -1, 0},
    [21145] = {21145, "Crachat empoisonné", [[ Un crachat de poison s’écrase dans l’arène, laissant une zone de 8 m de rayon qui inflige $[4 16200$]$[2 69840$]$[1 18000$] points de dégâts de nature toutes les 3 sec. à tous les ennemis qui entrent en contact avec elle. ]], 0, 0, 310665, 11655, 21146, 0, 0, 1, 48, 2, 2, -1, 0},
    [21146] = {21146, "Frénésie", [[ 60 secondes après son apparition, le lanceur entre en frénésie. Le temps entre les utilisations de ses capacités est réduit de moitié. ]], 0, 0, 310667, 11655, 0, 0, 0, 1, 2048, 2, 2, -1, 0},
    [21147] = {21147, "Tir de l’hydre", [[ Un tir magistral qui touche la cible désignée, son allié le plus proche et son allié le plus éloigné, infligeant aux deux premiers $[4 117000$]$[2 504400$]$[1 130000$] points de dégâts physiques, et au troisième $[4 57600$]$[2 248320$]$[1 64000$] points de dégâts de nature. ]], 0, 0, 310632, 11655, 21148, 0, 0, 1, 17, 2, 2, -1, 0},
