    [21226] = {21226, "Cascade temporelle", [[ Frappe un ennemi avec une anomalie arcanique qui infligera 100000 points de dégâts des arcanes, répartis entre la cible et ses alliés dans un rayon de 6 m., après 10 secondes. Les ennemis ayant partagé les dégâts de cette capacité (mais pas la victime initiale de l'anomalie) reçoivent l'effet "Cascade inversée". ]], 0, 0, 317158, 11658, 21228, 21227, 0, 0, 48, 2, 2, 8, 0},
    [21227] = {21227, "Cascade inversée", [[ Après avoir absorbé les dégâts de Cascade temporelle, vous subissez un effet résiduel de l'anomalie qui infligera 60000 points de dégâts des arcanes à tous vos alliés (mais pas à vous-même) dans un rayon de 6 m. après 10 sec. Ignore les effets de résistance. ]], 0, 0, 317160, 11658, 0, 0, 0, 1, 48, 2, 2, 8, 0},
    [21228] = {21228, "Cri résonnant", [[ Le lanceur de sorts pousse un cri qui fait vibrer l'âme de tous ses ennemis, interrompant instantanément les sorts en cours d'incantation et empêchant l'incantation de sorts de la même école que celle interrompue pendant 6 sec. ]], 0, 0, 312210, 11658, 21229, 0, 0, 0, 32, 2, 2, -1, 0},
    [21229] = {21229, "Lignes temporelles", [[ Le lanceur de sorts déforme l'espace et le temps, se téléportant vers une position aléatoire sur le champ de bataille. Depuis une autre ligne temporelle, une copie complète de lui-même vient à son secours (utilisant "Frappe résonnante", "Retour" et "Châtiment arcanique"), apparaissant à un autre endroit aléatoire. Toutes les versions actives du lanceur de sorts utilisent alors "Protection temporelle" et commencent à lancer "Retour". ]], 0, 0, 312211, 11658, 21232, 21230, 0, 0, 2080, 2, 2, 2, 0},
    [21230] = {21230, "Protection temporelle", [[ Le lanceur de sorts s'entoure d'un bouclier absorbant $[2 400000$]$[4 400000$]$[1 400000$] points de dégâts. Tant que cette protection est active, ses sorts ne peuvent pas être interrompus. ]], 0, 0, 312213, 11658, 21231, 0, 0, 1, 2, 2, 2, 2, 0},
    [21231] = {21231, "Retour", [[ Le lanceur de sorts agit sur la ligne temporelle pour tenter de se rendre $[2 100$]$[4 100$]$[1 100$]% de sa santé maximale. Les soins rendus sont répartis équitablement entre toutes les "copies" actives du lanceur de sorts. ]], 0, 0, 312214, 11658, 0, 0, 0, 1, 96, 2, 2, 2, 0},
    [21232] = {21232, "Lignes temporelles", [[ Le lanceur déforme l’espace et le temps, se téléportant vers une position aléatoire sur le champ de bataille. Depuis une autre ligne temporelle, une copie complète de lui-même vient lui prêter main-forte (utilisant "Frappe résonnante", "Retour" et "Châtiment arcanique"), apparaissant à un autre point aléatoire. Toutes les versions actives du lanceur utilisent ensuite "Protection temporelle" et commencent à lancer "Retour". ]], 0, 0, 312211, 11658, 21236, 21233, 0, 0, 2080, 2, 2, 8, 0},
    [21233] = {21233, "Protection temporelle", [[ Le lanceur s'entoure d'un bouclier absorbant $[2 1200000$]$[4 1200000$]$[1 1200000$] points de dégâts. Tant que cette protection est active, les sorts qu’il lance ne peuvent pas être interrompus. ]], 0, 0, 317163, 11658, 21234, 0, 0, 1, 2, 2, 2, 8, 0},
    [21234] = {21234, "Retour", [[ Le lanceur agit sur la ligne temporelle afin de restaurer $[2 100$]$[4 100$]$[1 100$]% de son maximum de points de vie. Les soins rendus sont répartis équitablement entre toutes les "copies" actives du lanceur. ]], 0, 0, 312214, 11658, 21235, 0, 0, 1, 96, 2, 2, 8, 0},
    [21235] = {21235, "Lien intemporel", [[ Lié à une version alternative de lui-même venue d’une autre ligne temporelle. Les dégâts subis sont répartis entre toutes les "copies" du lanceur et sont également réduits de 50%. ]], 0, 0, 317164, 11658, 0, 0, 0, 1, 0, 2, 2, 8, 0},
    [21236] = {21236, "Tourbillons intemporels", [[ Le lanceur invoque des énergies intemporelles qui jaillissent dans trois zones autour de lui, formant des vortex. Rester dans la zone d’effet d’un "Tourbillon intemporel" détruit progressivement l’ennemi et l’empêche également de lancer des sorts ou d’effectuer des attaques. ]], 0, 0, 317165, 11658, 21237, 0, 0, 0, 16, 2, 2, 8, 0},
    [21237] = {21237, "Temps démêlé", [[ Les Distordeurs temporels vivant dans le Sanctuaire de Bronze tentent, avant de mourir, de démêler la trame même du temps afin de réécrire le passé en faveur de leurs semblables, augmentant leurs dégâts de 5% ainsi que leurs points de vie de 5%.
Cet effet est cumulable jusqu’à 5 fois.

Si le Distordeur temporel Elonus est vaincu alors que le combat a commencé avec 5 charges de "Temps démêlé", son butin contiendra des objets supplémentaires de meilleure qualité. ]], 0, 0, 315530, 11658, 0, 0, 0, 1, 4096, 2, 2, -1, 0},
    [21238] = {21238, "Murozond", [[ Le seigneur du temps déchu combat au corps à corps, invoque des gardiens et utilise de puissants sorts d’ombre et de magie temporelle. ]], 38931, 0, 0, 11659, 21287, 21239, 0, 1, 0, 2, 2, -1, 50612},
    [21239] = {21239, "Brûleur du temps", [[ Le temps se déstabilise autour de Murozond, créant des vortex de "Temps brûlant" qui retournent la réalité sur elle-même, toutes les 2 sec., en un point aléatoire autour du lanceur. Les zones de "Temps brûlant" ont tendance à apparaître proches les unes des autres. ]], 0, 0, 313111, 11659, 21241, 21240, 0, 0, 32, 2, 2, 2, 0},
    [21240] = {21240, "Temps brûlant", [[ La réalité se retourne sous l’effet du flux chaotique du temps. Inflige 6000 points de dégâts d’ombre à tous les ennemis dans un rayon de 6 m toutes les 2 sec. Ignore les effets de résistance. ]], 0, 0, 313113, 11659, 0, 0, 0, 1, 32, 2, 2, 2, 0},
    [21241] = {21241, "Souffle de l’Infini", [[ Expire un flot de magie d’ombre infligeant $[2 40000$]$[4 40000$]$[1 40000$] points de dégâts d’ombre à tous les ennemis dans un cône de 200 m devant le lanceur. Si une cible est déjà affectée par "Souffle de l’Infini", elle meurt instantanément. Cette technique ignore les effets de résistance. ]], 0, 0, 313115, 11659, 21242, 0, 0, 0, 19, 2, 2, 2, 0},
    [21242] = {21242, "Souffle de l’Infini", [[ Expire un flot de magie d’ombre infligeant 80000 points de dégâts à tous les ennemis dans un cône de 40 m devant le lanceur, puis inflige également 10000 points de dégâts d’ombre toutes les 2 sec. pendant 120 sec. Cet effet périodique est cumulable jusqu’à 100 fois. ]], 0, 0, 313115, 11659, 21243, 0, 0, 0, 19, 2, 2, 8, 0},
    [21243] = {21243, "Onde de distorsion", [[ Frappe tous les ennemis utilisant du mana avec une onde de distorsion, leur infligeant $[2 10000$]$[4 10000$]$[1 10000$] points de dégâts d’ombre et téléportant chaque ennemi à une position aléatoire dans un rayon de 10 m.
Cette technique alterne avec "Avenir terrifiant". ]], 0, 0, 313116, 11659, 21244, 0, 0, 0, 32, 2, 2, 2, 0},
