    [21249] = {21249, "Corruption intemporelle", [[ Le lanceur afflige 5 ennemis dans un rayon de 50 m d’une corruption qui inflige $[2 4000$]$[4 4000$]$[1 4000$] points de dégâts d’ombre toutes les 3 sec. Cumulable jusqu’à 10 fois. ]], 0, 0, 312229, 11659, 21250, 0, 0, 1, 256, 2, 2, 2, 0},
    [21250] = {21250, "Temps figé", [[ Le lanceur retourne sa puissance contre le cours du temps pendant 5 sec., frappant les ennemis dans un rayon de 50 m avec des vagues de distorsion temporelle infligeant $[2 2000$]$[4 2000$]$[1 2000$] points de dégâts d’ombre toutes les 0.5 sec. et réduisant la vitesse des cibles touchées de 10%. À 10 cumuls, le temps est complètement arrêté pendant 10 sec. ]], 0, 0, 312236, 11659, 21251, 0, 0, 1, 96, 2, 2, 2, 0},
