    [21256] = {21256, "Assaut", [[ Pendant 5 sec., le lanceur enchaîne une série de frappes en poursuivant sa cible, infligeant à tous les ennemis dans un cône devant lui $[2 8000$]$[4 8000$]$[1 8000$] points de dégâts physiques toutes les 0.5 sec., tandis que sa vitesse de déplacement est réduite de 50%. ]], 0, 0, 312232, 11659, 0, 0, 0, 1, 3, 2, 2, 2, 0},
    [21257] = {21257, "Appel des Intemporels", [[ Invoque à son aide deux "Destructeurs de la lignée de l’Infini" et deux "Gardes de la lignée de l’Infini". Les alliés invoqués sont répartis en paires et apparaissent aux deux extrémités opposées du champ de bataille. En plus, un "Distordeur temporel de la lignée de l’Infini" ou un "Brûleur du temps de la lignée de l’Infini" sera invoqué et apparaîtra avec l’une des paires d’Intemporels. ]], 0, 0, 313120, 11659, 21274, 21258, 0, 1, 3, 2, 2, 8, 0},
