    [21267] = {21267, "Châtiment temporel", [[ Le lanceur de sorts châtie l'adversaire, lui infligeant $[2 18004$]$[4 18004$]$[1 18004$] dégâts de magie arcanique, et réduisant sa vitesse d'attaque, de déplacement et d'incantation de 5%. Se cumule jusqu'à 20 fois. Ce sort ignore les effets de résistance. ]], 0, 0, 312217, 11659, 21268, 0, 0, 1, 1, 2, 2, 8, 0},
    [21268] = {21268, "Vents de distorsion", [[ Le lanceur de sorts déforme la réalité dans le Sanctuaire de bronze, infligeant $[2 10000$]$[4 10000$]$[1 10000$] dégâts de magie des ténèbres à tous les ennemis toutes les 2 sec. Ce sort ignore les effets de résistance et ne peut être interrompu. ]], 0, 0, 312218, 11659, 21269, 0, 0, 1, 4, 2, 2, 8, 0},
    [21269] = {21269, "Temps dénoué", [[ Au bord de la mort, le lanceur de sorts dénoue le tissu même du temps, renforçant tous les autres dragons de l'Infini en augmentant leurs dégâts de 5% et leurs points de vie de 5%. Se cumule jusqu'à 5 fois. ]], 0, 0, 315992, 11659, 0, 0, 0, 1, 4128, 2, 2, 8, 0},
