    [21271] = {21271, "Lacération vieillissante", [[ Une attaque circulaire touchant tous les ennemis dans un secteur devant le lanceur de sorts, infligeant à chacun 200% des dégâts d'arme sous forme de dégâts de magie des ténèbres. Les ennemis touchés se mettent à vieillir rapidement, ce qui réduit leur réserve maximale de points de vie de 25%. Se cumule jusqu'à 3 fois. ]], 0, 0, 312225, 11659, 21272, 0, 0, 1, 17, 2, 2, 8, 0},
    [21272] = {21272, "Flétrissement", [[ Le lanceur de sorts tente d'absorber la force vitale de tous les ennemis, infligeant $[2 40000$]$[4 40000$]$[1 40000$] dégâts de magie des ténèbres en cas de réussite de l'incantation. Ce sort ignore les effets de résistance. ]], 0, 0, 312226, 11659, 21273, 0, 0, 1, 80, 2, 2, 8, 0},
    [21273] = {21273, "Enrage", [[ En atteignant 40% de points de vie, le lanceur de sorts entre en rage. Les dégâts qu'il inflige augmentent de 50%, tandis qu'il devient immunisé aux effets de provocation. ]], 0, 0, 312227, 11659, 0, 0, 0, 1, 2048, 2, 2, 8, 0},
    [21274] = {21274, "Temps à l'agonie", [[ La simple présence de l'Intemporel détruit les lignes temporelles, précipitant la fin de la réalité telle que nous la connaissons. Toutes les 5 sec., tous les ennemis du lanceur de sorts subissent des dégâts égaux à 40% de leurs points de vie actuels. ]], 0, 0, 317257, 11659, 21275, 0, 0, 0, 4, 2, 2, 8, 0},
    [21275] = {21275, "Piège temporel", [[ Dix pièges intemporels apparaissent sous des ennemis aléatoires. Après 6 sec., chaque piège s'active, étourdissant pendant 10 sec. tous les ennemis se trouvant dans la zone d'effet. Ignore les effets d'invulnérabilité. ]], 0, 0, 317259, 11659, 21276, 0, 0, 0, 48, 2, 2, 8, 0},
    [21276] = {21276, "Réflexion intemporelle", [[ Les flux du temps obéissent au lanceur de sorts, l'entourant d'une barrière qui réfléchit tous les sorts pendant 5 sec. ]], 0, 0, 317262, 11659, 21277, 0, 0, 0, 18, 2, 2, 8, 0},
    [21277] = {21277, "Fin du temps", [[ Rempli de rage, Murozond fait appel à son pouvoir sur le temps, infligeant à tous les ennemis $[2 2000$]$[4 2000$]$[1 2000$] ed. dégâts toutes les 1 sec. et s'entourant d'une barrière absorbant tous les dégâts. L'horloge du temps commence son décompte, sonnant 12 coups en 60 secondes. À chaque coup, des sphères de temps se dirigeront depuis les marqueurs temporels vers Murozond ; elles doivent être interceptées. ]], 0, 0, 313122, 11659, 0, 21278, 0, 1, 48, 2, 2, -1, 0},
    [21278] = {21278, "Barrière intemporelle", [[ La fin des temps exige de la concentration. Absorbe tous les dégâts reçus. ]], 0, 0, 313124, 11659, 21279, 0, 0, 0, 0, 2, 2, -1, 0},
    [21279] = {21279, "Sphère de temps blanche", [[ Vous avez touché une sphère de temps blanche et l'avez absorbée. Toucher une autre "Sphère de temps blanche" déclenchera l'effet "Déstabilisation temporelle". ]], 0, 0, 313129, 11659, 21282, 21280, 0, 0, 32, 2, 2, -1, 0},
