    [21290] = {21290, "Flamme infinie de la Corruption", [[ Enveloppe jusqu'à 10 ennemis d'une flamme dévorante infligeant 700 dégâts de magie de feu toutes les 1 sec. Les dégâts infligés par la flamme augmentent à chaque tic. Cet effet peut être dissipé. ]], 0, 0, 317729, 11660, 21291, 0, 0, 1, 132, 2, 2, 2, 0},
    [21291] = {21291, "Coup dévastateur", [[ Un coup d'une puissance incroyable infligeant 120000 dégâts physiques. Les dégâts sont répartis équitablement entre toutes les cibles touchées. Les ennemis touchés subissent 100% de dégâts physiques supplémentaires pendant les 60 sec. suivantes. ]], 0, 0, 317541, 11660, 21292, 0, 0, 1, 16, 2, 2, 1, 0},
    [21292] = {21292, "Coup dévastateur", [[ Un coup d'une puissance incroyable infligeant 240000 dégâts physiques. Les dégâts sont répartis équitablement entre toutes les cibles touchées. Les ennemis touchés subissent 100% de dégâts physiques supplémentaires pendant les 60 sec. suivantes. ]], 0, 0, 317730, 11660, 21293, 0, 0, 1, 16, 2, 2, 2, 0},
    [21293] = {21293, "Coup foudroyant", [[ Inflige instantanément 28750 dégâts physiques et 27505 dégâts supplémentaires sur 5 sec. ]], 0, 0, 317543, 11660, 21294, 0, 0, 1, 0, 2, 2, -1, 0},
    [21294] = {21294, "Marque de la Corruption", [[ Marque 2 ennemis avec la magie de la Corruption ; à la fin de l'effet, un vortex de Corruption apparaît sous la cible, dure 60 sec. et inflige 8250 dégâts de magie de feu toutes les 1 sec. ]], 0, 0, 317544, 11660, 21295, 0, 0, 1, 32, 2, 2, -1, 0},
    [21295] = {21295, "Terreur primitive", [[ Émet une vague de terreur, forçant tous les joueurs qui le regardent à fuir de peur pendant 10 sec. Cet effet peut être dissipé en soignant la cible touchée de 25000 points de vie. ]], 0, 0, 317548, 11660, 21296, 0, 0, 1, 36, 2, 2, -1, 0},
    [21296] = {21296, "Éclair de Corruption", [[ Frappe un ennemi avec un éclair de Corruption infligeant 9500 dégâts de magie de feu, qui bondit ensuite vers un autre ennemi à proximité. Le sort touche jusqu'à 3 cibles, chaque saut augmentant les dégâts de l'éclair de 30%. ]], 0, 0, 317549, 11660, 21297, 0, 0, 1, 0, 2, 2, 1, 0},
    [21297] = {21297, "Éclair de Corruption", [[ Frappe un ennemi avec un éclair de Corruption infligeant 10500 dégâts de magie de feu, qui bondit ensuite vers un autre ennemi à proximité. Le sort touche jusqu'à 8 cibles, chaque saut augmentant les dégâts de l'éclair de 15%. ]], 0, 0, 317731, 11660, 0, 0, 0, 1, 0, 2, 2, 2, 0},
    [21298] = {21298, "Phase 1 : voile des ténèbres", [[  ]], 0, 0, 0, 11661, 21311, 21299, 0, 2, 0, 2, 2, -1, 0},
    [21299] = {21299, "Flèche des Ténèbres", [[ Inflige à la cible 15000 dégâts de magie des ténèbres, et à tous les ennemis dans un rayon de 5 m. 3000 dégâts de magie des ténèbres.
Octroie 10 points d'énergie des Ténèbres. ]], 0, 0, 317563, 11661, 21300, 0, 0, 1, 0, 2, 2, -1, 0},
    [21300] = {21300, "Coup obscurcissant", [[ Un coup chargé de magie des ténèbres infligeant 20000 dégâts à la cible et lui appliquant la "Marque du Sans-Visage", qui l'immobilise et inflige 5000 dégâts de magie des ténèbres à tous ses alliés dans un rayon de 15 m. toutes les 1 sec. pendant 10 sec.
Octroie 20 points d'énergie des Ténèbres. ]], 0, 0, 317564, 11661, 21302, 21301, 0, 1, 1, 2, 2, -1, 0},
    [21301] = {21301, "Marque du Sans-Visage", [[ Immobilise la cible et inflige 5000 dégâts à tous ses alliés toutes les 1 sec. dans un rayon de 15 m. pendant 10 sec. ]], 0, 0, 317565, 11661, 0, 0, 0, 2, 0, 2, 2, -1, 0},
    [21302] = {21302, "Création d'une sphère des Ténèbres", [[ Libère une sphère. Une fois posée, la Sphère des Ténèbres inflige toutes les 2 sec. 2000 dégâts de magie des ténèbres aux ennemis dans un rayon de 8 m ; si aucun ennemi ne se trouve dans ce rayon, la sphère se met également à émettre des "Vagues d'Obscurité" infligeant 12000 dégâts à tous les ennemis. ]], 0, 0, 317567, 11661, 21305, 21303, 0, 1, 32, 2, 2, -1, 0},
    [21303] = {21303, "Sphère des ténèbres", [[ La Sphère des Ténèbres inflige toutes les 2 sec. 2000 dégâts de magie des ténèbres aux ennemis dans un rayon de 8 m ; si aucun ennemi ne se trouve dans ce rayon, la sphère se met également à émettre des "Vagues d'Obscurité" infligeant 12000 dégâts à tous les ennemis. ]], 0, 0, 317569, 11661, 0, 21304, 0, 1, 0, 2, 2, -1, 0},
    [21304] = {21304, "Vagues d'Obscurité", [[ Inflige 12000 dégâts à tous les ennemis. ]], 0, 0, 317571, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21305] = {21305, "Souffle d'Obscurité", [[ Un souffle de magie des ténèbres infligeant 4000 dégâts de magie des ténèbres toutes les 0.5 sec. à tous les ennemis pendant 3 sec. ]], 0, 0, 317571, 11661, 21306, 0, 0, 1, 4, 2, 2, -1, 0},
    [21306] = {21306, "Portail d'outre-monde", [[ Ouvre un portail duquel émerge toutes les 3 sec. une "Substance instable" qui se met à poursuivre une cible aléatoire.
Nécessite 100 points d'énergie des Ténèbres. ]], 0, 0, 317573, 11661, 21309, 21307, 0, 1, 48, 2, 2, -1, 0},
    [21307] = {21307, "Substance instable", [[ La substance instable se met à poursuivre une cible aléatoire et explose à son contact, infligeant 7500 dégâts de magie des ténèbres et laissant derrière elle une zone d'"Obscurité". ]], 559159, 0, 0, 11661, 0, 21308, 0, 2, 48, 2, 2, -1, 84010},
    [21308] = {21308, "Obscurité", [[ Ralentit de 35% tous les ennemis dans un rayon de 5 m. et inflige 8500 dégâts de magie des ténèbres toutes les 1 sec. ]], 0, 0, 317577, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21309] = {21309, "Déferlement des Ténèbres", [[ Provoque une série d'explosions de magie des ténèbres, dont les zones d'effet varient et qui infligent 25000 dégâts de magie des ténèbres ; les cibles touchées commencent à se consumer, subissant 2500 dégâts de magie des ténèbres supplémentaires toutes les 2 sec. pendant 10 sec.
Nécessite 100 points d'énergie des Ténèbres. ]], 0, 0, 317579, 11661, 0, 21310, 0, 1, 48, 2, 2, -1, 0},
    [21310] = {21310, "Zone des ténèbres", [[ Provoque une explosion de magie des ténèbres infligeant 25000 dégâts de magie des ténèbres ; les cibles touchées commencent à se consumer, subissant 2500 dégâts de magie des ténèbres supplémentaires toutes les 2 sec. pendant 10 sec. ]], 0, 0, 317596, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21311] = {21311, "Phase 2 : don d'Yogg-Saron", [[ La deuxième phase du combat débutera lorsque les points de vie du Dévoreur d'esprit Ktraxx tomberont à 50%. ]], 0, 0, 0, 11661, 0, 21312, 0, 2, 0, 2, 2, -1, 0},
    [21312] = {21312, "Flèche d'Obscurité", [[ Inflige instantanément 19000 dégâts de magie des ténèbres et 1000 dégâts de magie des ténèbres supplémentaires toutes les 1 sec. pendant 9 sec. Cet effet se cumule.
Octroie 10 points d'énergie des Ténèbres. ]], 0, 0, 317584, 11661, 21313, 0, 0, 1, 1, 2, 2, -1, 0},
    [21313] = {21313, "Sphère des Ténèbres", [[ Invoque 2 sphères sombres qui libèrent toutes les 2 sec. des amas de ténèbres infligeant 4500 dégâts de magie des ténèbres aux ennemis dans un rayon de 8 m. Les sphères choisissent une cible aléatoire et la poursuivent jusqu'à sa mort. ]], 0, 0, 317586, 11661, 21314, 0, 0, 1, 2, 2, 2, -1, 0},
    [21314] = {21314, "Souffle d'Obscurité", [[ Un souffle de magie des ténèbres infligeant 7500 dégâts de magie des ténèbres toutes les 1 sec. à tous les ennemis pendant 5 sec. ]], 0, 0, 317616, 11661, 21315, 0, 0, 1, 4, 2, 2, -1, 0},
    [21315] = {21315, "Malédiction ancienne", [[ Marque 3 ennemis d'une marque sombre ; à la fin de l'effet, un "Puits d'ombre" se forme. ]], 0, 0, 317594, 11661, 21317, 21316, 0, 1, 32, 2, 2, -1, 0},
    [21316] = {21316, "Puits d'ombre", [[ Une zone de magie sombre infligeant 3000 dégâts de magie sombre toutes les 0.5 sec. et réduisant de 80% les soins reçus par les ennemis. Confère l'immunité à l'effet "Plongée dans l'obscurité". Rayon d'effet : 5 m. ]], 0, 0, 317595, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21317] = {21317, "Zone des Ténèbres", [[ Provoque une explosion de magie des ténèbres infligeant 25000 dégâts de magie des ténèbres ; les cibles touchées commencent à se consumer, subissant 2500 dégâts de magie des ténèbres supplémentaires toutes les 2 sec. pendant 10 sec.
Octroie 10 points d'énergie des Ténèbres. ]], 0, 0, 317596, 11661, 21318, 0, 0, 1, 16, 2, 2, -1, 0},
    [21318] = {21318, "Don d'Yogg-Saron", [[ Invoque les forces résiduelles du dieu ancien, bombardant 5 joueurs d'une grêle de magie sombre infligeant des dégâts à la cible et à tous ses alliés dans le rayon d'effet.
Nécessite 100 points d'énergie des Ténèbres. ]], 0, 0, 317601, 11661, 21321, 21319, 0, 1, 48, 2, 2, -1, 0},
