    [21320] = {21320, "Don d'Yogg-Saron", [[ Le don d'Yogg-Saron inflige à la cible et à tous ses alliés dans un rayon de 8 m. 6000 dégâts toutes les 1 sec. pendant 5 sec. ]], 0, 0, 317602, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21321] = {21321, "Plongée dans l'obscurité", [[ Une explosion dévastatrice d'énergie des ténèbres infligeant 300000 dégâts de magie des ténèbres. Ignore les effets de résistance et d'invulnérabilité.
Nécessite 100 points d'énergie des Ténèbres. ]], 0, 0, 317604, 11662, 0, 0, 0, 1, 48, 2, 2, -1, 0},
    [21322] = {21322, "Séparation des éléments", [[ Applique aux ennemis des "Marques des Ténèbres" ou des "Marques de la Corruption". ]], 0, 0, 317638, 11661, 21330, 21323, 0, 1, 0, 2, 2, -1, 0},
    [21323] = {21323, "Marque des Ténèbres", [[ Applique une marque augmentant les dégâts subis de 5%. Cet effet se cumule. ]], 0, 0, 317639, 11661, 21326, 21324, 0, 0, 0, 2, 2, -1, 0},
    [21324] = {21324, "Ténèbres enveloppantes", [[ Les ténèbres se répandent sur le corps de la victime, entravant lentement ses mouvements. Si elle ne bouge pas continuellement, les ténèbres l'engloutiront entièrement, lui appliquant un "Cocon des Ténèbres". ]], 0, 0, 317642, 11661, 21325, 0, 0, 1, 32, 2, 2, -1, 0},
    [21325] = {21325, "Cocon des Ténèbres", [[ Les ténèbres immobilisent totalement la victime, l'enveloppant dans un cocon pendant 6 sec. ]], 0, 0, 317642, 11661, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21326] = {21326, "Marque de la Corruption", [[ Applique une marque réduisant de 5% l'efficacité des soins reçus. Cet effet se cumule. ]], 0, 0, 317643, 11661, 21329, 21327, 0, 0, 0, 2, 2, -1, 0},
    [21327] = {21327, "Corruption débordante", [[ La Corruption se répand sur le corps de la victime. Si la cible bouge trop activement, la Corruption se propagera rapidement dans son corps, appliquant l'effet "Folie démoniaque". ]], 0, 0, 317644, 11661, 21328, 0, 0, 1, 32, 2, 2, -1, 0},
    [21328] = {21328, "Folie démoniaque", [[ La Corruption a entièrement rempli le récipient, brouillant l'esprit et le sens de l'orientation pendant 6 sec. ]], 0, 0, 317646, 11661, 0, 0, 0, 1, 32, 2, 2, -1, 0},
    [21329] = {21329, "Conflit des éléments", [[ Deux éléments se mélangent dans le corps du joueur, provoquant des poussées magiques infligeant 5000 dégâts toutes les 1 sec. pendant 5 sec. ]], 0, 0, 317647, 11661, 0, 0, 0, 0, 48, 2, 2, -1, 0},
    [21330] = {21330, "Activation : Ténèbres", [[ Active l'effet "Marque des Ténèbres", infligeant 500 dégâts de magie des ténèbres à tous les alliés dans un rayon de 5 m. toutes les 2 sec. pendant 10 sec. pour chaque charge de la marque. ]], 0, 0, 317649, 11661, 21332, 21331, 0, 1, 0, 2, 2, -1, 0},
    [21331] = {21331, "Éclats des Ténèbres", [[ Provoque des éclats de ténèbres, d'un rayon de 8 m., sous chaque ennemi portant la "Marque des Ténèbres". L'éclat s'active après 2 sec., infligeant 15000 dégâts de magie des ténèbres. ]], 0, 0, 317655, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21332] = {21332, "Activation : Corruption", [[ Active l'effet "Marque de la Corruption", infligeant 500 dégâts de magie de feu à tous les alliés dans un rayon de 5 m. toutes les 2 sec. pendant 10 sec. pour chaque charge de la marque. ]], 0, 0, 317652, 11661, 21334, 21333, 0, 1, 0, 2, 2, -1, 0},
    [21333] = {21333, "Éclats de la Corruption", [[ Provoque des éclats de feu de la Corruption, d'un rayon de 8 m., sous chaque ennemi portant la "Marque de la Corruption". L'éclat s'active après 2 sec., infligeant 15000 dégâts de magie de feu. ]], 0, 0, 317658, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21334] = {21334, "Surcharge de la marque des Ténèbres", [[ Pendant 6 sec., charge 3 marques de Ténèbres, infligeant 70000 dégâts de magie des ténèbres répartis sur tous les ennemis dans un rayon de 8 m. À la fin de l'effet, forme un "Puits des Ténèbres". ]], 0, 0, 317661, 11661, 21336, 21335, 0, 1, 48, 2, 2, -1, 0},
    [21335] = {21335, "Puits des Ténèbres", [[ Une zone de magie sombre infligeant 5000 dégâts de magie des ténèbres dans un rayon de 8 m. toutes les 2 sec. ]], 0, 0, 317664, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21336] = {21336, "Surcharge de la marque de la Corruption", [[ Pendant 6 sec., charge 3 marques de Corruption, infligeant 70000 dégâts de magie de feu répartis sur tous les ennemis dans un rayon de 8 m. À la fin de l'effet, forme un "Foyer de Corruption". ]], 0, 0, 317665, 11661, 21338, 21337, 0, 1, 48, 2, 2, -1, 0},
    [21337] = {21337, "Foyer de Corruption", [[ Un foyer de flammes de Corruption infligeant 6500 dégâts de magie de feu dans un rayon de 8 m. toutes les 2 sec. ]], 0, 0, 317668, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21338] = {21338, "Tir de barrage", [[ Ouvre des portails d'où jaillissent de puissants flux magiques, infligeant 12500 dégâts aux ennemis en ligne droite et les repoussant de 10 m. ]], 0, 0, 317685, 11661, 21341, 21339, 0, 1, 48, 2, 2, -1, 0},
    [21339] = {21339, "Tir de barrage des Ténèbres", [[ Ouvre un portail d'où jaillit un puissant flux de Ténèbres, infligeant 12500 dégâts de magie des ténèbres aux ennemis en ligne droite et les repoussant de 10 m. ]], 0, 0, 317669, 11661, 21340, 0, 0, 1, 0, 2, 2, -1, 0},
    [21340] = {21340, "Tir de barrage de la Corruption", [[ Ouvre un portail d'où jaillit un puissant flux de Corruption, infligeant 12500 dégâts de magie de feu aux ennemis en ligne droite et les repoussant de 10 m. ]], 0, 0, 317671, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21341] = {21341, "Coup sismique", [[ Frappe la cible, infligeant 180000 dégâts physiques répartis entre les cibles dans un rayon de 8 m., et ébranle la pièce, projetant tous les ennemis à 10 m. ]], 0, 0, 317673, 11661, 21342, 0, 0, 1, 33, 2, 2, -1, 0},
    [21342] = {21342, "Ombres hurlantes", [[ Inflige 10000 dégâts physiques à tous les ennemis et interrompt leurs incantations pendant 5 sec. ]], 0, 0, 317674, 11661, 21343, 0, 0, 1, 0, 2, 2, -1, 0},
    [21343] = {21343, "Magie déferlante", [[ Frappe l'ennemi de magie pendant 15 sec. Toutes les 3 sec., des "Puits des Ténèbres" ou des "Foyers de Corruption" apparaissent sous la cible, selon la marque qu'elle portait. ]], 0, 0, 317675, 11661, 0, 0, 0, 1, 1, 2, 2, -1, 0},
    [21530] = {21530, "Norigorn", [[ Un mystérieux artefact ancien, une montagne vivante de pierre façonnée selon une logique étrange et inexplicable - certaines pierres semblent n'avoir jamais été touchées par une main, tandis que d'autres paraissent habilement taillées par un maçon pour bâtir une forteresse. L'origine de Norigorn demeure inconnue, et les mages-chercheurs modernes débattent sans fin des principes magiques qui animent ce gardien. Une chose, cependant, fait l'unanimité : Norigorn s'acquitte plus qu'honorablement de sa tâche et peut aisément vaincre même les aventuriers solitaires les plus puissants qui convoiteraient ses trésors. ]], 557969, 0, 0, 11672, 21537, 21531, 0, 1, 0, 2, 2, -1, 70010},
    [21531] = {21531, "Attraction de puissance", [[ La mort des ennemis du lanceur de sorts provoque une résonance des lignes telluriques, lui restituant 1% de ses points de vie toutes les 3 sec. et augmentant sa vitesse d'attaque de 100%. ]], 0, 0, 317620, 11672, 21532, 0, 0, 0, 32, 2, 2, -1, 0},
    [21532] = {21532, "Afflux de puissance", [[ La mort des ennemis du lanceur de sorts provoque une résonance des lignes telluriques, lui restituant 1% de ses points de vie toutes les 3 secondes. ]], 0, 0, 317621, 11672, 21533, 0, 0, 0, 160, 2, 2, -1, 0},
    [21533] = {21533, "Résonance de puissance", [[ La mort des ennemis du lanceur de sorts provoque une résonance des lignes telluriques, augmentant sa vitesse d'attaque de 100% pendant 10 secondes. ]], 0, 0, 317622, 11672, 21534, 0, 0, 0, 0, 2, 2, -1, 0},
    [21534] = {21534, "Décharge en chaîne", [[ Une décharge de foudre jaillit du lanceur de sorts, frappant l'ennemi désigné puis bondissant vers d'autres ennemis à proximité, infligeant 12000 dégâts à chacun. Effectue 4 sauts. Les dégâts de la décharge ne diminuent pas après chaque saut. ]], 0, 0, 317623, 11672, 21535, 0, 0, 0, 0, 2, 2, -1, 0},
    [21535] = {21535, "Poing aiguisé par les vents", [[ Une puissante attaque de mêlée infligeant 50000 dégâts physiques à l'ennemi, le mutilant et transperçant son armure. La valeur d'armure de l'ennemi diminue de 12%, et sa réserve maximale de points de vie de 10%. Se cumule jusqu'à 8 fois. ]], 0, 0, 317273, 11672, 21536, 0, 0, 0, 33, 2, 2, -1, 0},
    [21536] = {21536, "Taillade fulgurante", [[ Le lanceur de sorts charge son corps de décharges électriques, s'accélérant considérablement pendant un court instant, ce qui lui permet d'exécuter une attaque circulaire dévastatrice infligeant 40000 dégâts physiques à tous les ennemis dans un rayon de 10 mètres. ]], 0, 0, 317274, 11672, 0, 0, 0, 0, 32, 2, 2, -1, 0},
    [21537] = {21537, "Phase 1 : Appel des éléments", [[ Norigorn entre en combat contre ceux qui ont empiété sur son territoire, puisant dans les sources des éléments primordiaux pour se renforcer. ]], 0, 0, 0, 11672, 21547, 21538, 0, 1, 0, 2, 2, -1, 0},
    [21538] = {21538, "Renaissance de la terre", [[ Invocation d'un pilier de protection de la Terre. ]], 0, 0, 317266, 11672, 21541, 21539, 0, 0, 0, 2, 2, -1, 0},
    [21539] = {21539, "Aiguille de la Terre", [[  ]], 565122, 0, 0, 11672, 0, 21540, 0, 0, 0, 2, 2, -1, 83221},
    [21540] = {21540, "Bienveillance de la Forteresse", [[ Empoisonnées par le sang versé, les terres ont entendu l'appel, restituant à Norigorn 500000 points de vie toutes les 2 sec. ]], 0, 0, 317301, 11672, 0, 0, 0, 0, 34, 2, 2, -1, 0},
    [21541] = {21541, "Renaissance du feu", [[ Invocation d'un pilier de protection du Feu. ]], 0, 0, 317267, 11672, 21544, 21542, 0, 0, 0, 2, 2, -1, 0},
    [21542] = {21542, "Aiguille du Feu", [[  ]], 565123, 0, 0, 11672, 0, 21543, 0, 0, 0, 2, 2, -1, 83222},
    [21543] = {21543, "Persévérance du Feu", [[ La parenté avec les profondeurs enflamme la rage et la colère jadis éteintes de Norigorn, augmentant de 20% les dégâts qu'il inflige. ]], 0, 0, 317302, 11672, 0, 0, 0, 0, 0, 2, 2, -1, 0},
    [21544] = {21544, "Renaissance des vents", [[ Invocation d'un pilier de protection des Vents. ]], 0, 0, 317268, 11672, 0, 21545, 0, 0, 0, 2, 2, -1, 0},
    [21545] = {21545, "Aiguille des Vents", [[  ]], 565124, 0, 0, 11672, 0, 21546, 0, 0, 0, 2, 2, -1, 83223},
    [21546] = {21546, "Infinité des Vents", [[ Les vents enveloppent Norigorn, lui accordant protection et sérénité, réduisant de 30% les dégâts qu'il subit. ]], 0, 0, 317303, 11672, 0, 0, 0, 0, 34, 2, 2, -1, 0},
    [21547] = {21547, "Phase 2 : Acceptation de la nature", [[ Ayant subi d'importants dégâts, Norigorn invoque à son aide des créatures de la terre, puis devient invulnérable et commence à absorber l'essence circulant à travers les lignes telluriques. ]], 0, 0, 0, 11672, 21552, 21548, 0, 1, 0, 2, 2, -1, 0},
    [21548] = {21548, "Acceptation de la nature", [[ Le lanceur de sorts attire l'énergie d'une ligne tellurique dissimulée sous terre, puis se met à l'absorber pendant 60 sec. Pendant l'absorption, le lanceur de sorts est totalement invulnérable, mais ne peut rien faire d'autre que maintenir cette absorption.
